WordHunterWoW_QuestEN[89559] = { title = "Reasonless Worship", description = "Ahead is an old shrine. Nobody knows anymore what we worshipped there or why, but it was a place my mother loved.\n\nIt would honor her if we put a stone from it on de pyre with her.", objectives = "" }
WordHunterWoW_QuestEN[89560] = { title = "A Quiet Farewell", description = "Now we set up de bonfire to burn de body. Destroying the body means it cannot be used by de Vilebranch for evil and makes sure de spirit finds rest.\n\nIt still chills me how quiet she is now.\n\nThe tribe should be gatherin' down at de Funerary Coast.", objectives = "" }
WordHunterWoW_QuestEN[89561] = { title = "Wrapped Up", description = "Shad'anis has told me about you--a fleshling with the ability to travel to Untethered Space. How do you accomplish such a feat? Wait--let me deduce.\n \nIt must be those wraps you wear as a cloak. They have been modified by a Reshii Ribbon. I have not seen such a thing since the Devouring War. Very nice. Classic.\n \nDo you want classic? Or do you want powerful? I can enhance your Reshii Wraps with modern technomancy techniques to better face the dangers of Untethered Space.", objectives = "" }
WordHunterWoW_QuestEN[89565] = { title = "The Path of Mourning", description = "Hash'ura, could I ask for your aid?\n\nMy mother passed recently, and I'm de one responsible for performin' her death rituals. It's a lotta work for one person to do.\n\nMost would get help from their family, but I don't have any left. Can you help me?", objectives = "" }
