WordHunterWoW_QuestEN[89683] = { title = "Infinite Research: Time to Raid, Royal Athenaeum", description = "We require information about how multiple timerunners and their artifacts interact when faced with powerful opposition.\n\nSeek out others to help you conquer Royal Athenaeum.", objectives = "" }
WordHunterWoW_QuestEN[90087] = { title = "Distance Tracker (DNT)", description = "Testing distance tracking. Do not translate. Not player facing.", objectives = "" }
WordHunterWoW_QuestEN[90093] = { title = "Prey Contract: Murloc Shadowhunter", description = "A MURLOC SHADOWHUNTER has been spotted in Zul Aman!\n\nDifficulty: Hard\n\nAffixes: Mark of the Prey\n\nYour target will occasionally mark you, decreasing your damage done and increasing damage taken.", objectives = "" }
WordHunterWoW_QuestEN[90094] = { title = "Echo of the Hunt", description = "Haranir are fierce and ferocious--cunning and canny. In time, we became the most feared beasts upon the mountain.\n\nA great many wise and powerful beasts roamed the hills of our old mountain. But in time, we came to master them all.\n\nToday, you shall hunt as we once did.", objectives = "" }
WordHunterWoW_QuestEN[90095] = { title = "Echo of the Call", description = "When the haranir began to grow restless, they looked to new sources of purpose. Some cast their gazes upward, toward the stars and the moon. Others, such as the Hara'ti, heard a call from deep within the world.\n\nThe moment the first of the Hara'ti heard the Song echoing from the roots, we knew that we had found a new purpose. We would seek out the source of the Song, and discover the truth of it for ourselves.\n\nBut it would be a difficult road. Strange stone monsters sought to block our path.", objectives = "" }
WordHunterWoW_QuestEN[90096] = { title = "Infinite Research: Worldly Deeds", description = "All across the Broken Isles there are people in need. They search for hope but are hard pressed to find any. You can be that hope.\n\nSeek out those in peril in the Broken Isles and be the champion they so desperately need.\n\nIt is through such acts that legends are made.", objectives = "" }
WordHunterWoW_QuestEN[90097] = { title = "Infinite Research: Invasion Points", description = "The Legion does not fight conventionally. They deceive, manipulate, and undermine their opposition at every turn.\n\nThere are no battle lines against the Legion. They will open rifts at a weak point and then spill out of it sowing death and destruction. When they invade, it is on their terms.\n\nHowever, this strategy is not invincible. Potent champions, able to move and react swiftly, can stop these invasions at their source. Stop the Legion Invasion. Show people that the Legion can be defeated.", objectives = "" }
WordHunterWoW_QuestEN[90098] = { title = "Infinite Research: Greater Invasion Points", description = "Once the Legion has sown confusion and chaos, then they will begin their real assault. Huge invasion rifts will open and the Legion will march forth in great numbers. The defenders, scattered to protect against smaller rifts, will lack sufficient strength anywhere to stop them.\n\nThat is when champions like you are most needed.\n\nSeek out one of the Legion's major invasions and throw everything you have at it. \n\nShow the people that with enough determination you can cancel the apocalypse.", objectives = "" }
WordHunterWoW_QuestEN[90099] = { title = "Infinite Research: Combat Studies, Rare", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a rare study, so focus on fighting rare opponents so that we can get a better understanding of your abilities.\n\nAnd remember, this is for the greater good.", objectives = "" }
WordHunterWoW_QuestEN[90100] = { title = "Infinite Research: Combat Studies, Rare Elites", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a rare elite study, so focus on fighting rare elite opponents so that we can get a better understanding of your abilities.\n\nAnd remember, this is for the greater good.", objectives = "" }
WordHunterWoW_QuestEN[90101] = { title = "Infinite Research: Terrors of the Broken Isles", description = "It is time to put both you and your artifact to the test.\n\nSeek out a Terror of the Broken Isles and defeat them.\n\nI am certain that, no matter the outcome, you will provide us with much to think about. I will be watching with great interest.", objectives = "" }
WordHunterWoW_QuestEN[90102] = { title = "Infinite Research: Champion of the Broken Isles", description = "Our research suggests that power is only part of the equation--what one does with it is also of great importance.\n\nThe people of the Broken Isles need a champion. Come to their aid and drive the Legion from their shores and your legend will grow.\n\nWhere you choose to start is up to you--the Legion is everywhere, so one place is just as good as another.", objectives = "" }
WordHunterWoW_QuestEN[90103] = { title = "Infinite Research: Champion of the Order Hall", description = "Your legend will not be satisfied with just being another {class}--you must prove yourself to be more.\n\nProve yourself within your Order Hall. Gain the respect of your peers, and become the first among equals.\n\nIn this way we may yet determine what limits you have and whether it is a person, or their artifact, that defines the legend.", objectives = "" }
WordHunterWoW_QuestEN[90108] = { title = "Infinite Research: Artifact Collector", description = "As we study this timeline and your effect upon it, a question has been raised--what would be different if you had a different artifact?\n\nSeek out a new artifact and let us see whether the first choice you made was good, or great.", objectives = "" }
WordHunterWoW_QuestEN[90109] = { title = "Infinite Research: Clear the Skies", description = "Manipulating time is not without its risks or its rewards.\n\nThe strain on this timeline has produced numerous residual time motes through the Broken Isles. It would be irresponsible not to clean them up.\n\nHowever, there is opportunity here. If you were to gather these motes, then their latent infinite power would be bestowed upon you instead.\n\nWe can clean up the timeline and enhance our research at the same time.", objectives = "" }
WordHunterWoW_QuestEN[90110] = { title = "Infinite Research: Gather Timewarped Samples", description = "The fraying of this timeline has had some interesting effects on plants and stone. We would like to study them.\n\nGather samples of timewarped herbs and ores from around the Broken Isles and being them back for analysis.", objectives = "" }
WordHunterWoW_QuestEN[90111] = { title = "Infinite Research: Combat Studies, Demonology", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a demonology study, so focus on fighting demonic opponents so that we can get a better understanding of your abilities.\n\nAnd remember, this is for the greater good.", objectives = "" }
WordHunterWoW_QuestEN[90112] = { title = "Infinite Research: Combat Studies, Elite", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be an elite study, so focus on fighting elite opponents so that we can get a better understanding of your abilities.\n\nAnd remember, this is for the greater good.", objectives = "" }
WordHunterWoW_QuestEN[90115] = { title = "Infinite Research: Combat Studies, Groverunner", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a study of your attunement to the forest, so focus on fighting opponents using the power of nature.\n\nAnd remember, this is for the greater good.", objectives = "" }
WordHunterWoW_QuestEN[90119] = { title = "test", description = "", objectives = "" }
WordHunterWoW_QuestEN[90122] = { title = "Eliminate Xy'vox the Twisted", description = "<Use the Xy'vox Refuge Dampener to reveal and eliminate Xy'vox the Twisted.>", objectives = "" }
WordHunterWoW_QuestEN[90123] = { title = "Eliminate Hollowbane", description = "<Use the Hollowbane Portal Key to reveal and eliminate Hollowbane.>", objectives = "" }
WordHunterWoW_QuestEN[90124] = { title = "Eliminate Shatterpulse", description = "<Use the Shatterpulse Cell Key to reveal and eliminate Shatterpulse.>", objectives = "" }
WordHunterWoW_QuestEN[90125] = { title = "Eliminate Purple Peat", description = "<Use the Purple Peat Cell Key to reveal and eliminate Purple Peat.>", objectives = "" }
WordHunterWoW_QuestEN[90126] = { title = "Eliminate Grubber", description = "<Use the Grubber Lure to reveal and eliminate Grubber.>", objectives = "" }
WordHunterWoW_QuestEN[90127] = { title = "Eliminate Arcana-Monger So'zer", description = "<Use the Arcane Lure to reveal and eliminate Arcana-Monger So'zer.>", objectives = "" }
WordHunterWoW_QuestEN[90467] = { title = "Tales of the Sky", description = "Wait a minute... You're no rutaani at all! Are you one of those \"outsiders\" that Saku and Orkon keep talking about?\n\nOh! I just had a great idea. Did you know that the Goddess used to have a pet? Rumor has it that when the Goddess disappeared, Aln'sharan was SO sad that he flew up into the highest roots of Harandar, never to be seen again. But every so often, he goes looking for food... And his scales fall as skyglass!\n\nI wanna gather some. It's my dream to see Aln'sharan firsthand! Will you help me?", objectives = "" }
WordHunterWoW_QuestEN[90468] = { title = "Ugh, Chores!", description = "Okay, so I may have a DIFFERENT thing that I'm supposed to be doing in the Cascades, too. It's my turn to gather saptor fronds for stew. It's such a pain. Not only are saptor fronds horribly bitter, but the saptors are barely even fun to hunt! They don't even make your blood flow that fast before they die.\n\nBut hey! You probably don't get to fight saptors as often as I do. Maybe while you're looking for skyglass, you could gather some up for me? You know... while you're in the area.", objectives = "" }
WordHunterWoW_QuestEN[90469] = { title = "Carry On, Wayward Kuri", description = "Oh, that Kuri. She holds tightly to our ancient traditions and tales... perhaps too tightly.\n\nThere is a difference between holding reverence for our ancient ways and chasing them into dangerous caves. I fear she might bite off more than she can chew in her search for Aln'sharan.\n\nWon't you go after her? She seems to trust you, now that she sees you as her co-conspirator in this quest. Please bring her home safely.", objectives = "" }
WordHunterWoW_QuestEN[90470] = { title = "Skyglass Scavenging", description = "The adults find all sorts of stuff in the caves around here that we use back at the village. A lot of the critters that live in the caves like to gather skyglass, in particular. I guess they think it's shiny.\n\nThat's good for us, though! It means we can go and get a bunch of skyglass. Go in there and make sure the coast is clear, and then I'll come in and gather up as much as I can carry!\n\nAt this rate, we'll be able to summon Aln'sharan in no time.", objectives = "" }
WordHunterWoW_QuestEN[90474] = { title = "The Legend of Aln'sharan", description = "This is it! We have all the skyglass we can carry.\n\nThe legends say that Aln'sharan cries crystal tears to mourn the missing Goddess. Maybe if we give the crystals back to him, he won't be so sad? Maybe then he'll appear for us!\n\nMeet me back at the village. I think I know the perfect place to make our offering.", objectives = "" }
WordHunterWoW_QuestEN[90481] = { title = "I Have a Permit", description = "These Witherbark youths are telling us we can't stay here.\n\nBut I've been talking to one of their elders for months to be sure we'd have permission to set up camp and explore. I even have copies of all the letters!\n\nCan you find Elder Ren'zen in Witherbark Village and show him his letter of approval?", objectives = "" }
WordHunterWoW_QuestEN[90482] = { title = "Cuisine Connection", description = "Dis \"seeker\" has been askin' a lot of questions about de foods we eat.\n\nIt sounds like these tortollans like to eat poisonous foods. De Witherbark do as well. There are many foods we eat that could kill us if not treated properly.\n\nGo collect zapgut eel stomachs and blisterskin kelp. I'd like to test dis turtle's tongue.", objectives = "" }
WordHunterWoW_QuestEN[90483] = { title = "A Witherbark Story", description = "The Witherbark say they have a lot of stories to tell, but I've heard two and BOTH involved a sparring match!\n\nPlease, can you ask the Witherbark here for stories? My old bones can't take another reenactment!", objectives = "" }
WordHunterWoW_QuestEN[90484] = { title = "Sightseeing Stegadon", description = "Wow, your armor is sooooo cool!\n\n<Trishe stares, slack-jawed.>\n\nOh, have you seen my friend Steggy? She was here with me, but then there were all these pretty bugs and things, and she ran off after them, and I was too slow to follow her.\n\n<Trishe pouts.>\n\nI'm s'posed to watch Steggy. I'm response-able! And now you're response-able for finding her, okay?", objectives = "" }
WordHunterWoW_QuestEN[90485] = { title = "Afterthought Artifacts", description = "This location is ideal for finding artifacts. Searching through the rubble at the bottom of that lake could reveal many treasures.\n\nIf you have a moment, you're welcome to take a look around yourself. Bring me anything you find and we'll see if it's valuable.", objectives = "" }
WordHunterWoW_QuestEN[90486] = { title = "Dangerous Delicacies", description = "A Witherbark troll could survive eatin' each of these ingredients raw, but dey would need aid.\n\nTogether, de ingredients would be deadly. We're going to cook dem into one dish.\n\nDon't worry. I'll show you how to take out enough poison so it tastes good AND has paralytic effects.", objectives = "" }
WordHunterWoW_QuestEN[90493] = { title = "The Heart of Tranquillien", description = "We can't let the Twilight's Blade get away with this. There are innocent citizens all over town who had nothing to do with this cult. You heard the governor: anyone who doesn't join will be executed.\n\nI won't stand for that.\n\nGo--aid any civilians you can find. Get them out of harm's way. If they're being attacked, take their attacker down. Tranquillien will not fall under my watch.", objectives = "" }
WordHunterWoW_QuestEN[90494] = { title = "The Missing Magister", description = "Umbric went to chase down Antenorian when the fighting broke out, but nobody has seen him since. \n\nI trust him to hold his own, but between Kasiea's death and Antenorian's betrayal, I worry he may be so set on revenge that he won't see an attack if one happens. Can you find him for me?\n\nI'll stay here and make sure these civilians remain safe.", objectives = "" }
WordHunterWoW_QuestEN[90509] = { title = "The Traitors of Tranquillien", description = "Some of the town's most respected citizens, traitors?\n\nHow long has the Twilight's Blade been here? How many scouts have gone missing? Crimes gone unreported? Innocents recruited by those they thought they could trust?\n\nThey must be stopped. Cut down the traitors. Show them that Tranquillien is no home for cultists.", objectives = "" }
WordHunterWoW_QuestEN[90517] = { title = "My Part of the Deal", description = "The threat of the Shadowguard to Eco-Dome: Primus is over. My Reshii Ribbon is no longer needed to protect this asset. Take it. Use it wisely. Protect the greatest investment of all--our existence.\n\nStay focused! The Harbinger has already driven off one member of your team. Once you get enough Reshii Ribbons, you still need to fight Dimensius. Find allies who will stand with us, in addition to artifacts.", objectives = "" }
WordHunterWoW_QuestEN[90533] = { title = "Go Get Orweyna!", description = "Hey! Champ!\n\nLook, I swear I'm glad to see ya. I'm just in a little bit of a diplomatic situation here.\n\nCan you go get Orweyna and bring her back here? See if she'll talk this beast into letting me go?\n\nI'm not an elekk plushie, for cryin' out loud.", objectives = "" }
WordHunterWoW_QuestEN[90534] = { title = "The Home of the Haranir", description = "I am eager to show Monte my home, but I know it is very different from what he is used to.\n\nCome with us as he meets my people.", objectives = "" }
WordHunterWoW_QuestEN[90535] = { title = "Leave Your Mark", description = "One thing that is very important to the haranir is our past. Some may remove their ability to hear the Goddess, but we are all connected to who came before us.\n\nYou and Gazlowe are a part of our history now. You have earned the right to leave your mark here in the Den, for as long as the Den remains.\n\nGo, touch the wall with your painted hand, and know that you touch the same stone as generations before you.", objectives = "" }
WordHunterWoW_QuestEN[90537] = { title = "Late Bloomers", description = "It is good to see you again, {name}. Orweyna told me that you might be able to help me with something.\n\nA group of rutaani were due to arrive here earlier today, but they're late. They're coming up from Blooming Terrace with my mentor, Ru'gar, and I am worried they've had trouble on the road.\n\nWill you scout along the road from here down to the Terrace? I'll come up from there and we can meet on the way if we find nothing.", objectives = "" }
WordHunterWoW_QuestEN[90538] = { title = "Prey Contract: Zealous Crusader", description = "A ZEALOUS CRUSADER has been spotted in Eversong!\n\nDifficulty: Hard\n\nAffixes: Grounded!\n\nUnable to use mounts while inside your active Prey Area.", objectives = "" }
WordHunterWoW_QuestEN[90540] = { title = "Rutaani Rescue", description = "Over the hill north of here is a fungarian village, Fungal Cleft. I believe the missing rutaani have been taken there.\n\nThe fate that awaits them is a brutal one if we do not get them back quickly. Usually, fungarians favor hosts that are already dead for their reproductive purposes. The ones here are strangely vicious, however. I have seen some mushroom-covered animals and rutaani who are still moving around! It is unnatural.\n\nGo to Fungal Cleft and see if you can rescue the missing travelers.", objectives = "" }
WordHunterWoW_QuestEN[90544] = { title = "Thief at Bark", description = "<Luma stands in front of you, ears perked, thankful for your help.\n\nShe lets out a short bark, tail wagging once before trotting a few steps forward, then pausing.\n\nGlancing back, Luma waits expectantly. Her body language pleads, \"Come on, follow me!\">", objectives = "" }
WordHunterWoW_QuestEN[90545] = { title = "A Reel Problem", description = "An essential component of the Oasis ecosystem is the aquatic life within our small lake. \n\nIt appears that artificial organisms known as Hyrobites are in the lake. Originally introduced to remove toxins in the water, their continued presence threatens the equilibrium of the water.\n\nPlease remove these mechanical fish immediately!", objectives = "" }
WordHunterWoW_QuestEN[90546] = { title = "Missing Paladins", description = "Some of our brothers and sisters in the Light were responding to a request for help by the Magisters at the Sanctum of the Moon. Apparently the Twilight's Blade has been seen lurking in the area.\n\nWe expected to hear back from them awhile ago, but we've heard nothing.\n\nGiven the strength of the party that went, Salandria and I wanted some additional backup before we looked into the issue. Care to lend a hand?", objectives = "" }
WordHunterWoW_QuestEN[90547] = { title = "Missing Paladins", description = "Some of our brothers and sisters in the Light--including my friend Dawnheart--were responding to a request for help by the Magisters at the Sanctum of the Moon. Apparently the Twilight's Blade has been seen lurking in the area.\n\nWe expected to hear back from them awhile ago, but we've heard nothing.\n\nGiven the strength of the party that went, Taelia and I wanted some additional backup before we looked into the issue. Care to lend a hand?", objectives = "" }
WordHunterWoW_QuestEN[90548] = { title = "Twilight Missive", description = "We need to figure out what the Twilight's Blade is trying to do here. We also need to get rid of these cultists so the Magisters can get back to their work building runestones.\n\nTake out as many cultists as you can. See if any of them are carrying information we can use.", objectives = "" }
WordHunterWoW_QuestEN[90549] = { title = "Signs of the Struggle", description = "The Twilight's Blade are acting boldly in their takeover here. None of these Magisters have any information for us.\n\nWe'll hold this end of the bridge and protect any Magisters who escape. You get in there and look for signs of the missing paladins. Were they taken? Did they put up a fight, or were they ambushed? Are they still armed?\n\nI have a bad feeling we are running out of time.", objectives = "" }
WordHunterWoW_QuestEN[90550] = { title = "A Somber Sun", description = "<The corpse of this Blood Knight has been horribly mangled and tainted by Void magic. He put up a fight, but was unable to survive.\n\nSalandria will want to know of this.>", objectives = "" }
WordHunterWoW_QuestEN[90551] = { title = "Captured Information", description = "We need to find out where the paladins were taken. Easiest way to do that is ask... under a bit of duress.\n\nFind an isolated target, beat them down, and then drag them to the hollow on the other side of the Sanctum. Taelia and I will get the civilians to safety and meet you there.", objectives = "" }
WordHunterWoW_QuestEN[90552] = { title = "Interrogation", description = "We need to know where Dawnheart and the others were taken. This one doesn't seem to want to talk... but we can fix that.", objectives = "" }
WordHunterWoW_QuestEN[90553] = { title = "Executing the Blades", description = "Those monsters will pay for what they have done!\n\nTake out any Twilight's Blade cultists you see. We'll scour them from Eversong for good!", objectives = "" }
WordHunterWoW_QuestEN[90554] = { title = "Leave Ashes in Your Wake", description = "We need to make it clear to these cultists that they aren't welcome.\n\nTear down their banners, and destroy their books and supplies. Do whatever you can to wreck their camp!", objectives = "" }
WordHunterWoW_QuestEN[90555] = { title = "Blessing of Freedom", description = "Our friends are being held in this area. I have no idea what state we'll find them in, but I pray they are at least alive.\n\nHelp me find and free our missing paladins in the Ruins of Deatholme.", objectives = "" }
WordHunterWoW_QuestEN[90556] = { title = "Cutting off the Head", description = "We'll crush their leader! For justice and the Light!", objectives = "" }
WordHunterWoW_QuestEN[90568] = { title = "Unlikely Friends", description = "This old Witherbark pot you found is quite interesting.\n\nI've made a series of notes on its construction and use, but now it's time we speak to Elder Ren'zen. The pot should be returned to him. And he can fill in the gaps in the pot's story!\n\nLet's speak with him in the village.", objectives = "" }
WordHunterWoW_QuestEN[90569] = { title = "Back in the Bag", description = "What a mess this is. The sack you found was supposed to be filled with seeds. They're part of an important cultivation project that Ru'gar was working on.\n\nIt appears the fungarians made off with the seeds when they captured the rutaani.\n\nWhile you're looking for the rutaani, see if you can recover the seeds that were stolen.", objectives = "" }
WordHunterWoW_QuestEN[90570] = { title = "To the Ruins of Deatholme", description = "Thanks to our \"friend\" here, we know the missing paladins were taken to Deatholme. We have to find them before it's too late! \n\nSalandria and I will meet you there.", objectives = "" }
WordHunterWoW_QuestEN[90571] = { title = "The Lay of the Beast", description = "Your friend's scheme to blow up the Nexus-Point was adorable. You all looked so determined, I didn't have the heart to tell you how simple the solution really is.\n\nThe Mantle of Predation will allow you to enter the Nexus-Points and weaken the storm. Alas, it's claiming the Mantle that will truly test you.\n\nBorrow my pet--see through his eyes. I'll show you who you'll steal the Mantle from.", objectives = "" }
WordHunterWoW_QuestEN[90573] = { title = "Fortify the Runestones: Magisters", description = "We placed a number of runestones throughout Eversong Woods, each one charged with protective arcane magic intended to ward off the Lightbloom.\n\nWhile highly effective, the runestones require an immense amount of power to function. They must be regularly fed with latent arcana lest they weaken.\n\nAs Magisters, it is our duty to maintain the runestones--especially when the eyes of this Haven are upon us. Recharge their arcane power and defend them from those who would threaten us.", objectives = "" }
WordHunterWoW_QuestEN[90574] = { title = "Fortify the Runestones: Blood Knights", description = "The Magisters placed a number of runestones throughout Eversong Woods, each one charged with protective arcane magic intended to ward off the Lightbloom.\n\nNaturally, the runestones require an immense amount of power to function. They can be fed with latent arcana, but that power draws enemies seeking to claim it.\n\nAs Blood Knights, it is our duty to defend the runestones--especially when the eyes of this Haven are upon us. Recharge their arcane power and defend them from those who would threaten us.", objectives = "" }
WordHunterWoW_QuestEN[90575] = { title = "Fortify the Runestones: Farstriders", description = "The Magisters placed a handful of runestones across Eversong, each one charged with arcane magic that wards off the Lightbloom.\n\nAs you might guess, the runestones require a huge amount of power to function. The Magisters feed them with latent arcana, but that kind of power draws a lot of attention. Bad attention.\n\nAs Farstriders, it's our duty to defend Eversong from those kinds of threats--especially when the Haven is looking at us. Go recharge the runestones and fight off whatever tries to stop you.", objectives = "" }
WordHunterWoW_QuestEN[90576] = { title = "Fortify the Runestones: Shades of the Row", description = "Have you seen the runestones out in Eversong? Huge rocks full of arcane magic that ward off the Lightbloom.\n\nI'm not the magic type, but I know an opportunity when I see one. Those runestones need a lot of power to work. If we help keep them charged, there are a lot of people who would owe us favors--and favors are even better than gold.\n\nHere's the plan: I help you get some latent arcana, you drop it into the runestones, beat up whatever tries to stop you, then we bask in the accolades. Deal?", objectives = "" }
WordHunterWoW_QuestEN[90601] = { title = "Gathering Glowshrooms", description = "Ru'gar used to tell me about how he'd sneak into the nearby cave to harvest glowshrooms. They seemed to be integral to the development of the tla'tak seeds he was cultivating. Will you collect some of the mushrooms within?\n\nOh, and Ru'gar mentioned that the mushrooms have strange properties when harvested. I'm not sure what he meant by that, but maybe stay on your toes.", objectives = "" }
WordHunterWoW_QuestEN[90602] = { title = "Gomphusta", description = "I would ask one last thing of you. I've heard quite a few of the fungarians mention their leader, Gomphusta. It seems he's behind the uptick in their violence and the reason they're stealing the seeds.\n\nWhile you're in the cave, find him and take him out. Without Gomphusta pulling the strings, the other fungarians will be thrown into chaos and won't be able to organize ambushes as well.", objectives = "" }
WordHunterWoW_QuestEN[90615] = { title = "Be Grudge You", description = "You look... different! Ever be to Grudge Pit?\n\nGrudge Pit is great place! Full of fighting and cheering and fungarians. Also decaying!\n\nBoletus is always look for strong creatures to be kill in Grudge Pit. Or for making others be kill.\n\nAre strong creature? Should go to Pit!", objectives = "" }
WordHunterWoW_QuestEN[90616] = { title = "You Strong?", description = "You look strong.\n\nShould test yourself in our arena.\n\nSee how you compare to strong fungarians.", objectives = "" }
WordHunterWoW_QuestEN[90617] = { title = "A Few Fun Guys", description = "You are very strong, {name}.\n\nWill teach fungarians to fight?\n\nMuch we could learn from you.\n\nMany fungarians watch battle.\n\nAsk if they want to be strong in Pit.", objectives = "" }
WordHunterWoW_QuestEN[90619] = { title = "What Doesn't Kill Them", description = "Have team, now are ready to fight.\n\nTake your team to empty area. Practice fight, and see what can do.", objectives = "" }
WordHunterWoW_QuestEN[90620] = { title = "To the Ring", description = "TeamName? Not bad. I like!\n\nYou and the TeamName head on down, and we say words.\n\nYou fight Spore Storm. If beat, fight Cap Clash.\n\nIf beat, fight Fungus Force.\n\nAlways-winners are Glow Guard. You won't beat.\n\nNo run out! Run out is big, big lose.", objectives = "" }
WordHunterWoW_QuestEN[90621] = { title = "Tiny Heroes' Journeys", description = "You taught them. Why did they run out?\n\nAll fungarians were excited to see if a {race} could teach fungarians for be strong.\n\nYou try one more time, okay?\n\nFirst do what need to get them ready.", objectives = "" }
WordHunterWoW_QuestEN[90622] = { title = "Not-Yet Defeated Champions", description = "{name}, the PHTeamname look stronger now! More ready. Hope they won't run again.\n\nNext fight is against Glow Guard. Glow Guard always never lose.\n\nHope your training makes fight better, before TEAMNAME lose.\n\nWill be fun for watch!", objectives = "" }
WordHunterWoW_QuestEN[90630] = { title = "A Small Bundle of Crystals", description = "", objectives = "" }
WordHunterWoW_QuestEN[90634] = { title = "A Small Bundle of Crystals", description = "", objectives = "" }
WordHunterWoW_QuestEN[90638] = { title = "A Bundle of Crystals", description = "", objectives = "" }
WordHunterWoW_QuestEN[90659] = { title = "Something Borrowed", description = "Now that you have your infinite bronze, we just need to select the right artifact for you, shape the bronze into a suitable simulacrum of the weapon, and then reach through a temporal knot and swap them.\n\nNo one will be the wiser.\n\nAll we have to do is remember to reclaim the simulacrum in this timeline and everything will work itself out.\n\nLet's start by selecting your specialization, that'll determine which artifact we'll be borrowing.", objectives = "" }
WordHunterWoW_QuestEN[90661] = { title = "Dastardly Duos", description = "", objectives = "" }
WordHunterWoW_QuestEN[90663] = { title = "Stealing What is Ours", description = "Ve'nari has called in a lot of favors to get the Oasis reclamation effort off the ground. Plenty of Tazavesh merchants have donated to the cause, though some have seen fit to help themselves instead.\n\nA large shipment of stasis-sealed items was stolen from the docks by an untrustworthy importer. I could use someone of your skill to recover the shipment.", objectives = "" }
WordHunterWoW_QuestEN[90666] = { title = "A Bundle of Crystals", description = "", objectives = "" }
WordHunterWoW_QuestEN[90667] = { title = "Enchanted Runed Ethereal Crest", description = "", objectives = "" }
WordHunterWoW_QuestEN[90669] = { title = "Gold is Gold", description = "Hey! You there.\n\n<Sarvi beckons you closer and lowers her voice.>\n\nYou looking for work? A Magister gave me five gold to find an adventuring type to do some sort of job for him. He said if the person gets it done, I get five more. That'll feed me for months.\n\nYou fit the bill. If you want to try to get paid too, he has a study over by the harbor. Real fancy place--you can't miss it. The guy's name is Aradis.", objectives = "" }
WordHunterWoW_QuestEN[90690] = { title = "Charge of the Vanguard", description = "Turalyon reports the Vanguard of the Light is prepared to march on Xal'atath's stronghold.\n\nWould that I could join you for the charge. I will keep my retainer of forces here to maintain the defense of the Sunwell and Silvermoon while you take the fight to our enemy. \n\nMuster in the Voidstorm, take the fight to the Voidspire, and bring an end to this great enemy. Good hunting.", objectives = "" }
WordHunterWoW_QuestEN[90701] = { title = "Cowardly Cheery Bombs", description = "Goblins love bombs, I get that. But does EVERYTHING have to blow up?\n\nDo me a favor: In the next Dastardly Duos match you enter, find a cheery bomb inside one of the wooden tree and planter props.\n\nAfter you find the bomb, but before it  \"blows up\"... smack it for me. Don't worry, they're cowards.", objectives = "" }
WordHunterWoW_QuestEN[90705] = { title = "Lorewalking", description = "Are you curious about your world's history? Would you like to learn more?\n\nLi Li Stormstout has started her Lorewalking apprenticeship. With all her travels, she has gathered many stories of important events and figures across Azeroth and beyond and is eager to share them!\n\nPay her a visit in your capital city!", objectives = "" }
WordHunterWoW_QuestEN[90718] = { title = "Request of the Arcantina", description = "Ah, {name}!\n\nI hear you have a standing invitation to Archmage Khadgar's... Arcantina?\n\nCan you go there for me and bring this missive to the Archmage? I need to source reagents for the sheer volume of telemancy spells I have been asked to conjure.\n\nMagister's Terrace has been an excellent source up until recent events but really I need the Kirin Tor to loan me some of their harder to find ingredients.", objectives = "" }
WordHunterWoW_QuestEN[90719] = { title = "Borrowing Corruption", description = "Adventurer, I have made an amazing discovery. \n\nAnalyzing the memories from the time I have discovered that I might be able to recreate the corruption effects that have been wielded in the past. Albeit in a much more controlled way. \n\nI will need you gather some black blood residue from defeating the bosses of the Corrupted or Lost areas of the map and a few more of the displaced corrupted mementos.", objectives = "" }
WordHunterWoW_QuestEN[90724] = { title = "The Broken Sky", description = "All those people. Our army. Our heroes. Our leaders.\n\nGone.\n\nWe are exposed here. Umbric's tether saved us, but we need to ensure we survive this. Report to Lor'themar and tell him what transpired in the Voidspire. I will get Umbric to safety and learn what I can here.", objectives = "" }
WordHunterWoW_QuestEN[90729] = { title = "Win-Win Situation", description = "Not everything you recovered yesterday was mine, but let's be honest--we're going to keep it anyway!\n\nXy'daz has been ripping people off for years. It's his turn to take a loss!\n\nNow, this can work in both our favors. You sell off half of the leftover goods for me, and I'll let you keep the rest!", objectives = "" }
WordHunterWoW_QuestEN[90731] = { title = "Enhancing Corruption", description = "Welcome back adventurer. I have made a new discovery but I need to test it out. \n\nHidden in the Lost areas of the Horrific Visions I believe is a rare black blood coagulate. This might be the key to increasing the power of the corruption effects... in a safe way. \n\nIf you can go into these areas and find this item and also bring me back more displaced corrupted mementos I should be able to increase the potency of the corruption effects.", objectives = "" }
WordHunterWoW_QuestEN[90733] = { title = "The Listener", description = "Now that you've learned about our legends, you've earned the notice of one of our elders. He wants to meet you.\n\nHis name is Aksem, and he knows things that the rest of us have never learned. History that remains hidden, even in the paintings.\n\nGo and introduce yourself. He's expecting you.", objectives = "" }
WordHunterWoW_QuestEN[90734] = { title = "In the Name of the Goddess", description = "The high priest Aksem has asked for you again. He said you are not the only one on a quest for knowledge about the deep history of Harandar.\n\nGo to him. I believe he already has another guest who is also interested in learning this hidden history.", objectives = "" }
WordHunterWoW_QuestEN[90735] = { title = "The Stolen Staff", description = "This time, I do not have a story for you. \n\nInstead, Aksem has asked that you meet with him to help recover the next of the relics. Go to speak with him, and he will tell you more of what you must do.", objectives = "" }
WordHunterWoW_QuestEN[90736] = { title = "That's Not Yours", description = "The rutaani in the Blossoming Terrace are crafty. They've trained their petalwings to search and grab anything shiny that rolls down from the Den.\n\nAnd, I suspect, sometimes they grab things that haven't naturally fallen.\n\nSo we want to get those things back. That's where you come in.\n\nGo into the terrace, and don't hesitate to use force to send a message. That's a language we all understand.", objectives = "" }
WordHunterWoW_QuestEN[90737] = { title = "Nested Clues", description = "You're looking for a staff called the Root of the World. It's a powerful twist of woven roots, back from before the haranir traveled deep into the mountain.\n\nIt's irreplaceable, as Aksem knows. So if a rutaani petalwing stole it, that's embarrassing. The only way for everyone to save face is to get it back.\n\nSearch the nests of the bigger birds. They've been trained to look for more valuable items.", objectives = "" }
WordHunterWoW_QuestEN[90738] = { title = "To the Blossoming Terrace", description = "When the haranir first arrived in Harandar, they brought with them a staff formed of the roots of a great tree. That tree has since gone away, but the roots remain.\n\nIt has been our duty to protect that staff and pass it on through the generations, but now it has been stolen.\n\nYour task is to find it and return it to Zur'Ashar Kassameh.\n\nGo into the mists below the Den and seek out the Shul'ka. They will guide you on your search.", objectives = "" }
WordHunterWoW_QuestEN[90739] = { title = "The Root of Things", description = "Looks like you didn't find any sign of the rootstaff among all the thiever's nests. That's a good thing, honestly.\n\nBut there's more to this test than just recovering stolen goods. Yes, it's a test. You're seeking secret knowledge. That means something here doesn't add up, and the real answer is waiting to be found.\n\nSo, come find me when you're ready to get that answer.", objectives = "" }
WordHunterWoW_QuestEN[90740] = { title = "A Legend to Know", description = "I am entrusted with many secrets, and the benefit of that is not having to explain myself often.\n\nYou have recovered the Root of the World, as I asked. Now, take it to Zur'ashar Kassemeh, and learn more about it.\n\nThere will be more for you, later.", objectives = "" }
WordHunterWoW_QuestEN[90741] = { title = "Once More Into the Rift", description = "Aksem has asked for you again. He says he's ready for you to undergo the final ritual for the knowledge he wants to teach you.\n\nI admit, I'm envious, but I do not envy the trials you'll need to undergo in order to prepare for this knowledge.\n\nGo speak to Aksem, and do as he says. Orweyna will be joining you.", objectives = "" }
WordHunterWoW_QuestEN[90742] = { title = "Shrouded by Aln'hara", description = "As you know well by now, the creatures in the rift are infused with the essence of Aln'hara. What we need is that essence mixed with water.\n\nAksem wants us to collect water here and then infuse the essence of Aln'hara into it. I can only imagine what it might be used for.", objectives = "" }
WordHunterWoW_QuestEN[90743] = { title = "Ritual Reinforcement", description = "You know the dangers of the Rift of Aln, but this is the best place to prepare for the kind of ritual Aksem wants to perform.\n\nGo about the rift and place offerings to prepare yourself.", objectives = "" }
WordHunterWoW_QuestEN[90744] = { title = "The Dreamrift: Malformed Mystery", description = "We have prepared ourselves as best we can for the next stage. Now, we must venture into the deepest part of the Rift of Aln.\n\nInto the Dreamrift.\n\nIt's a place so dangerous that even the Shul'ka hesitate to go, but we must. Aksem needs us to collect the most powerful infusion of Aln there is.\n\nAre you ready?", objectives = "" }
WordHunterWoW_QuestEN[90745] = { title = "The Empty Cradle", description = "You have ventured far, fought deep, and learned many things about our history to be here.\n\nNow it's time to know the truth. Prepare yourself.", objectives = "" }
WordHunterWoW_QuestEN[90746] = { title = "The Elves Assemble", description = "The time for preparations have passed. Xal'atath's forces are upon us.\n\nJoin us, champion, as we must rebuff this assault and then press our attack on the Darkwell.", objectives = "" }
WordHunterWoW_QuestEN[90747] = { title = "The Wrong Bluecephalus", description = "We may have gotten off on the wrong foot, but there's something you should know.\n\nThat old slateback you used to haul all those imports? I thought it was just another worn-out nag, but it turns out it was the real treasure all along.\n\nA rare bluecephalus, worth a fortune!\n\nYou might want to figure out where it went, and why Ba'eth isn't exactly rushing to share the profits!", objectives = "" }
WordHunterWoW_QuestEN[90748] = { title = "Quel'Danas", description = "Champion, the time has come to see an end to the Darkwell.\n\nI do not know what awaits us beyond the gates of Quel'Danas, but we cannot tarry any longer. The Void continues to pour into the Darkwell, transforming it. \n\nArator is at the head of our combined armies. He has asked you and your strongest allies join him at his side. \n\nIt is time to end this and take back our well.", objectives = "" }
WordHunterWoW_QuestEN[90749] = { title = "Our Mutual Enemy", description = "<Liadrin lowers her voice, speaking only to you.>\n\nWe have two choices. We can either continue to talk to the Amani or fight our way inside.\n\nI would still prefer to negotiate passage with Zul'jarra, but if our diplomacy goes awry, be ready.\n\nFor now, follow my lead.", objectives = "" }
WordHunterWoW_QuestEN[90754] = { title = "Skyriding", description = "This land is more vast than I remember. However, a good scholar is always prepared.\n\nTo cover more ground, you will need a winged mount and the skill to ride it swiftly.\n\nI recall Lord Andestrasz helping us with this in the past, near the Timeless Isle in Pandaria. Let's send you back to that moment in time, so you can learn from him.\n\nDon't wander too far in distant lands, you're still needed back here. Return via the portal when you have finished your instructions.", objectives = "" }
WordHunterWoW_QuestEN[90755] = { title = "Time Flies", description = "That should suffice for now. Remember the basics and you will improve in time.\n\nSpeaking of time, you had best be on your way. The portal there will take you back to Moratari.", objectives = "" }
WordHunterWoW_QuestEN[90759] = { title = "The Cult Within", description = "<A missive written on shimmering vellum unfurls before you.>\n\n{name},\n\nRumors suggest that Xal'atath's cult, the Twilight's Blade, has been recruiting in Alliance cities. Meet me in Stormwind to investigate these rumors. If the cult is there, then we must stamp it out at once.\n\nMagister Umbric", objectives = "" }
WordHunterWoW_QuestEN[90760] = { title = "Avoiding Blame", description = "Apocalyptic threats have taken many forms in Azeroth's history, but today we face Xal'atath and her Twilight's Blade.\n\nI fear that people are falling into hopelessness as the Radiant Song cries a warning. The Twilight's Blade could use that despair to draw them into their ranks.\n\nMy mages have identified this district as housing a peculiar amount of void energy. Investigate and stop any cultists you may find.", objectives = "" }
WordHunterWoW_QuestEN[90761] = { title = "Avoiding Blame", description = "The cult of twilight has long been dedicated to ending Azeroth. That they ally with Xal'atath is no surprise.\n\nIf the Twilight's Blade are indoctrinating citizens, we must stop them. We cannot permit the weak to fall to the Void's dark designs.\n\nThe Cleft of Shadow is home to many practitioners of unsavory magic. Identify and end any cultists you may find there.", objectives = "" }
WordHunterWoW_QuestEN[90762] = { title = "The Twilight Highlands", description = "I've spoken with Grand Magister Rommath. Despite our differences, it seems we are aligned in purpose.\n\nWe have both found evidence that Twilight's Blade cultists are convening in the Twilight Highlands. It's a place long scarred by the cult's misdeeds. And it's a suitable staging ground for an attack.\n\nMeet us there so we may continue our investigation.", objectives = "" }
WordHunterWoW_QuestEN[90763] = { title = "The Twilight Highlands", description = "I've received word from Magister Umbric. He has found similar evidence that the Twilight's Blade are recruiting in Stormwind.\n\nThe Void poses an existential threat to all of Azeroth. We must stop the cult at its source.\n\nWe've agreed to meet in the cult's homeland, the Twilight Highlands. Find me there so we may continue our investigation.", objectives = "" }
WordHunterWoW_QuestEN[90764] = { title = "The Cult Within", description = "<A missive written on fine parchment unfurls before you.>\n\n{name},\n\nI have heard unsettling rumors that Xal'atath's cult, the Twilight's Blade, is recruiting within Horde cities. Meet me in Orgrimmar so we may root out this evil. We cannot suffer a single cultist within our walls.\n\nGrand Magister Rommath", objectives = "" }
WordHunterWoW_QuestEN[90765] = { title = "Midnight Dress", description = "Cult activity in the area has risen significantly. While we are gathering troops, you secure a cultist disguise and infiltrate their nearby training grounds.\n\nFind out anything you can about the Twilight's Blade and their goals. I will keep this area secure.", objectives = "" }
WordHunterWoW_QuestEN[90766] = { title = "Xal'atath's Proven Faithful", description = "It takes more than blistering desperation for the apocalypse to be part of the Cult of Twilight.\n\nWe are Xal'atath's Twilight's Blade. Our purpose is greater than it has ever been before. And thus, we must become her strongest allies.\n\nGo and train with my associates in the field. Educate yourself on our rituals and rhetoric. Only then will I allow you to go through the initiation ceremony.", objectives = "" }
WordHunterWoW_QuestEN[90767] = { title = "More Doom", description = "Having completed your training, you have earned full membership with the Twilight's Blade.\n\n<Harrowtongue pauses a moment, appearing self-satisfied.>\n\nAs a member of the cult, you will now join your fellow acolytes in an initiation ceremony. They are in the basement of this building receiving instructions from our great leader, Mor'duun.\n\nAllow his words to fill you with zeal for the cause. The end is near!", objectives = "" }
WordHunterWoW_QuestEN[90768] = { title = "Cult It Out", description = "Mor'duun and his Twilight's Blade cultists are directly supporting the Harbinger's dark designs for our world.\n\nAnd that is all we need to know. Kill as many as you can, then meet us back at our base of operations.\n\nThe cult and its leaders must be eliminated.", objectives = "" }
WordHunterWoW_QuestEN[90769] = { title = "A Blue for You", description = "Why you want such a strange beast? \n\nI save many better items just for you. What about some soap?\n\nBut, I not deny {name} heart's desire.", objectives = "" }
WordHunterWoW_QuestEN[90770] = { title = "The Grift", description = "Dey say you want the blue beast. Was a great bargain I stumbled upon. Da bazaar full of opportunities. \n\nMany more bargains to find in spots where treasures lie waiting. \n\nYou know where to look?\n\nGo to dis special place and find treasures, I give the blue beast to you.", objectives = "" }
WordHunterWoW_QuestEN[90772] = { title = "The Flames Rise Higher", description = "De coal... it's white-hot now. And I feel like there is somethin' inside it?\n\nBrek said dis was de last trial. But Jan'alai is not here.\n\nWhat do we do now?\n\n<Zul'jarra looks at Brek and scowls.>\n\nTalk to Brek and see if he's got anything to say we can understand.", objectives = "" }
WordHunterWoW_QuestEN[90773] = { title = "Meat My Business", description = "Since I am helping you, I'm sure you won't mind returning the favor.\n\nI have a constant need for fresh, untainted meat, which is quite hard to come by. The Oasis is off limits, but the wildlife roaming these sands?\n\nI've got a list of what I need. Bring me those items, and I'll tell you what you need to know.", objectives = "" }
WordHunterWoW_QuestEN[90776] = { title = "Ancient Curiosity: Combat", description = "<You hold the curio and discover a shimmering glow emanating from it. This looks important. The Explorers' League would be interested in this.>", objectives = "" }
WordHunterWoW_QuestEN[90777] = { title = "Feeding the Flame", description = "Champion, the Sunwell holds for now, but the Vanguard has begun to deploy the bulk of its forces to Voidstorm.\n\nLady Liadrin has requested your assistance at the Sunwell.", objectives = "" }
WordHunterWoW_QuestEN[90778] = { title = "Ancient Curiosity: Utility", description = "<You hold the curio and discover a shimmering glow emanating from it. This looks important. The Explorers' League would be interested in this.>", objectives = "" }
WordHunterWoW_QuestEN[90779] = { title = "Cracked Keystone", description = "Fragmentary images of heroic deeds flash though your mind as you touch the stone, but they fade as fast as they arrive.\n\nPerhaps performing a suitably impressive task will stabilize the stone's magic once more?", objectives = "" }
WordHunterWoW_QuestEN[90782] = { title = "The Nethersent", description = "<The draenei first tries to speak to you in his native tongue, adapting after you fail to respond.>\n\nMen of Void take us to here. Come from sky. Fighting, killing. Want to go back. Help brothers and sisters.\n\nShow you.", objectives = "" }
WordHunterWoW_QuestEN[90818] = { title = "Murder Row: Loose Lips", description = "It is not unexpected to sense some fel magic here. There are still warlocks in the city and old fel siphoning chambers. But the evidence I've found so far is more than could be explained by just that. It feels... different. Chaotic.\n\nThis practice has to be widespread, which means someone must be talking about it.\n\nI've been rooting around too long to go unnoticed, but perhaps you could covertly listen in on some idle banter around the city. If you learn anything useful, report back to me.", objectives = "" }
WordHunterWoW_QuestEN[90819] = { title = "Murder Row: Acting the Part", description = "Based on what we discovered, I believe the fel is coming from Murder Row. Someone there is breaking down Legion relics and infusing the magic into mana wyrms for covert siphoning--and people are buying it up in droves.\n\nWe need to figure out who that someone is.\n\nTake this wyrm core with you into the Row and look for more of them. The promise of coin should get you in front of the right person.", objectives = "" }
WordHunterWoW_QuestEN[90821] = { title = "Murder Row: Harbored Secrets", description = "That manifest is stamped by the Silvermoon Harbor. It looks like Zaen has his smugglers working there to push his fel relic shipments through inspections.\n\nIf we cut off their supply line at the harbor, we can halt the fel operation until we track down Zaen and end it for good. No sense going after the middlemen until then.\n\nSubterfuge got us this far, so let's keep at it. Head to the harbor and tell them you're picking up Zaen's shipment. We'll work from there.", objectives = "" }
WordHunterWoW_QuestEN[90822] = { title = "Murder Row: One Fel Swoop", description = "We have all the puzzle pieces. Zaen smuggles fel relics from the Broken Isles by stacking the Silvermoon Harbor with his own smugglers. The relics are processed in Murder Row, then fel magic is infused into mana wyrms for sale and siphoning.\n\nSuch a convoluted operation might be impressive, if the goals weren't so reckless. Zaen is preying on people's fear. He doesn't care who he helps or hurts as long as he rakes in the gold.\n\nLet us end it. We'll find the Illicit Rain in Murder Row and clear it out.", objectives = "" }
WordHunterWoW_QuestEN[90823] = { title = "Akil'zon's Insight", description = "Now that I be catching my breath, I be reminded of why I thought there'd be nothing but silence at the top.\n\nShe be here. Akil'zon be here. But also, she had been gone when we needed her most.\n\nWhat could she be wanting to tell us?", objectives = "" }
WordHunterWoW_QuestEN[90824] = { title = "My Brother's Alive!", description = "En'liahn saved me from the Rift of Aln. He's my older brother. I know it was stupid to go there, but it wasn't my fault!\n\nWe all thought En'liahn was dead, but I saw him earlier at the wetland. When he saw me, he ran away.\n\n<Chua looks sad.>\n\nNo one here believes me and now I can't go. Will you help me find him again?", objectives = "" }
WordHunterWoW_QuestEN[90826] = { title = "The Healing Waters of Ahl'ua", description = "I'd hoped Chua hadn't seen me. Better he thinks I died. Instead, I'm self-exiling.\n\nI was trapped in the Rift of Aln while saving him. Being in there for so long corrupted my connection to the goddess--if I don't sever it soon, it'll drive me mad, or worse.\n\nThe Shul'ka who saved me has agreed to mentor me through the process. He told me to come here and gather some things for a ritual to sever the connection.\n\nI must collect the nearby healing waters. Will you help me fill this jug?", objectives = "" }
WordHunterWoW_QuestEN[90827] = { title = "Only the Poisonous Parts", description = "My Shul'ka mentor instructed me to collect the toxic glands from the creatures here. He said they were crucial to the Ritual of Severing in order to break my connection with the goddess.\n\n<En'liahn shakes his head in pain.>\n\nI'm not looking forward to whatever this ritual is, but her disjointed song in my head is getting stronger and making it hard to focus.", objectives = "" }
WordHunterWoW_QuestEN[90829] = { title = "Meeting My Mentor", description = "I'm in your debt, {name}. I didn't think I'd get any help. My mentor only provides guidance. He says that is the way of the Shul'ka.\n\nThanks to you, I have everything I need for the ritual. Will you continue on with me? I'm heading for the cliffside overlooking the Rift of Aln to the northeast.", objectives = "" }
WordHunterWoW_QuestEN[90830] = { title = "The Path Will Reveal Itself", description = "The next step is to locate the ritual site. It's different for each potential Shul'ka.\n\nAmarakk says that I must open myself to the power of the rift--that some part of myself tied to this place will guide the way.\n\nAll I can tell you is it hurts.\n\nAre you still with me?", objectives = "" }
WordHunterWoW_QuestEN[90831] = { title = "Doing Is Becoming", description = "If En'liahn is to succeed as a Shul'ka, he must learn to disrupt the manifestations in the rift. Sometimes that means closing small tears as they open. Most of the time, we simply slay the manifestations where we find them so they do not become so numerous as to threaten the rest of Harandar.\n\nIt is a never-ending responsibility each of us bears. It is why we are Shul'ka.\n\nThis, of course, assumes that he survives the ritual, or even survives to find the ritual site.", objectives = "" }
WordHunterWoW_QuestEN[90832] = { title = "As Her Voice Goes Silent", description = "En'liahn is about to drink the mixture of the poison and healing waters to begin the ritual. He will be unconscious and fighting for his life.\n\nThe manifestations of the rift can sense this, and they are gathering.\n\n{name}, you must place the wards and use their power to defend him while he severs his final connection to the goddess before her song drives him to madness.", objectives = "" }
WordHunterWoW_QuestEN[90833] = { title = "The Final Rite", description = "Foolish. En'liahn is still weak from the ritual and not prepared.\n\nHe has run off to confront Morta'ka the Sundered Echo. This is the final rite of all who would become Shul'ka, but it is usually only attempted after years of preparation.\n\nEn'liahn will not survive, and in dying will only make Morta'ka more powerful. Will you save him, {name}?", objectives = "" }
WordHunterWoW_QuestEN[90834] = { title = "From This Point Forward", description = "I don't know how to feel about losing my connection with Aln'hara. There's no more pain... I'm not going mad, but there's a hole inside. Does that make sense?\n\nWill you rejoin us back up on the cliff?", objectives = "" }
WordHunterWoW_QuestEN[90835] = { title = "Murder Row: Rumors Abound", description = "I would advise exploring the city with caution. Not all is what it seems in Silvermoon.\n\nThe Illidari are performing an investigation which need not be spoken of openly. But you appear formidable... Perhaps you can aid us.\n\nMy commander, Belath Dawnblade, is heading the investigation. The last I heard, he was surveying the upper terraces of the Bazaar.\n\nSeek him out, if you would make use of yourself.", objectives = "" }
WordHunterWoW_QuestEN[90837] = { title = "Murder Row: Traces of Fel", description = "I have been sensing powerful fel magic throughout Silvermoon, but this is the first origin point I could locate. The rest were too faint, or perhaps deliberately hidden. Fortunately, this means we now have a specific area to comb through more closely.\n\nWe need to gather more evidence. Go around this area and see if you can find more hidden sources of fel. I will grant you a temporary portion of my sight so that even the slightest hint of fel magic will be obvious to you.", objectives = "" }
WordHunterWoW_QuestEN[90838] = { title = "Oaths and Heirlooms", description = "You, stranger... do you know of the Shadowguard that left K'aresh in ruins?\n\nMy sister was lost in the conflict, her heart forcibly turned to the Void, but I swore oaths to my family... to cherish them no matter their transgressions.\n\nMy sister, Veraan, is surely lost, but if I were to recover her necklace, at least then my oaths would be upheld in spirit.\n\nI am a simple tinkerer. I've tuned this device to track the Shadowguard, but I cannot face them alone.\n\nWould you help me?", objectives = "" }
WordHunterWoW_QuestEN[90840] = { title = "What's Your Specialty?", description = "The Dragon Isles is a dangerous and uncharted place. We'll need to get you prepared.\n\nYou're strong enough now that you should choose a combat specialization.\n\nThis will unlock a new array of abilities for you to face the dangers within the Dragon Isles.\n\nGo ahead and choose your combat specialization.", objectives = "" }
WordHunterWoW_QuestEN[90842] = { title = "Home Is Where the Hearth Is", description = "Before you head off, you'll want to get yourself a Hearthstone. \n\nThis little stone will return you to the inn where you last bound it to.\n\nIt's not much of an \"inn\", but the explorers have a tent set up. \n\nTest out that new mount of yours and ride over to Sil'nori Crestshade. He'll get you sorted out with a Hearthstone.", objectives = "" }
WordHunterWoW_QuestEN[90843] = { title = "Aiding the Dragon Isles", description = "It's time for us to part ways. I have pressing business further within the Dragon Isles in a place called the Azure Span.\n\nNaleidea Rivergleam of the Dragonscale Expedition could use your help.\n\nSafe travels, {name}. I look forward to our next meeting!", objectives = "" }
WordHunterWoW_QuestEN[90844] = { title = "Fits of Lucidity", description = "While I've been lurking, I've been listening.\n\nThese Shadowguard appear to have a minor rebellion on their hands. Some of the ethereals are acting erratically. They're being rounded up and questioned.\n\nWhat's going on here?\n\nDispatch some of these Shadowguard and intercept their intel. I'll decode anything you bring back to me.", objectives = "" }
WordHunterWoW_QuestEN[90845] = { title = "Distant Memories", description = "I swore an oath to honor my family... difficult when my sister was converted to the Shadowguard. She may not be here, but tracking the Shadowguard has led me to this place. \n\nI'm looking for a necklace that belonged to my sister Veraan. It's odd... I've noticed many K'areshi heirlooms discarded around here. It seems the Shadowguard wish to destroy any reminders of our home world.\n\nIf you bring some of these trinkets and baubles to me, we can see if there are any I recognize.", objectives = "" }
WordHunterWoW_QuestEN[90847] = { title = "Truth From Power", description = "Thanks to your intel, we have learned that the rebels are being interrogated by Questioner Xen'daan.\n\nIt is said that after being questioned, the rebel ethereals are being taken somewhere to be \"dealt with.\"\n\nThe head questioner is sure to know more. If we can find where they've taken the rebels, there may still be hope for them.", objectives = "" }
WordHunterWoW_QuestEN[90848] = { title = "She Started the Fire", description = "Veraan is sure to be amongst the rebels taken to Shadowguard Point.\n\nHer fiery spirit fills me with great pride!\n\nI came here expecting to say a farewell of sorts. I did not come here expecting to find my sister.\n\nPerhaps it's not too late, {name}!", objectives = "" }
WordHunterWoW_QuestEN[90851] = { title = "Eating Their Own", description = "The Shadowguard seem to have no qualms caging and torturing their own kind.\n\nThe last thing I want is more violence amongst the people of K'aresh, but better them than us.\n\nDisrupt their operation by subduing some of the Shadowguard.", objectives = "" }
WordHunterWoW_QuestEN[90852] = { title = "Techno-Magnetic Pulse", description = "The betrayers are being held in stasis chambers.\n\nI've seen these cages before. Their design is efficient but fragile. They will fail with the slightest energy variation.\n\nFind crackling energy vessels strewn about and heave them at the stasis chambers. With true aim, you will disable them and free the betrayers.", objectives = "" }
WordHunterWoW_QuestEN[90858] = { title = "Repress the Oppressors", description = "We were brought here to face the wrath of Soulbinder D'zaar. She commands the Shadowguard here. She leverages the power of the Voidstorm to convert souls to energy that she consumes.\n\nShe and her loyalists are traitors to our kind!\n\n<Veraan grimaces in pain as the Void courses through her.>\n\nThey must be stopped... their devices dismantled... their will ended...\n\n{name}... destroy them all!", objectives = "" }
WordHunterWoW_QuestEN[90860] = { title = "Shedding the Yoke", description = "Rebels like us are brought to Soulbinder D'zaar. She suffers no betrayers.\n\nOur fate was to be sacrificed--our souls converted to energy. D'zaar works the conduit with arcane mastery to absorb these souls!\n\nWe don't have much time. I can feel the Void pressing from within. If we are to leave this life violently, D'zaar and her conduit are coming with us!", objectives = "" }
WordHunterWoW_QuestEN[90861] = { title = "Those Left Behind", description = "In the wake of Xal'atath's destruction, what remains of our forces are gathering at the Darkwell to determine what we can do about the remnants of the Void.\n\nWe cannot abide the presence of so much dark energy. Some of our greatest casters and most knowledgeable scholars believe they might have a solution, but we could use your aid.\n\nPlease, join Arator at the Darkwell at your earliest convenience.", objectives = "" }
WordHunterWoW_QuestEN[90862] = { title = "In Times of Need", description = "The last of the other elven leaders have returned with powers from their homeland that will help us in cleansing the Darkwell. \n\nWhile the Voidstorm no longer barrages the Darkwell, it still needs healing. \n\nPlease meet with the other leaders and let them know we are ready for them.", objectives = "" }
WordHunterWoW_QuestEN[90866] = { title = "Universal Language", description = "To go home, water of life. Need.\n\n<Tul'amar attempts to discern if you understand what she's talking about with a look. After a pause, she opts to stab her own fingertip with the end of her staff and then displays a bead of her blood to you.>\n\nThis. Of here. Is of fight. Of fight is Void. Void is power. With power, go home.\n\n<She shows her fangs with an exaggerated snarl before pantomiming a claw swipe.>\n\nWater of life. Of beast. Much. Yes?", objectives = "" }
WordHunterWoW_QuestEN[90867] = { title = "From Darkness, Light", description = "We will not let the Sunwell be corrupted again. This Darkwell must change, but it must change to something that we are no longer bound to with such dependency. We do not need this well to be the bait for so many other world-corrupting forces.\n\nNo, today we heal the Darkwell, and make it something new. Let me know when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[90869] = { title = "It's All in the Image", description = "So, the higher-ups in the marketing department say you need a good partner to soften your aesthetic of... you know, \"murder everyone around me for gold.\"\n\nWe've got two focus group approved goblins over there ready to go, so go take your pick. Sassy will handle the paperwork.\n\nOh, don't give me that look. You only gotta forever-love each other in front of the public. Once the cameras are off, no one cares. It'll be great for your reputation!", objectives = "" }
WordHunterWoW_QuestEN[90870] = { title = "Gathering the Grub", description = "Ah, ye're here! Brewfest is here and we've got a small problem. We can't have a proper feast without the food, but some pesky hozen thought it'd be fun to steal our bags of grub. I'm sure they're just lookin' to fill their own bellies, but it's messin' up our plans!\n\nSo here's what I need ye to do: hunt down those hozen and take back the bags they've snatched. There's a good chance ye'll find a few bags just sittin' on the ground too. When ye return, just add the recovered bags to that wagon back there.", objectives = "" }
WordHunterWoW_QuestEN[90871] = { title = "The Silversun Compact", description = "Champion. \n\nAfter much discussion, negotiation, and even some screaming and three duels, the Sunreavers and the Silver Covenant have decided on a course of action to define both of our futures.\n\nGiven your aid in getting us to this day, we would like you here to act as a witness as we formalize and sign our peace accords. Will you do us the honor of igniting the Flames of Remembrance?", objectives = "" }
WordHunterWoW_QuestEN[90872] = { title = "Drenched In It", description = "<Tul'amar looks away from the blood-soaked and mortified Juras, and toward the portal as it flickers to life. She reads it with her powers of the arcane.>\n\nGood. Blood is vio... violent? Violent is power. Need more. Now, brothers and sisters.\n\n<She gestures to the blood in your possession, and then to her people. Many of them return wary looks your way.>\n\nYou can. I say. \n\nThen, go out. See of me.", objectives = "" }
WordHunterWoW_QuestEN[90873] = { title = "These Violent Delights", description = "Brothers and sisters. Here. Help.\n\n<Tul'amar connects her thumb and index finger on both hands to make a chain. Then, she breaks the link with a sharp gesture.>\n\nHow? Show.\n\n<She then produces a glimmering relic and holds it over her gauntlet. She spends a portion of her arcane energy into it. Its newly activated magic forces the straps holding her glove in place loose.>\n\nUse.", objectives = "" }
WordHunterWoW_QuestEN[90874] = { title = "Their Violent Ends", description = "Go home. How?\n\n<She offers a dramatic flourish with her fingertips, producing some arcane sparks. Then, she makes an X with her index fingers.>\n\nOf me? No. Of they.\n\n<Tul'amar gestures to a group of voidwalkers up ahead. She then draws her thumb across her neck.>\n\nKill. And.\n\n<She reaches into a pouch on her hip and retrieves a cracked stone of domanaar make. It looks like a spell reagent of some kind.>\n\nAs this. Need.", objectives = "" }
WordHunterWoW_QuestEN[90875] = { title = "Across Worlds", description = "Man of Void. Have key. Need. Key to home.\n\n<Tul'amar gestures down the way to the northwest. She grimaces back at her injured kin.>\n\nGo back, we. Wait. Hope. For you.", objectives = "" }
WordHunterWoW_QuestEN[90876] = { title = "Reluctant Hand", description = "Champion, I felt it was important to have you here for this moment so that neither I nor my wayward former peer get off topic with his many failings.\n\nI also want a witness in case he turns to evil. \n\nWould you be so kind as to unpack a few items so that I do not have to touch them?", objectives = "" }
WordHunterWoW_QuestEN[90879] = { title = "Brewmaster's Kitchen", description = "Now that ye've gathered the materials, we can get to cookin'! We'll need plenty o' food for the whole crowd.\n\nWe've got a short but sweet menu: Barley Soup, Pretzels, and of course a good ol' brew!\n\nAre ye ready to learn the ropes?", objectives = "" }
WordHunterWoW_QuestEN[90880] = { title = "Serving with Style", description = "Ye've done well in the kitchen, now it's time to learn how to serve! Brewfest isn't just about food--it's about makin' sure everyone has a good time.\n\nYe'll be takin' orders, deliverin' dishes, and pourin' drinks with a smile.\n\nGet out there and show 'em how it's done. Brewfest won't run without good service!", objectives = "" }
WordHunterWoW_QuestEN[90882] = { title = "Gnoll Way", description = "Handle those gnolls while we figure out our next move.", objectives = "" }
WordHunterWoW_QuestEN[90883] = { title = "To Go'shek Farm", description = "Find Farmer Bruvk outside of Go'Shek Farm.", objectives = "" }
WordHunterWoW_QuestEN[90885] = { title = "My Beautiful Pumpkins", description = "The kobolds and ogres appeared out of nowhere and kicked us out of the farm!\n\nI thought this was some Alliance plot until you all showed up. Maybe the Alliance is here to help us after all.\n\nYou have to help me get my precious pumpkins back. I've spent the entire harvest cultivating them!\n\nYou lead the way. I'll grab the pumpkins when you find them.", objectives = "" }
WordHunterWoW_QuestEN[90886] = { title = "Best Laid Plans of Kobolds and Ogres", description = "The kobolds and ogres here seem to be carrying some sort of plan for their attack.\n\nI don't think they're particularly well written, so I'll need several of them to figure out what the ogres are planning.", objectives = "" }
WordHunterWoW_QuestEN[90887] = { title = "Farmer's Nemesis", description = "Farmer Bruvk mentioned an ogre named Runk was leading the group here.\n\nThese creatures won't leave this place as long as that ogre is commanding them.", objectives = "" }
WordHunterWoW_QuestEN[90888] = { title = "Saving Stromgarde Keep", description = "The plans you found indicate the ogres are trying to get food to supply a massive attack on Stromgarde Keep!\n\nOr they're trying to use the crops to keep guarding an object named a storm. The translation was loose. \n\nIt's safe to assume our problem is the former. Let's go!", objectives = "" }
WordHunterWoW_QuestEN[90890] = { title = "[PH] Go Home", description = "", objectives = "" }
WordHunterWoW_QuestEN[90892] = { title = "Clearing the Skies: A Fel of a Time", description = "<The skies are full of residual time energy and demons pouring in from other timelines.\n\nI should help Eternus by cleaning up the skies. The extra bronze energy would be nice too.>", objectives = "" }
WordHunterWoW_QuestEN[90893] = { title = "Repelling the Siege", description = "We must do everything possible to stop this siege on Stromgarde. \n\nMake your way into the battle and weaken the ogre forces.\n\nStromgarde should be able to rally if they can gain the upper hand.", objectives = "" }
WordHunterWoW_QuestEN[90895] = { title = "Catapult Bombardment", description = "These catapults are relentless. They must be destroyed.\n\nPlace these rune stones at their base. It'll unleash arcane magic to turn the catapults to dust.\n\nI'll take out a few as well as I make my way across the battlefield.", objectives = "" }
WordHunterWoW_QuestEN[90896] = { title = "One Last Ogre", description = "The head of the siege is still cowering within the former Horde encampment. \n\nHe managed to hide from Jaina's spell behind several of his cohorts.\n\nYou can have the honors to confront of him. Jaina and I will stay here to ensure any remnants of the siege do not return.\n\nEnd this.", objectives = "" }
WordHunterWoW_QuestEN[90897] = { title = "Back to Stromgarde", description = "I think we can count ourselves lucky there was no bigger threat here beyond a group of overambitious ogres. \n\nThe same can't be said of other threats that are looming throughout Azeroth.\n\nCome. Let's return to Stromgarde to discuss matters further.", objectives = "" }
WordHunterWoW_QuestEN[90898] = { title = "Back to Hammerfall", description = "We're not always so lucky that a plan such as this is ended so swiftly and without a surprise portal or two.\n\nThat being said, more dangers lurk throughout Azeroth. I know you can be of help to some.\n\nLet us return to Hammerfall to see how they're recovering.", objectives = "" }
WordHunterWoW_QuestEN[90901] = { title = "As A Matter of Artifact", description = "There's more to artifacts than meets the eye, {name}.\n\nSimply using an artifact allows its legend to grow, and as that legend grows, so too does its power.\n\nIn order to unlock the full potential of that power, however, you'll need to focus infinite power into the artifact's traits. As more traits are empowered the artifact's true potential will be unlocked, and its legend will be undeniable.\n\nLet's get started.", objectives = "" }
WordHunterWoW_QuestEN[90907] = { title = "The First to Know", description = "Notes speaking of fear, of uncertainty--of some mysterious truth? This is not good, {name}. By all accounts, it sounds as if a cult has managed to infiltrate Tranquillien. \n\nIf that journal entry was true, Kasiea was attempting to leave it. \n\nWe must tell Antenorian. He'll want to secure the town and make sure his people are safe.", objectives = "" }
WordHunterWoW_QuestEN[90910] = { title = "Overwhelming Darkness", description = "A dreadful presence calls from the den just to the southeast of here. Many of the dazed ren'dorei you see in camp were overwhelmed by its raw power on a scouting mission.\n\nLet us go together and see if whatever dwells within can be put to use. We cannot afford to spurn power in the fight against Xal'atath.\n\nBefore that: we have little need of Kalgorg. The Voidstorm has made my voidwalker unruly and disobedient. Assist me in sacrificing it. We will need all of the Void energy we can muster.", objectives = "" }
WordHunterWoW_QuestEN[90911] = { title = "Your Next Adventure", description = "", objectives = "" }
WordHunterWoW_QuestEN[90914] = { title = "A Born Killer", description = "Ah, {name}. I have so enjoyed our time together. I hunger for more. \n\nI wish you knew more of me than my predilection for the taste of mortal suffering. One of my greatest joys is in crafting Void power into various objects and structures. It is my passion--my art.\n\nHere, I would like to show you. First, we will need power. You already know how to get it, of course: kill, kill, kill.", objectives = "" }
WordHunterWoW_QuestEN[90915] = { title = "Artifice of Aggression", description = "While we domanaar are best known for leading armies and savoring battles, there is more to us. \n\nMany, like myself, enjoy using our mastery over the Void to shape it into the buildings and objects you see around you. \n\nHow do you think Xal'atath learned to create that great tower of hers? She's a quick study. \n\nCome now, and I will show you my work.", objectives = "" }
WordHunterWoW_QuestEN[90916] = { title = "Seek to Destroy", description = "It's no easy thing, intertwining Light and Void together. The result is unstable, so we must continue to temper it. \n\nWe shall quench this blade in the blood of our enemies. \n\nSome domanaar attempt to reclaim and re-power Nexus-Point Xenas. That won't be good for your people. I'll assume you want to stop it. \n\nWhat is it you mortals say? Two birds, one stone?", objectives = "" }
WordHunterWoW_QuestEN[90917] = { title = "Harvester of Savagery", description = "The blade hungers! The blood of our enemies will help stabilize and hone our nascent weapon. \n\nYou'll need to drench the blade inside some corpses. So, you'll need to make corpses. \n\n<Decimus's smile grows broader.> \n\nYou're good at that, right?", objectives = "" }
WordHunterWoW_QuestEN[90918] = { title = "The Unforgiven", description = "Since even before our little misadventure, Nexus-Point Xenas has always been the weakest link. The beasts here are stubborn and powerful, always pushing deeper and deeper in. \n\nSome domanaar seek to reclaim the Nexus-Point. They are known to me: weaklings, fighting for scraps. Let's ensure they fail.", objectives = "" }
WordHunterWoW_QuestEN[90919] = { title = "The Fiend That Failed", description = "The blade squirms. It is ready for its next transformation.\n\nThere is only the leader, Vortensiun, left. \n\nHe is known to me. Once, we formed a pact together to defeat a rival. When the time came for him to betray me, he did so clumsily. \n\nI let him live, so I could savor the taste of his regret. \n\nI wonder how well that pain has marinated by now? Let's find out. When the blade is tempered in his essence, it shall grow new power.", objectives = "" }
WordHunterWoW_QuestEN[90920] = { title = "Warmth for the Soul", description = "Enjoying the view? \n\nThe blade is stronger now, but it is not yet complete. A weapon worthy of you deserves nothing less than perfection. \n\nBut let us relax for a moment. I understand you mortals enjoy a... casual exchange of conversation to get to know each other better.\n\nI am familiar with the concept, but am curious to see it in action. Indulge me?", objectives = "" }
WordHunterWoW_QuestEN[90922] = { title = "The Fallen Wake", description = "<The shade flickers. You can barely make out its whisper.>\n\nYou... left me... to die...\n\n<Its arm reaches toward you, then dissipates. Somehow, the presence is a familiar one. You feel that you know this spirit. \n\nYou see more flickers in the distance. What are these shades?>", objectives = "" }
WordHunterWoW_QuestEN[90923] = { title = "Shepherd of Fear", description = "Our journey continues... one final battlefield. There are vicious beasts aplenty here. Their Void shall fuel the blade even more.\n\nAnd the blade's newfound power shall draw their Void into itself by mere proximity!\n\nThough, this place is different. You may find things you don't expect.\n\nKeep an eye out.", objectives = "" }
WordHunterWoW_QuestEN[90924] = { title = "The Wicked End", description = "The time has come. The final step. \n\n<Decimus pauses, savoring something.>\n\nLet us create the greatest weapon your kind has ever seen.", objectives = "" }
WordHunterWoW_QuestEN[90938] = { title = "A Skip Through the Void", description = "Fleshling, do you know about Untethered Space? I am sure you know someone who has encountered it. \n \nPreviously we assumed that only beings of energy such as those from K'aresh could Phase Dive. Since the Harbinger's return, she has created a means for solid creatures to become energy using Reshii Wraps.\n \nMy name is Hashim, and I have some Reshii Wraps in my possession. We are in desperate need of adventurers powerful enough to brave the lucrative depths of Untethered Space.", objectives = "" }
WordHunterWoW_QuestEN[90957] = { title = "Initiation Day", description = "{name}, today is when you find your proper place among the haranir.\n\nRoot Tender Dalnir will guide you. His path is one of tradition and humility, so don't expect excitement. By the end of the day, you will make your mark in the Den of Remembrance. The story you begin now will build on those that came before, like the roots themselves, growing the foundations of Harandar.\n\nDalnir was clearing invasive drifters from the roots. Before you go to him, aid Dalnir by removing some of the pests yourself.", objectives = "" }
WordHunterWoW_QuestEN[90958] = { title = "Roots Above All", description = "Some say the great trees grow, and Harandar will remain even if we do not tend them. Our traditions say, it does not matter. We remain here to protect, tend and serve. We do this with dedication and humility.\n\nKeeping the environment around the roots clean and free of pests reflects upon this duty. Return to me once you are done. You will represent our ways well, {name}.", objectives = "" }
WordHunterWoW_QuestEN[90959] = { title = "Traditional Duties", description = "Dalnir has a point about the ceremony, but we should not focus too narrowly. I still hold the values of our people, but sometimes we must look beyond.\n\nDo not worry. You should be focusing on the ceremony. I will search for the outsiders later.\n\nI am sure you could join me once the initiation ceremony is done.", objectives = "" }
WordHunterWoW_QuestEN[90960] = { title = "My Story, My Legacy", description = "{name}, the final part of the ceremony is ahead of you, though you've put it at risk with your digressions.\n\nThe first mural will show you a vision of your true self, the one that resonates from within you.\n\nThe second mural will show you a vision of where you are needed.\n\nThe third mural, tradition tells us, breaks the barrier between us and the Goddess herself.\n\nThe ceremony will conclude with you painting your story in the Den.", objectives = "" }
WordHunterWoW_QuestEN[90961] = { title = "Stranger in a New Land", description = "{name}, I see you now for who you are. You are dedicated not just to our people, but to the world.\n\nThe goddess has acknowledged you as well, and I can not recall such an event--not even Orweyna's ceremony was so eventful.\n\nThis is where your story begins. It is time for you to take the first steps of your journey.", objectives = "" }
WordHunterWoW_QuestEN[90963] = { title = "Caves of the Cleft", description = "Good work freeing the captured rutaani. With the seeds you recovered, I can try to carry on Ru'gar's work.\n\nI did some scouting and gathering while you were keeping the fungarians distracted, and could use your help with another task. Meet me at the cave northeast of here.", objectives = "" }
WordHunterWoW_QuestEN[90968] = { title = "Titanic Rumblings", description = "Rumors are abuzz of titan forces being sighted around Khaz Algar. Brann has asked Dagran Thaurissan II for assistance in looking into these rumors.", objectives = "" }
WordHunterWoW_QuestEN[90969] = { title = "Titan Consoles", description = "Adventurer, the rumors are true. I've seen the titan forces and they are nae friendly. We must try tae discover why they are emergin' now and try and stop 'em from doin' too much damage.\n\nConfront and stop these renegade constructs. To help ye, I've procured some Titan Consoles. I was able to set them up in the affected areas. I can use them to communicate with ye in the field. I am thinkin' we can use them to counter these titan forces as well.", objectives = "" }
WordHunterWoW_QuestEN[90970] = { title = "Titan Disc-Count", description = "We need tae secure more titan discs. Venture deeper into this area, seek out the Titan Constructs, and defeat them. Ye should find disc shards. This console can reassemble them and access their data. \n\nMake sure tae search for any treasure rooms as well. The constructs appear to be assistin' the local denizens. Some of those locals might've secured additional titan discs with their other treasures.", objectives = "" }
WordHunterWoW_QuestEN[90971] = { title = "Overcharged Console", description = "With the shards ye found, we can use the console tae restore the titan discs and use them to access powerful boons. \n\nUse the console's disc repair feature to create a titan disc, then use that disc to select a starting node in the overcharge console's interface.", objectives = "" }
WordHunterWoW_QuestEN[90972] = { title = "A Common Cause", description = "{name}! I heard you were here on K'aresh. Good. I need help.\n \nMy apprentice Leona has been researching novel means of harnessing the power of the Void. She's approached a Demon Hunter named Adarus to see if the Illidari's methods could offer any insights.\n \nTo be honest, I'm not sure I trust Adarus. He's not... studious. Unlike Leona.\n \nLeona was just going to observe him as he sought to master the Void. But she's disappeared. Please find her. Talk with Adarus--he knows something.", objectives = "" }
WordHunterWoW_QuestEN[90993] = { title = "Take the Darkwell!", description = "We have our army but what lies behind these walls are the most powerful, most vile, and most empowered foes Xal'atath has in her arsenal. \n\nGather your strongest allies, {name}, and meet us within. It is time to end this and take back our well.", objectives = "" }
WordHunterWoW_QuestEN[90995] = { title = "The Future of The Fel Hammer", description = "Oh wait! Of course, right when I send you off I remember the most important thing!\n\nThe you-of-this-timeline made a critical choice for the future of all demon hunters. The follower they chose to be their personal champion created two diverging timelines for the fate of the Illidari.\n\nYou will need to choose which of these diverging timelines to explore. What rings true to you?", objectives = "" }
WordHunterWoW_QuestEN[91000] = { title = "A Humble Servant", description = "{name}, residents of Hammerfall have been focused on daily life, defense, and survival over the past months. \n\nThey have not had sufficient time, or frankly numbers, to address all the harms that were done.\n\nThere is much we can do to help them get back on their feet.\n\nI know this is humble work, but it makes a very real difference to the orcs who live here.", objectives = "" }
WordHunterWoW_QuestEN[91001] = { title = "Clear de Way", description = "With dey magic and dey line broken, de Twilight's Blade is losin' ground.\n\nWe must take advantage of dey turned backs.\n\nI will lead de charge through de ravine to de Conquerer's Sanctum beyond. Mor'duun is there, keepin' his coward-body safe from our spears and axes.\n\nHe won't be safe much longer.", objectives = "" }
WordHunterWoW_QuestEN[91009] = { title = "Durable Information Storage Container", description = "Adventurer, can you hear me? I've discovered a smaller titan device, the Durable Information Storage Container, which can fit on yer belt. I've deduced they'll be able tae play smaller titan discs, granting ye boons ye can use anywhere. \n\nEach of these devices need a jump start. If ye kick up enough dust in these delves it should generate a spark that the device will detect and collect. It should be enough tae power it for yer lifetime.", objectives = "" }
WordHunterWoW_QuestEN[91026] = { title = "Gathering an Upgrade", description = "Hello? Hello? You're back! Perfect!\n\nI was studying the titan console and gathering a bunch of new information from the overcharged areas including the faulty directives that were found. This might be the key to this unexpected behavior, but I'll need more time tae know for sure.\n\nReturn to the delves and we can check the results of the faulty directives, I can use the information to create an upgrade for yer belt!", objectives = "" }
WordHunterWoW_QuestEN[91030] = { title = "New Titan Directives", description = "My calculations need a lot more data. I've got another upgrade card nearly finished, but I'm not sure if it will integrate properly.\n\nBut if ye go back into the delve spaces and defeat more of the enemies, I can see how they react. Based on their reactions, I can put the final touches on this upgrade for yer belt.", objectives = "" }
WordHunterWoW_QuestEN[91031] = { title = "Pushing it to the Limit", description = "I realized after ye left last time that I might have worried ye a wee bit with the whole exploding belt upgrade possibility. I'm sorry. I get a bit excited sometimes.\n\nI do think I can get even more power out o' the belt. At least a bit more. Safely of course! In yer data, I've seen that you've encountered many enemies as ye entered many delves. That's the key, return one more time for this last upgrade for yer belt.", objectives = "" }
WordHunterWoW_QuestEN[91033] = { title = "Monitoring 'Construct'ing", description = "Welcome back, adventurer. I have a simple request for ye. I need ye tae continue monitorin' these titan constructs. \n\nWe have seen them moving around Azeroth in different locations, but I've not yet figured out their end goal or what instructions they might have. Perhaps if ye can gather more information, an insight will present itself.", objectives = "" }
WordHunterWoW_QuestEN[91035] = { title = "Construct De-Escalation", description = "Yer previous results showed a reduction in the overcharge present in the constructs. We must see if that was a one-off or if the reduction is escalatin'...\n\nHead back into these overcharged areas and test out the charge on the constructs, then report back.", objectives = "" }
WordHunterWoW_QuestEN[91038] = { title = "Hellhunters Wanted", description = "<A scorch-marked missive has been nailed to this wall.>\n\nHELL COMES FOR YOU!\n\nNow that we have your attention, please be warned that shards of brimstone have entered this world. They are warm to the touch and should not, under any circumstances, be stabbed into your head, the head of anyone else, or any other vital organ of you or anyone near you.\n\nPlease bring any shards you find IMMEDIATELY to us in Dornogal.\n\nAnd if you see any tiny little minions carrying a bag of treasures, KILL THEM ON SIGHT.", objectives = "" }
WordHunterWoW_QuestEN[91039] = { title = "Faerin's Request", description = "{name},\n\nGeya'rah and Danath have arrived in Dornogal. They both seem upset about rising tensions in the Arathi Highlands. It sounds serious.\n\nCan you come to Dornogal? I believe your presence can help the situation.\n\nFaerin", objectives = "" }
WordHunterWoW_QuestEN[91041] = { title = "A Gently Shaken Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[91042] = { title = "A Winter Veil Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[91044] = { title = "Hunger of the Void", description = "I did all I could to prevent this outcome. If you hadn't pushed him through the portal the unrestrained void energy would've collapsed the cave around us.\n\nHe was strong. In a way, I think that worked against him.\n\nMeet me back in Shan'dorah. I need to report to Umbric and let him know what happened here.", objectives = "" }
WordHunterWoW_QuestEN[91052] = { title = "Worldsoul: Overcharged Delves", description = "Something has caused hostile titan constructs to activate and enter various caverns and spaces around Khaz Algar. Venture to these locations and investigate and eliminate the threat they pose.", objectives = "" }
WordHunterWoW_QuestEN[91061] = { title = "Infinite Chaos", description = "You may think this ironic, but our time is running short, {name}. Great forces threaten more than one world's future.\n\nNozdormu won't like it, but I must hasten our study with experimentation. I have isolated a fractured timeline for you to explore. But be warned--this realm is devoid of all hope. It is the only way I can truly prepare us for what is to come.\n\nI have established a research console by the fel monument behind you. Use it to enter this forbidden future so that we may learn the unknowable.", objectives = "" }
WordHunterWoW_QuestEN[91062] = { title = "Broken Bridges", description = "I make one last request of you before you return with Liadrin to Silvermoon, hash'ura.\n\nFind Zul'jan. None have seen him since returnin' to Amani'Zar.\n\nOn de way back here, I confronted him about takin' our soldiers to Broken Throne against my orders.\n\nPeople died dat shouldn't have. I asked him what he don't understand about dat.\n\nHe didn't argue. He was blank. His body was there, but his mind?\n\nSometimes he seeks peace in de sound of ocean waves.\n\nYou might find him on de Skybridge.", objectives = "" }
WordHunterWoW_QuestEN[91063] = { title = "The Blooming Lattice", description = "You're that stranger I've been hearing about, aren't you? I'm Su'meera, apprentice painter to Ja'kul. You heard of him? No? Maybe his work hasn't made it to your lands. That makes sense, I guess.\n\nAnyhow, I heard you like helping people out. Well, a few important things went missing when Ja'kul was attacked and killed. I want them back.\n\nWill you meet me near Blooming Lattice?", objectives = "" }
WordHunterWoW_QuestEN[91065] = { title = "Purloining Petals", description = "A couple of days ago, a group of rutaani attacked and killed my mentor, Ja'kul. When they did, their stupid birds stole a few things from him. Those petals-for-brains will make off with anything shiny that isn't thorned down.\n\nWill you recover Ja'kul's things for me? I'm a painter, not a fighter. I wouldn't last very long in there on my own.", objectives = "" }
WordHunterWoW_QuestEN[91066] = { title = "Brewmaster's Kitchen", description = "Good, you've brought the supplies. Now, we begin the feast. We'll need plenty of food to keep up our strength.\n\nThe menu's simple, but worthy: Barley Stew, Stone-baked Pretzels, and a strong brew to fuel the Horde!\n\nAre you prepared to learn?", objectives = "" }
WordHunterWoW_QuestEN[91067] = { title = "Gathering the Grub", description = "Ah, you're here. Brewfest has begun-but we've got a problem. Can't have a proper feast without food, and some thieving hozen thought it'd be clever to snatch our grub.\n\nHere's what you'll do: track down those hozen and take back what's ours. You might find a few bags just lying around too-grab those. Once you've got the goods, toss them in the wagon behind me.", objectives = "" }
WordHunterWoW_QuestEN[91068] = { title = "Serving with Style", description = "You've proven your strength at cooking, now it's time to prove it on the floor! Brewfest isn't just about feastin-it's about bringing the revelry to every corner of the camp.\n\nYou'll be taking orders, hauling plates, and pouring ale like a true warrior of celebration.\n\nNow get out there and show them what real service looks like! Brewfest don't run on empty mugs!", objectives = "" }
WordHunterWoW_QuestEN[91069] = { title = "Vengeance for Tolbani", description = "Me and Tolbani had loaded de skiff with medicine, steel, and food to bring upriver to de forward camp.\n\nIt was meant to be a quiet run: no trouble, and no eyes on us.\n\nBut in de shallows, de murlocs came swarmin' out of de reeds all foam and teeth. Dey hit us hard--too fast to fight back proper. We tipped and lost de cargo. I barely made it to shore.\n\nTolbani didn't. I dragged his dart-riddled body here.\n\nDe murlocs must pay for what dey have done.", objectives = "" }
WordHunterWoW_QuestEN[91070] = { title = "Reclaim the Goods", description = "While I was limping back from de river, I spotted a few of de murlocs dragging our food bags through de mud. They weren't working together either--kept snapping at each other, trying to snatch de best pieces for themselves.\n\nI saw one of them stash a whole satchel behind a fallen tree. Another buried something under a pile of rocks. Greedy little monsters think they can steal from us and get away with it.", objectives = "" }
WordHunterWoW_QuestEN[91071] = { title = "The Menace of Atal'Abasi", description = "Our boat didn't ground on its own.\n\nWe were fightin' de murlocs, and then suddenly we were in de air.\n\nDats when I saw him--one dat wasn't like de rest. Bigger. Stronger. When he attacked, de other murlocs scattered.\n\nHe picked up our boat like it weighed nothin' and hurled it on de rocks. I've never seen a murloc do somethin' like that.\n\nWe're gonna keep losin' people and supplies if dat muscle-bound murloc is watchin' de river.", objectives = "" }
WordHunterWoW_QuestEN[91084] = { title = "Looming Shadows", description = "Though we've triumphed over Ruia and the Lightbloom for now, more remains to be done. The elders will want to convene regarding the Hara'ti's new place in the world, now that we have stepped out from the shadows of our past.\n\nOur reticence and fear will not vanish overnight. But this is an important first step.\n\nWe will be fine, {name}. Let Orweyna and I deal with the elders. When the time comes, the Hara'ti shall be at your side. For now, though, I'd imagine you have more pressing matters to attend to.", objectives = "" }
WordHunterWoW_QuestEN[91085] = { title = "Petal Bristles", description = "Ja'kul was out hunting petalwings when the rutaani came upon him and killed him. We use their feathers for some of our paintbrushes. They are especially useful in helping the young sprouts learn how to be more precise and delicate. \n\nWhile you're up there, will you bring me back some of their plumes?", objectives = "" }
WordHunterWoW_QuestEN[91086] = { title = "Nipping the Buds", description = "The rutaani of Blooming Lattice were behind the attack on Ja'kul. They're led by a Prime Bloomwarden who's even more vicious. I hate them and they're all terrible!\n\nHow about you go prune the overgrowth and make the rest of us safer?", objectives = "" }
WordHunterWoW_QuestEN[91087] = { title = "Reports Returned", description = "I will go to Silvermoon but... I will return here to advise Zul'jarra.\n\nI feel I let my past and my prejudices get in the way of my judgement regarding the Amani. You could say that being a hash'ura is a befitting atonement but... I feel drawn to stay, perhaps to help Zul'jarra in guiding her people back to the loa.\n\nI will go to Silvermoon with you to bear the report--and Lor'themar's reaction.\n\nIf we go now, we may return to... party.\n\n<A small smile cracks Liadrin's usually stoic face.>", objectives = "" }
WordHunterWoW_QuestEN[91088] = { title = "Behind the Falls", description = "The scroll you brought back was left behind for me by my mentor, Ja'kul. I didn't even have a chance to read it before it was stolen away! \n\nJa'kul left directions in the scroll to a cave that's behind a waterfall in Blooming Lattice. I'm not sure what we'll find there, but I would really appreciate if you came along while I check it out. Will you meet me there?", objectives = "" }
WordHunterWoW_QuestEN[91089] = { title = "Defeating Ky'veza", description = "So she's here to collect a bounty, eh?\n\nDid nae one tell her it's rude to try and kill a Champion of Azeroth? Or a Bronzebeard, for that matter?", objectives = "" }
WordHunterWoW_QuestEN[91090] = { title = "Pesky Pests", description = "Nearby creatures are suffering an infection of Light, and are being drawn to the Sunbath. Our guests find it disturbing. That is a problem, when one is trying to enjoy a tranquil escape from the world.\n\nI confess, having one run into your leg while you are swimming can be unnerving.\n\nPlease, dissuade the invading sungrubs from joining us, and take to the sky to chase off those persistent butterflies.", objectives = "" }
WordHunterWoW_QuestEN[91093] = { title = "More Than Just a Phase", description = "Untethered Space represents an ongoing danger to our people on K'aresh. It is infested with banished souls, broken technology, and monsters of all kinds.\n\nAid the K'aresh Trust and defeat our foes in Untethered Space. You may use the Phase Conduits to navigate between the remnants of K'aresh while phase diving.", objectives = "" }
WordHunterWoW_QuestEN[91095] = { title = "Prey: Magister Sunbreaker (Normal)", description = "Once a noble Magister of Silvermoon, sworn to protect Quel'Thalas at any cost, he has broken away from the order and now seeks vengeance on his own terms.\n\nI see something of myself in him.\n\nKill it for me.", objectives = "" }
WordHunterWoW_QuestEN[91096] = { title = "Prey: Magistrix Emberlash (Normal)", description = "Alas, you can only catch so many innocent bystanders in your fireballs before you find yourself ostracized from polite society. Emberlash was always more interested in flame than friends...\n\nShe has burned one too many mutual acquaintances. \n\nIf she will not control her power, we will gladly take it for our own.", objectives = "" }
WordHunterWoW_QuestEN[91097] = { title = "Prey: Senior Tinker Ozwold (Normal)", description = "Rumor has it that Ozwold single-handedly raised insurance premiums in Gnomeregan before their little exodus. Be that as it may, he's consistently taken to perfecting his gadgetry regardless of the cost to others.\n\nHis ambition is admirable, but his methods are irredeemable. \n\nGo and see that his inventing days come to an end.", objectives = "" }
WordHunterWoW_QuestEN[91098] = { title = "Prey: L-N-0R the Recycler (Normal)", description = "Do you know why they call her the Recycler, {name}? I don't. And given her history of \"disappearing\" shop assistants, I'm not really inclined to ask her.\n\nThat being said, watch your step. I understand that she likes to incorporate her victims into her gadgetry. We wouldn't want you becoming a pocket watch or some such thing.", objectives = "" }
WordHunterWoW_QuestEN[91099] = { title = "Prey: Mordril Shadowfell (Normal)", description = "The Void is a perfidious thing, like water. The wise keep it at a respectful distance, never dancing too close to the edge. The foolish dive in, and in so doing, drown.\n\nMordril is a danger to himself and everyone around him, so lost is he in his own obsession.\n\nSee to it that he no longer poses a threat to this realm.", objectives = "" }
WordHunterWoW_QuestEN[91100] = { title = "Prey: Deliah Gloomsong (Normal)", description = "In a previous life, Deliah Gloomsong was a prodigious student--truly a marvel of ambition, talent, and unrelenting curiosity. \n\nIt was the latter that got the best of her.\n\nPut an end to her murderous spree.", objectives = "" }
WordHunterWoW_QuestEN[91101] = { title = "Prey: Phaseblade Talasha (Normal)", description = "Ethereals... they make my skin crawl. Esoteric. Unknowable. I don't trust anything I can't look in the eyes while it grovels before me.\n\nMy scouts report that a particularly dangerous ethereal is active in a nearby region. We would do well to nip this in the bud while we still can.", objectives = "" }
WordHunterWoW_QuestEN[91102] = { title = "Prey: Nexus-Edge Hadim (Normal)", description = "Our activities are drawing unwanted attention. I have heard whispers that a powerful ethereal assassin is on my... on our trail. It would be very difficult indeed to defend our city as twin piles of bloody ribbons.\n\nGo out there and show this \"assassin\" the true art of the kill.", objectives = "" }
WordHunterWoW_QuestEN[91103] = { title = "Prey: Jo'zolo the Breaker (Normal)", description = "Jo'zolo the Breaker is a troll who abides by his name. Long has he been the bane of our scouts, but no more! \n\nKill him. Feed his anguish to the defenses of our beloved city.", objectives = "" }
WordHunterWoW_QuestEN[91104] = { title = "Prey: Zadu, Fist of Nalorakk (Normal)", description = "Our neighbors produce some of the most skilled hunters in all of Azeroth. It is a shame they are so difficult to reason with. \n \nThere is one named Zadu. Her anguish would make for a most excellent trophy...", objectives = "" }
WordHunterWoW_QuestEN[91105] = { title = "Prey: The Talon of Jan'alai (Normal)", description = "There is a powerful troll shaman who calls himself the Talon of Jan'alai. Long has he confounded our city's Farstriders, sowing confusion and death in his wake.\n\nSee to it that he joins the spirits he so ardently venerates.", objectives = "" }
WordHunterWoW_QuestEN[91106] = { title = "Prey: The Wing of Akil'zon (Normal)", description = "Do you smell that? There is death on the air. This can only mean one thing. The Wing of Akil'zon is near. Go out and slay her.\n\nOh, and be careful. She's responsible for more than one lost Farstrider patrol.", objectives = "" }
WordHunterWoW_QuestEN[91107] = { title = "Prey: Ranger Swiftglade (Normal)", description = "It is a difficult thing, to hunt one of our own. Ranger Swiftglade is beyond redemption. His bloodlust could not be sated against our foes, and he has since turned his martial prowess upon his own people.\n\nEnd his sadistic killing spree and put his anguish to better use.", objectives = "" }
WordHunterWoW_QuestEN[91108] = { title = "Prey: Lieutenant Blazewing (Normal)", description = "I do not know what to make of Lieutenant Blazewing. Her entire patrol disappeared during a reconnaissance mission into Zul'Aman. She was the sole survivor, but she returned with a fiery bloodlust and a complete disregard for the lives of others. \n\nWhether this is possession or sedition I am unsure, but she must be dealt with.", objectives = "" }
WordHunterWoW_QuestEN[91109] = { title = "Prey: Petyoll the Razorleaf (Normal)", description = "Reports are coming in of shredded Farstriders adorned with petals and berries--entire patrols found strung up by razor-vines. There are more gruesome details, but they chafe even my... refined sensibilities. \n\nHunt whatever manner of creature is embarking on this horrific killing spree, and see to it that its anguish is added to our crystals.", objectives = "" }
WordHunterWoW_QuestEN[91110] = { title = "Prey: Lamyne of the Undercroft (Normal)", description = "Do you garden, {name}? I've been known to dabble. It seems the plants in our realm are becoming somewhat overbearing these days, sprouting legs and arms and running around murdering our brave soldiers. \n\nLet's give them a bit of a pruning, shall we?", objectives = "" }
WordHunterWoW_QuestEN[91111] = { title = "Prey: High Vindicator Vureem (Normal)", description = "High Vindicator Vureem is a victim of his own unyielding faith in the Light and the superiority it gives him. His crusade continues unabated and unresolved. He exists in a constant state of fury at the imperfectness of the world and those within it.\n\nIn the absence of total purity, Vureem sees only violence and the shadows of his own dogma. \n\nWhat say we put his worldview to the test?", objectives = "" }
WordHunterWoW_QuestEN[91112] = { title = "Prey: Crusader Luxia Maxwell (Normal)", description = "We are not sure if Luxia Maxwell is a deserter or has simply decided to embark on her own personal crusade. Regardless, reports are coming in of her attacking both friend and foe alike, yelling aphorisms of purity and duty.\n\nShe has become a liability to the defense of Silvermoon. \n\nGo and harvest her anguish.", objectives = "" }
WordHunterWoW_QuestEN[91113] = { title = "Prey: Praetor Singularis (Normal)", description = "The domanaar...\n\n<Astalor shudders.>\n\nI do not profess to know much about them, other than their proclivity for subterfuge, guile, and the absolute destruction of anything that stands before them. Praetor Singularis is no exception. They have been confounding our forces at every turn.\n\nGo and put an end to their games.", objectives = "" }
WordHunterWoW_QuestEN[91114] = { title = "Prey: Consul Nebulor (Normal)", description = "I have heard that there is one under Xal'atath's command who takes particular delight in dominating their foes. Whispers of a domanaar that taunts its victims with whispers and riddles before annihilating their mortal coil with void magic.\n  \nConsul Nebulor is their name.\n\nGo and show them the limits of their power.", objectives = "" }
WordHunterWoW_QuestEN[91115] = { title = "Prey: Executor Kaenius (Normal)", description = "The domanaar have a reputation for guile and cunning, but there are brutes among them: those who seek to dominate their victims through sheer power and force of will.\n\nExecutor Kaenius is one such domanaar.\n\nThey stalk the battlefield, singling out our strongest soldiers and viciously cutting them down.\n\nPut an end to their rampage.", objectives = "" }
WordHunterWoW_QuestEN[91116] = { title = "Prey: Imperator Enigmalia (Normal)", description = "Imperator Enigmalia is personally responsible for the deaths of at least a dozen Farstriders. I say \"at least\" because this particular domanaar makes it somewhat difficult to identify the bodies, so utterly destroyed are they.\n\nGo and avenge our fallen soldiers.", objectives = "" }
WordHunterWoW_QuestEN[91117] = { title = "Prey: Knight-Errant Bloodshatter (Normal)", description = "Death knights are unstable killing machines at the best of times. Knight-Errant Bloodshatter has forsaken any oath or promise that would ostensibly bind one of his kind to the bottom rungs of civilized society, and has gone completely rogue.\n \nHe is starting to become a liability. \n\nRecoup his anguish so that we can make the best of such an unfortunate situation.", objectives = "" }
WordHunterWoW_QuestEN[91118] = { title = "Prey: Vylenna the Defector (Normal)", description = "Vylenna the Defector lives up to her name. After a recent engagement on the field of battle, she became so preoccupied with profaning the dead that she completely abandoned the duties ascribed to her.\n\nThen her dereliction turned violent.\n\nA veritable font of anguish if you ask me...", objectives = "" }
WordHunterWoW_QuestEN[91119] = { title = "Prey: Lost Theldrin (Normal)", description = "Those of us who succumbed to our base desire for mana were slowly weeded out of civil society, if they survived at all. Theldrin is one such example, only it is a testament to his cunning and will to live that he has made it as long as he has.\n\nHe accepts no aid, choosing instead to stalk careless students and idle Magisters. His sole obsession is the mana that others possess...\n\nSee to it that he never harms another elf again.", objectives = "" }
WordHunterWoW_QuestEN[91120] = { title = "Prey: Neydra the Starving (Normal)", description = "Poor Neydra... I knew her, in a previous life. She was full of vitality. Full of ambition. Unfortunately, she let that ambition get the best of her. She grew too enamored with the raw power of the arcane. She became resentful of all other things. Of all other people...\n\nAnd now she is a murderous creature who beheads rats and attacks innocents in a desperate attempt to garner enough arcane energy to slake her unquenchable thirst.\n\nIt's funny, the paths life takes us...", objectives = "" }
WordHunterWoW_QuestEN[91121] = { title = "Prey: Thornspeaker Edgath (Normal)", description = "This one presents a prickly problem indeed. Thornspeaker Edgath has made a name for himself by using his druidic powers not to preserve Azeroth, but to twist its strength both against his enemies and innocent bystanders alike. He has no regard for anything that is not a beast or growing in the ground.\n\nIt is time we clip this thorn.", objectives = "" }
WordHunterWoW_QuestEN[91122] = { title = "Prey: Thorn-Witch Liset (Normal)", description = "Thorn-Witch Liset is a curse upon civilization and a blight upon the land itself. She twists the very trees and beasts, communing with the dark, evil things that live on the very edges of the natural realm.\n\nI despise the natural realm.", objectives = "" }
WordHunterWoW_QuestEN[91123] = { title = "Prey: Grothoz, the Burning Shadow (Normal)", description = "The Twilight's Blade are an embarrassing band of mediocre cultists and uninspired conspirators. Grothoz is the brains of a particularly stupid cabal that has been active in a nearby region. \n\nAs his stupidity prevents him from using his whole brain, let us unlock his potential for him...", objectives = "" }
WordHunterWoW_QuestEN[91124] = { title = "Prey: Dengzag, the Darkened Blaze (Normal)", description = "Do you know why the Twilight's Blade call Dengzag the \"Darkened Blaze?\" It is because they are stupid, small-minded, and utterly bereft of imagination. What a silly name indeed. \n\nI, however, am not small-minded. I have quite the prodigious mind, and it is currently intent on putting an end to Dengzag and whatever his tiny brain is up to. \n\nGet to it.", objectives = "" }
WordHunterWoW_QuestEN[91136] = { title = "Memories in Stone", description = "Ja'kul was killed before he could finish my training, but I would recognize his work anywhere! He must have painted this vision stone for me!\n\nThe rutaani will catch on pretty soon that we're up here, and I won't be able to defend myself. Will you keep watch while I journey into the memory he left me?", objectives = "" }
WordHunterWoW_QuestEN[91137] = { title = "Lost in Light", description = "It seems some of our more adventurous guests have not returned from their hike. Val said he saw a rutaani skulking about earlier, but I was certain he was just trying to add some drama to our day.\n\nThe Lightbloom infiltrated the Sanctum to the north and has been spilling residual issues our way.\n\nOur guests are here to escape the troubles of the world... This all could become a bit too real for them.\n\nIf you'll take care of that situation, I'll make sure Val keeps the guests distracted.", objectives = "" }
WordHunterWoW_QuestEN[91138] = { title = "I am the Creator and Destroyer", description = "Such a small thing, really. And devoid of any of the power T'uure once nurtured. But a relic of inestimable value nonetheless.\n\nDid you know, {class}, that to T'uure, the dark and the light were inseparable aspects of a greater truth?\n\nWhat creates, has the power to destroy in equal measure. Demonstrate this lesson and you will reach a new understanding of yourself, and of the great Naaru whose sacrifice was able to halt the annihilation of an entire planet.", objectives = "" }
WordHunterWoW_QuestEN[91140] = { title = "A Piece of the Past", description = "<This crystalline fragment has lost any luster it once had. Now finally extricated from Dimensius's dread form and in the hands of the devout, a brief glimmer revives in its depths.\n\nPerhaps someone in Tazavesh will know more.>", objectives = "" }
WordHunterWoW_QuestEN[91142] = { title = "Tabard for the Trusted", description = "", objectives = "" }
WordHunterWoW_QuestEN[91145] = { title = "The Conquered Heroes", description = "A domanaar was harrying our back lines. It was... different than the other void beasts--like it was playing rather than fighting. My partner, Callum, led a squad to hunt it down. They never came back.\n\nCallum's an Arathi through and through. He wouldn't fall here--I know it.\n\nCommander Lightblood refused to send a search party. He said there's a difference between personal and important. Well, the Vanguard can have their war, but I'm going after Cal. I know the route he took, but I can't search alone.", objectives = "" }
WordHunterWoW_QuestEN[91146] = { title = "Flickering Light", description = "I feel traces of Light here--dim, scattered across the plain, but unmistakable. It's Callum. I know his Light like I know my own.\n\nThat domanaar is a monster: using others like toys, smashing them together until they break. We'll find them, {name}, and then I will turn that void beast to ash.\n\n<Anais grips her spear.>\n\nOne thing at a time. Find the Light, and we find Callum.", objectives = "" }
WordHunterWoW_QuestEN[91147] = { title = "Cut Her Strings", description = "Revik, Riandron, Danna... that domanaar made them kill each other. The creatures here are bound with the same shadowgrafts: the same twisted magic.\n\nIf this is how Imperia controls her victims, we have to find a way to remove it.\n\nRestrain the beasts and I'll attempt to break their bonds. If it's forged by the Void, the Light must be able to overcome it.", objectives = "" }
WordHunterWoW_QuestEN[91148] = { title = "Strung Along", description = "When the Light called, it called both of us. Why? So Callum could die on some void-scarred rock?\n\nI can't think here. All I can picture is Callum bleeding out. Come, we'll return to camp. With his belongings, I should be able to find him. \n\nThen... I don't know. If we can't break the shadowgrafts, we'll subdue him and drag him back to Silvermoon if we must. I'm not losing him.", objectives = "" }
WordHunterWoW_QuestEN[91149] = { title = "Bury Me Not", description = "I knew we'd never grow old together, but I thought we'd have more time.\n\n<Anais coughs, blood pooling beneath her. Flecks of the Void shimmer in the spreading crimson.>\n\nDon't worry. I'm not afraid. I promised myself I wouldn't go home without him... wouldn't spend a night in an empty bed. I'm just keeping that promise.\n\nDon't let her have him. Take his tinder box. You'll know what to do.", objectives = "" }
WordHunterWoW_QuestEN[91173] = { title = "The Flame Burns Eternal", description = "These Sureki sure are a persistent bunch! We need to match their persistence with our blades.\n\nCan we count on your continued support in the battles ahead?", objectives = "" }
WordHunterWoW_QuestEN[91206] = { title = "Loa Disturbance", description = "Now dat we are tryin' to contact all de loa, my mind turns to Kulzi, de loa of medicine--and the madness that surrounds his shrine.\n\nHis loa speaker, Sij'ta, was a good friend. He healed many war parties of their injuries. But somethin' happened at Kulzi's shrine, and it is full of angry spirits.\n\nDey attack anybody dat tries to get through to dem, and de loa is silent.\n\nPerhaps you can finally reach out to de loa and find his speaker!", objectives = "" }
WordHunterWoW_QuestEN[91210] = { title = "Prey: Magister Sunbreaker (Hard)", description = "Once a noble Magister of Silvermoon, sworn to protect Quel'Thalas at any cost, he has broken away from the order and now seeks vengeance on his own terms.\n\nI see something of myself in him.\n\nKill it for me.", objectives = "" }
WordHunterWoW_QuestEN[91211] = { title = "Prey: Magister Sunbreaker (Nightmare)", description = "Once a noble Magister of Silvermoon, sworn to protect Quel'Thalas at any cost, he has broken away from the order and now seeks vengeance on his own terms.\n\nI see something of myself in him.\n\nKill it for me.", objectives = "" }
WordHunterWoW_QuestEN[91212] = { title = "Prey: Magistrix Emberlash (Hard)", description = "Alas, you can only catch so many innocent bystanders in your fireballs before you find yourself ostracized from polite society. Emberlash was always more interested in flame than friends...\n\nShe has burned one too many mutual acquaintances. \n\nIf she will not control her power, we will gladly take it for our own.", objectives = "" }
WordHunterWoW_QuestEN[91213] = { title = "Prey: Magistrix Emberlash (Nightmare)", description = "Alas, you can only catch so many innocent bystanders in your fireballs before you find yourself ostracized from polite society. Emberlash was always more interested in flame than friends...\n\nShe has burned one too many mutual acquaintances. \n\nIf she will not control her power, we will gladly take it for our own.", objectives = "" }
WordHunterWoW_QuestEN[91214] = { title = "Prey: Senior Tinker Ozwold (Hard)", description = "Rumor has it that Ozwold single-handedly raised insurance premiums in Gnomeregan before their little exodus. Be that as it may, he's consistently taken to perfecting his gadgetry regardless of the cost to others.\n\nHis ambition is admirable, but his methods are irredeemable. \n\nGo and see that his inventing days come to an end.", objectives = "" }
WordHunterWoW_QuestEN[91215] = { title = "Prey: Senior Tinker Ozwold (Nightmare)", description = "Rumor has it that Ozwold single-handedly raised insurance premiums in Gnomeregan before their little exodus. Be that as it may, he's consistently taken to perfecting his gadgetry regardless of the cost to others.\n\nHis ambition is admirable, but his methods are irredeemable. \n\nGo and see that his inventing days come to an end.", objectives = "" }
WordHunterWoW_QuestEN[91216] = { title = "Prey: L-N-0R the Recycler (Hard)", description = "Do you know why they call her the Recycler, {name}? I don't. And given her history of \"disappearing\" shop assistants, I'm not really inclined to ask her.\n\nThat being said, watch your step. I understand that she likes to incorporate her victims into her gadgetry. We wouldn't want you becoming a pocket watch or some such thing.", objectives = "" }
WordHunterWoW_QuestEN[91217] = { title = "Prey: L-N-0R the Recycler (Nightmare)", description = "Do you know why they call her the Recycler, {name}? I don't. And given her history of \"disappearing\" shop assistants, I'm not really inclined to ask her.\n\nThat being said, watch your step. I understand that she likes to incorporate her victims into her gadgetry. We wouldn't want you becoming a pocket watch or some such thing.", objectives = "" }
WordHunterWoW_QuestEN[91218] = { title = "Prey: Mordril Shadowfell (Hard)", description = "The Void is a perfidious thing, like water. The wise keep it at a respectful distance, never dancing too close to the edge. The foolish dive in, and in so doing, drown.\n \nMordril is a danger to himself and everyone around him, so lost is he in his own obsession.\n\nSee to it that he no longer poses a threat to this realm.", objectives = "" }
WordHunterWoW_QuestEN[91219] = { title = "Prey: Mordril Shadowfell (Nightmare)", description = "The Void is a perfidious thing, like water. The wise keep it at a respectful distance, never dancing too close to the edge. The foolish dive in, and in so doing, drown.\n \nMordril is a danger to himself and everyone around him, so lost is he in his own obsession.\n\nSee to it that he no longer poses a threat to this realm.", objectives = "" }
WordHunterWoW_QuestEN[91220] = { title = "Prey: Deliah Gloomsong (Hard)", description = "In a previous life, Deliah Gloomsong was a prodigious student--truly a marvel of ambition, talent, and unrelenting curiosity. \n\nIt was the latter that got the best of her.\n\nPut an end to her murderous spree.", objectives = "" }
WordHunterWoW_QuestEN[91221] = { title = "Prey: Deliah Gloomsong (Nightmare)", description = "In a previous life, Deliah Gloomsong was a prodigious student--truly a marvel of ambition, talent, and unrelenting curiosity. \n\nIt was the latter that got the best of her.\n\nPut an end to her murderous spree.", objectives = "" }
WordHunterWoW_QuestEN[91222] = { title = "Prey: Phaseblade Talasha (Hard)", description = "Ethereals... they make my skin crawl. Esoteric. Unknowable. I don't trust anything I can't look in the eyes while it grovels before me.\n\nMy scouts report that a particularly dangerous ethereal is active in a nearby region. We would do well to nip this in the bud while we still can.", objectives = "" }
WordHunterWoW_QuestEN[91223] = { title = "Prey: Phaseblade Talasha (Nightmare)", description = "Ethereals... they make my skin crawl. Esoteric. Unknowable. I don't trust anything I can't look in the eyes while it grovels before me.\n\nMy scouts report that a particularly dangerous ethereal is active in a nearby region. We would do well to nip this in the bud while we still can.", objectives = "" }
WordHunterWoW_QuestEN[91224] = { title = "Prey: Nexus-Edge Hadim (Hard)", description = "Our activities are drawing unwanted attention. I have heard whispers that a powerful ethereal assassin is on my... on our trail. It would be very difficult indeed to defend our city as twin piles of bloody ribbons.\n\nGo out there and show this \"assassin\" the true art of the kill.", objectives = "" }
WordHunterWoW_QuestEN[91225] = { title = "Prey: Nexus-Edge Hadim (Nightmare)", description = "Our activities are drawing unwanted attention. I have heard whispers that a powerful ethereal assassin is on my... on our trail. It would be very difficult indeed to defend our city as twin piles of bloody ribbons.\n\nGo out there and show this \"assassin\" the true art of the kill.", objectives = "" }
WordHunterWoW_QuestEN[91226] = { title = "Prey: Jo'zolo the Breaker (Hard)", description = "Jo'zolo the Breaker is a troll who abides by his name. Long has he been the bane of our scouts, but no more! \n\nKill him. Feed his anguish to the defenses of our beloved city.", objectives = "" }
WordHunterWoW_QuestEN[91227] = { title = "Prey: Jo'zolo the Breaker (Nightmare)", description = "Jo'zolo the Breaker is a troll who abides by his name. Long has he been the bane of our scouts, but no more! \n\nKill him. Feed his anguish to the defenses of our beloved city.", objectives = "" }
WordHunterWoW_QuestEN[91228] = { title = "Prey: Zadu, Fist of Nalorakk (Hard)", description = "Our neighbors produce some of the most skilled hunters in all of Azeroth. It is a shame they are so difficult to reason with. \n \nThere is one named Zadu. Her anguish would make for a most excellent trophy...", objectives = "" }
WordHunterWoW_QuestEN[91229] = { title = "Prey: Zadu, Fist of Nalorakk (Nightmare)", description = "Our neighbors produce some of the most skilled hunters in all of Azeroth. It is a shame they are so difficult to reason with.\n\nThere is one named Zadu. Her anguish would make for a most excellent trophy...", objectives = "" }
WordHunterWoW_QuestEN[91230] = { title = "Prey: The Talon of Jan'alai (Hard)", description = "There is a powerful troll shaman who calls himself the Talon of Jan'alai. Long has he confounded our city's Farstriders, sowing confusion and death in his wake.\n\nSee to it that he joins the spirits he so ardently venerates.", objectives = "" }
WordHunterWoW_QuestEN[91231] = { title = "Prey: The Talon of Jan'alai (Nightmare)", description = "There is a powerful troll shaman who calls himself the Talon of Jan'alai. Long has he confounded our city's Farstriders, sowing confusion and death in his wake.\n\nSee to it that he joins the spirits he so ardently venerates.", objectives = "" }
WordHunterWoW_QuestEN[91232] = { title = "Prey: The Wing of Akil'zon (Hard)", description = "Do you smell that? There is death on the air. This can only mean one thing. The Wing of Akil'zon is near. Go out and slay her.\n\nOh, and be careful. She's responsible for more than one lost Farstrider patrol.", objectives = "" }
WordHunterWoW_QuestEN[91233] = { title = "Prey: The Wing of Akil'zon (Nightmare)", description = "Do you smell that? There is death on the air. This can only mean one thing. The Wing of Akil'zon is near. Go out and slay her.\n\nOh, and be careful. She's responsible for more than one lost Farstrider patrol.", objectives = "" }
WordHunterWoW_QuestEN[91234] = { title = "Prey: Ranger Swiftglade (Hard)", description = "It is a difficult thing, to hunt one of our own. Ranger Swiftglade is beyond redemption. His bloodlust could not be sated against our foes, and he has since turned his martial prowess upon his own people.\n\nEnd his sadistic killing spree and put his anguish to better use.", objectives = "" }
WordHunterWoW_QuestEN[91235] = { title = "Prey: Ranger Swiftglade (Nightmare)", description = "It is a difficult thing, to hunt one of our own. Ranger Swiftglade is beyond redemption. His bloodlust could not be sated against our foes, and he has since turned his martial prowess upon his own people.\n\nEnd his sadistic killing spree and put his anguish to better use.", objectives = "" }
WordHunterWoW_QuestEN[91236] = { title = "Prey: Lieutenant Blazewing (Hard)", description = "I do not know what to make of Lieutenant Blazewing. Her entire patrol disappeared during a reconnaissance mission into Zul'Aman. She was the sole survivor, but she returned with a fiery bloodlust and a complete disregard for the lives of others. \n\nWhether this is possession or sedition I am unsure, but she must be dealt with.", objectives = "" }
WordHunterWoW_QuestEN[91237] = { title = "Prey: Lieutenant Blazewing (Nightmare)", description = "I do not know what to make of Lieutenant Blazewing. Her entire patrol disappeared during a reconnaissance mission into Zul'Aman. She was the sole survivor, but she returned with a fiery bloodlust and a complete disregard for the lives of others. \n\nWhether this is possession or sedition I am unsure, but she must be dealt with.", objectives = "" }
WordHunterWoW_QuestEN[91238] = { title = "Prey: Petyoll the Razorleaf (Hard)", description = "Reports are coming in of shredded Farstriders adorned with petals and berries--entire patrols found strung up by razor-vines. There are more gruesome details, but they chafe even my... refined sensibilities. \n\nHunt whatever manner of creature is embarking on this horrific killing spree, and see to it that its anguish is added to our crystals.", objectives = "" }
WordHunterWoW_QuestEN[91239] = { title = "Prey: Petyoll the Razorleaf (Nightmare)", description = "Reports are coming in of shredded Farstriders adorned with petals and berries--entire patrols found strung up by razor-vines. There are more gruesome details, but they chafe even my... refined sensibilities. \n\nHunt whatever manner of creature is embarking on this horrific killing spree, and see to it that its anguish is added to our crystals.", objectives = "" }
WordHunterWoW_QuestEN[91240] = { title = "Prey: Lamyne of the Undercroft (Hard)", description = "Do you garden, {name}? I've been known to dabble. It seems the plants in our realm are becoming somewhat overbearing these days, sprouting legs and arms and running around murdering our brave soldiers. \n\nLet's give them a bit of a pruning, shall we?", objectives = "" }
WordHunterWoW_QuestEN[91241] = { title = "Prey: Lamyne of the Undercroft (Nightmare)", description = "Do you garden, {name}? I've been known to dabble. It seems the plants in our realm are becoming somewhat overbearing these days, sprouting legs and arms and running around murdering our brave soldiers. \n\nLet's give them a bit of a pruning, shall we?", objectives = "" }
WordHunterWoW_QuestEN[91242] = { title = "Prey: High Vindicator Vureem (Hard)", description = "High Vindicator Vureem is a victim of his own unyielding faith in the Light and the superiority it gives him. His crusade continues unabated and unresolved. He exists in a constant state of fury at the imperfectness of the world and those within it.\n\nIn the absence of total purity, Vureem sees only violence and the shadows of his own dogma. \n\nWhat say we put his worldview to the test?", objectives = "" }
WordHunterWoW_QuestEN[91243] = { title = "Prey: Crusader Luxia Maxwell (Hard)", description = "We are not sure if Luxia Maxwell is a deserter or has simply decided to embark on her own personal crusade. Regardless, reports are coming in of her attacking both friend and foe alike, yelling aphorisms of purity and duty.\n\nShe has become a liability to the defense of Silvermoon. \n\nGo and harvest her anguish.", objectives = "" }
WordHunterWoW_QuestEN[91244] = { title = "Prey: Praetor Singularis (Hard)", description = "The domanaar...\n\n<Astalor shudders.>\n\nI do not profess to know much about them, other than their proclivity for subterfuge, guile, and the absolute destruction of anything that stands before them. Praetor Singularis is no exception. They have been confounding our forces at every turn.\n\nGo and put an end to their games.", objectives = "" }
WordHunterWoW_QuestEN[91245] = { title = "Prey: Consul Nebulor (Hard)", description = "I have heard that there is one under Xal'atath's command who takes particular delight in dominating their foes. Whispers of a domanaar that taunts its victims with whispers and riddles before annihilating their mortal coil with void magic. \n \nConsul Nebulor is their name.\n\nGo and show them the limits of their power.", objectives = "" }
WordHunterWoW_QuestEN[91246] = { title = "Prey: Executor Kaenius (Hard)", description = "The domanaar have a reputation for guile and cunning, but there are brutes among them: those who seek to dominate their victims through sheer power and force of will.\n\nExecutor Kaenius is one such domanaar.\n\nThey stalk the battlefield, singling out our strongest soldiers and viciously cutting them down.\n\nPut an end to their rampage.", objectives = "" }
WordHunterWoW_QuestEN[91247] = { title = "Prey: Imperator Enigmalia (Hard)", description = "Imperator Enigmalia is personally responsible for the deaths of at least a dozen Farstriders. I say \"at least\" because this particular domanaar makes it somewhat difficult to identify the bodies, so utterly destroyed are they.\n\nGo and avenge our fallen soldiers.", objectives = "" }
WordHunterWoW_QuestEN[91248] = { title = "Prey: Knight-Errant Bloodshatter (Hard)", description = "Death knights are unstable killing machines at the best of times. Knight-Errant Bloodshatter has forsaken any oath or promise that would ostensibly bind one of his kind to the bottom rungs of civilized society, and has gone completely rogue.\n\nHe is starting to become a liability.\n\nRecoup his anguish so that we can make the best of such an unfortunate situation.", objectives = "" }
WordHunterWoW_QuestEN[91249] = { title = "Prey: Vylenna the Defector (Hard)", description = "Vylenna the Defector lives up to her name. After a recent engagement on the field of battle, she became so preoccupied with profaning the dead that she completely abandoned the duties ascribed to her.\n \nThen her dereliction turned violent.\n\nA veritable font of anguish if you ask me...", objectives = "" }
WordHunterWoW_QuestEN[91250] = { title = "Prey: Lost Theldrin (Hard)", description = "Those of us who succumbed to our base desire for mana were slowly weeded out of civil society, if they survived at all. Theldrin is one such example, only it is a testament to his cunning and will to live that he has made it as long as he has.\n\nHe accepts no aid, choosing instead to stalk careless students and idle Magisters. His sole obsession is the mana that others possess...\n\nSee to it that he never harms another elf again.", objectives = "" }
WordHunterWoW_QuestEN[91251] = { title = "Prey: Neydra the Starving (Hard)", description = "Poor Neydra... I knew her, in a previous life. She was full of vitality. Full of ambition. Unfortunately, she let that ambition get the best of her. She grew too enamored with the raw power of the arcane. She became resentful of all other things. Of all other people...\n\nAnd now she is a murderous creature who beheads rats and attacks innocents in a desperate attempt to garner enough arcane energy to slake her unquenchable thirst.\n\nIt's funny, the paths life takes us...", objectives = "" }
