WordHunterWoW_QuestEN[91260] = { title = "Prey: Executor Kaenius (Nightmare)", description = "The domanaar have a reputation for guile and cunning, but there are brutes among them: those who seek to dominate their victims through sheer power and force of will.\n\nExecutor Kaenius is one such domanaar.\n\nThey stalk the battlefield, singling out our strongest soldiers and viciously cutting them down.\n\nPut an end to their rampage.", objectives = "" }
WordHunterWoW_QuestEN[91261] = { title = "Prey: Imperator Enigmalia (Nightmare)", description = "Imperator Enigmalia is personally responsible for the deaths of at least a dozen Farstriders. I say \"at least\" because this particular domanaar makes it somewhat difficult to identify the bodies, so utterly destroyed are they.\n\nGo and avenge our fallen soldiers.", objectives = "" }
WordHunterWoW_QuestEN[91262] = { title = "Prey: Knight-Errant Bloodshatter (Nightmare)", description = "Death knights are unstable killing machines at the best of times. Knight-Errant Bloodshatter has forsaken any oath or promise that would ostensibly bind one of his kind to the bottom rungs of civilized society, and has gone completely rogue.\n \nHe is starting to become a liability. \n\nRecoup his anguish so that we can make the best of such an unfortunate situation.", objectives = "" }
WordHunterWoW_QuestEN[91263] = { title = "Prey: Vylenna the Defector (Nightmare)", description = "Vylenna the Defector lives up to her name. After a recent engagement on the field of battle, she became so preoccupied with profaning the dead that she completely abandoned the duties ascribed to her.\n\nThen her dereliction turned violent.\n\nA veritable font of anguish if you ask me...", objectives = "" }
WordHunterWoW_QuestEN[91264] = { title = "Prey: Lost Theldrin (Nightmare)", description = "Those of us who succumbed to our base desire for mana were slowly weeded out of civil society, if they survived at all. Theldrin is one such example, only it is a testament to his cunning and will to live that he has made it as long as he has.\n\nHe accepts no aid, choosing instead to stalk careless students and idle Magisters. His sole obsession is the mana that others possess...\n\nSee to it that he never harms another elf again.", objectives = "" }
WordHunterWoW_QuestEN[91265] = { title = "Prey: Neydra the Starving (Nightmare)", description = "Poor Neydra... I knew her, in a previous life. She was full of vitality. Full of ambition. Unfortunately, she let that ambition get the best of her. She grew too enamored with the raw power of the arcane. She became resentful of all other things. Of all other people...\n\nAnd now she is a murderous creature who beheads rats and attacks innocents in a desperate attempt to garner enough arcane energy to slake her unquenchable thirst.\n\nIt's funny, the paths life takes us...", objectives = "" }
WordHunterWoW_QuestEN[91266] = { title = "Prey: Thornspeaker Edgath (Nightmare)", description = "This one presents a prickly problem indeed. Thornspeaker Edgath has made a name for himself by using his druidic powers not to preserve Azeroth, but to twist its strength both against his enemies and innocent bystanders alike. He has no regard for anything that is not a beast or growing in the ground.\n\nIt is time we clip this thorn.", objectives = "" }
WordHunterWoW_QuestEN[91267] = { title = "Prey: Thorn-Witch Liset (Nightmare)", description = "Thorn-Witch Liset is a curse upon civilization and a blight upon the land itself. She twists the very trees and beasts, communing with the dark, evil things that live on the very edges of the natural realm.\n\nI despise the natural realm.", objectives = "" }
WordHunterWoW_QuestEN[91268] = { title = "Prey: Grothoz, the Burning Shadow (Nightmare)", description = "The Twilight's Blade are an embarrassing band of mediocre cultists and uninspired conspirators. Grothoz is the brains of a particularly stupid cabal that has been active in a nearby region. \n\nAs his stupidity prevents him from using his whole brain, let us unlock his potential for him...", objectives = "" }
WordHunterWoW_QuestEN[91269] = { title = "Prey: Dengzag, the Darkened Blaze (Nightmare)", description = "Do you know why the Twilight's Blade call Dengzag the \"Darkened Blaze?\" It is because they are stupid, small-minded, and utterly bereft of imagination. What a silly name indeed. \n\nI, however, am not small-minded. I have quite the prodigious mind, and it is currently intent on putting an end to Dengzag and whatever his tiny brain is up to. \n\nGet to it.", objectives = "" }
WordHunterWoW_QuestEN[91270] = { title = "The Most Important Thing", description = "We will be strong for the Pit!\n\nBut Boletus right. Another thing needed. Must have great name.\n\nBest teams all have good name. Fungus Force. Spore Storm. Cap Clash. And champions, Glow Guard!\n\nAll good names.\n\nWe need amazing name. Best name. So will be best team.\n\nYou help choose?", objectives = "" }
WordHunterWoW_QuestEN[91271] = { title = "A Fish!", description = "There is a deliciously delectable dish that I am dying to share with my guests. We start with just the right fish, then chop it up, drop it in a blend of citrus and our special savory seasonings, and let it bask in the glorious flavors.\n\nIn the shake of a tail feather, it becomes a magical delight for the senses!\n\nWe are the talk of the town, you know. Could you please procure for us the perfect fish?", objectives = "" }
WordHunterWoW_QuestEN[91274] = { title = "Severing the Void", description = "The High Exarch has formed an impressive defensive line. It will hold the Devouring Host's current numbers. But I can see void pylons behind the lines. Those will call forth more Devouring Host and overwhelm the Vanguard of Light.\n\nTheir power is too dangerous for us to destroy directly, but if we can re-activate the sentinels that fell in the initial assault, they could destroy the pylons for us.", objectives = "" }
WordHunterWoW_QuestEN[91281] = { title = "Midnight", description = "Locate one of the images of Lady Liadrin that have appeared across Azeroth.", objectives = "" }
WordHunterWoW_QuestEN[91284] = { title = "A Path Not Yet Chosen", description = "I'm trying to figure out what career path to follow, but I keep second-guessing myself. The Farstriders, the Blood Knights, the Magisters... they all seem so incredible that I can't decide.\n\nI was hoping if I spoke to each and earned a recommendation, I might finally understand where I'm meant to be. Would you help me?", objectives = "" }
WordHunterWoW_QuestEN[91288] = { title = "A Test of the Hunt", description = "So, you want a Farstrider recommendation? We don't hand those out like festival ribbons.\n\nIf you want to earn it, then you'll need to do what every other recruit does. Bring me lynx pelts, clean and proper.\n\nNo shortcuts, no excuses. Let's see if you've got the spine for it.", objectives = "" }
WordHunterWoW_QuestEN[91291] = { title = "A Test of Blood", description = "Ah, you seek a Blood Knight's recommendation, do you? In that case, you'll need to prove your worth... against me. \n\nOnly those with true strength and honor may join our ranks! Prepare yourself. This won't be a simple challenge, but if you can best me, I'll gladly offer my recommendation!", objectives = "" }
WordHunterWoW_QuestEN[91292] = { title = "A Test of the Arcane", description = "Ah, you seek a recommendation from a Magister, do you? Very well... but first, you must prove your understanding of the arcane.\n\nGo to the nearby crystals we have for training, extract their energy, and channel it into this staff. Show me that you can harness the arcane, and I will see you worthy of my recommendation.\n\nShould you fail, don't bother returning. My time is too valuable for such trivial matters.", objectives = "" }
WordHunterWoW_QuestEN[91301] = { title = "How to Train Your Protege", description = "I did everything they asked--the trials, the lessons--and they all said I did well... but I still don't know where I truly belong.\n\nEach path felt right in its own way, and now my heart feels pulled in three directions.\n\nPlease... could you help me decide?", objectives = "" }
WordHunterWoW_QuestEN[91314] = { title = "Untethered Potential", description = "{class}--I heard you have explored Untethered Space? That place is soaked with pristine void energy. I would like to explore it myself, but the last who have ventured into were consumed by the Void.\n\nI need help with my research. There are Phase-Lost creatures in the Voidscar Cavern that I could use to examine their essence. If you could collect that for me, I would be grateful. \n\nGo carefully.", objectives = "" }
WordHunterWoW_QuestEN[91328] = { title = "Secret Ingredients", description = "Our gregarious guests have partaken so much from our stores that we are running dangerously low of our special Solaarian sintalia.\n\nThe rich taste of belanise, with its intoxicating scent, contrasts perfectly with the sharp tartness of the local berries. Carefully prepared then soaked in our special blend of spirits, then served--it's to die for!\n\nJust between us, if the berries are not handled just right, the infusion can be quite deadly. Otherwise... delicious, invigorating, purifying, glorious!", objectives = "" }
WordHunterWoW_QuestEN[91339] = { title = "Smothered in the Crib", description = "I summoned my first imp in a dirty, haze-filled lounge beneath Murder Row after a dozen failed attempts. Each time, I reached further for what made so-called greater powers submit to mortals. I finally managed it after wetting my hands with the hot blood of a young rabbit. Bloodthistle never satisfied me again.\n\nI have matured my technique since then. Seek the whelps of these beasts. Siphon their energy into my reliquary of darkness. From their sacrifice, we will draw the power to defeat Kalgorg.", objectives = "" }
WordHunterWoW_QuestEN[91340] = { title = "For Violence's Sake", description = "Like many warlocks, I bind my demons with terms of a contract. I should have realized the Void and violence of this world could affect the rules I took for granted. Kalgorg used that power to break its bindings and end our arrangement. \n\nWhen we confront Kalgorg, the scent of blood and violence must be upon us. Slay the beasts you find to demonstrate to Kalgorg we are willing to do the same to it. Control over the Void is found and lost within the blink of an eye.", objectives = "" }
WordHunterWoW_QuestEN[91341] = { title = "Unlimited", description = "Now, we descend. The Void energy below is unlike any I've felt before, as if gravity itself yields to the Void. Once you enter the cave, its influence will be upon you.\n\nKalgorg has already slain and claimed power from the creatures within. Their violent deaths have left behind some kind of cursed terrain, but we must proceed and claim the power within. Fill the reliquary to the brim. \n\nI know not what to expect from my voidwalker. We will need all the power we can manage.", objectives = "" }
WordHunterWoW_QuestEN[91342] = { title = "If You Want It Done Right", description = "With all the problems facing Eversong, the Farstriders have their hands full!\n\nI'm a capable arcanist. I've always admired the Farstriders--why not lend my talents to their cause? They do so much work by hand, when a bit of magic would allow them so much more time for adventuring!\n\nAlas, my enchanted broom idea has not quite gone as I'd hoped. They're so ornery, they end up attacking the recruits instead of cleaning!\n\nPerhaps this is a problem for elbow grease after all.", objectives = "" }
WordHunterWoW_QuestEN[91343] = { title = "Ambition's Reward", description = "You have filled the reliquary with power I can draw on. Now, we reap the reward of our preparations.\n\nKalgorg waits just ahead, draining the beast that once made this cave its lair. Weaken Kalgorg, and I will bind it as I first did years ago.", objectives = "" }
WordHunterWoW_QuestEN[91345] = { title = "To the North Tower", description = "Ranger Valsarin is a chef at Farstrider Hold. He's decent in a kitchen, but his passion is field cooking.\n\nThere was a time when you could wander any path in Eversong and find the ingredients for a good meal. A Farstrider's dream! With enough hard work, we can help the forest recover, and it starts with rehabilitating the soil.\n\nMeet Valsarin at the North Tower and he can tell you more.", objectives = "" }
WordHunterWoW_QuestEN[91346] = { title = "Supplicants to the Goddess", description = "We have long tended to the roots with the help of the creatures who live and grow here. Think of it as a symbiotic relationship from which we, the creatures, and the roots all benefit. That said, my partner Riverscale isn't contributing very much lately!\n\nPlease help me find a way to motivate him again.\n\nFirst, you must cleanse off the essence of the outside. Cleanse yourself in the waters of Har'kuai.", objectives = "" }
WordHunterWoW_QuestEN[91347] = { title = "Strider Stampede", description = "It's hard to believe this used to be the Dead Scar.\n\nUp here, close to the city, the land has almost completely recovered. Which is good, because we've got a lot of mouths to feed.\n\nHawkstriders are the perfect helpers for preparing the soil. Their tough claws can easily spread seeds and squash bugs!\n\nMeet me down in the Tranquil Repose and I'll saddle one up for you.", objectives = "" }
WordHunterWoW_QuestEN[91348] = { title = "See a Mana 'bout a Wyrm", description = "Mana wyrms may not be as glamorous as lynxes or hawkstriders, but they're crucial to keeping magic flowing through the forest.\n\nThey congregate on the ley lines to molt, but sometimes they get a little agitated. And we have to help them out! Aggressively!\n\nI've set up some ley channels to get things started. Find wyrms that look like they could use a little help, and beat them up until they shed their arcane carapace. Don't worry--all that mana returns to the forest eventually!", objectives = "" }
WordHunterWoW_QuestEN[91349] = { title = "The Dark Part of the Woods", description = "Much of the forest has recovered, but to the south... Everything that Eversong has faced--the Scourge, the fel, and now the Twilight's Blade--all that magic leaches into the soil. It builds up in the creatures until they're completely overwhelmed...\n\nMy instruments can detect corruption in these animals. We can cull the ones that are too far gone and save the ones that aren't. It isn't fun... but it's for the good of Eversong!", objectives = "" }
WordHunterWoW_QuestEN[91350] = { title = "A Real Assignment", description = "Captain Dawnrunner was supposed to check on the Enclave and then meet us here. She's as capable a ranger as any! It's a bad sign if she's been detained.\n\nFarstrider Enclave is usually where they do wilderness training. With all the trouble however, everyone's been dispatched elsewhere. She could be up there alone, in serious danger!\n\nThere's no time to lose. I'm going to save my Captain and prove myself as a Farstrider!", objectives = "" }
WordHunterWoW_QuestEN[91359] = { title = "Fungal Lashers B Gone", description = "We are blessed to live in Harandar, but this is also our responsibility. The roots of the World Trees wind through these lands. We tend them, and they thrive. That is why it is so important for Riverscale to be back on duty.\n\nWe need to keep these grounds clear of these fungal lashers before they leach off the roots. As a plus, Riverscale really loves lasher fronds. Can you find and bring some back for him?", objectives = "" }
WordHunterWoW_QuestEN[91360] = { title = "Weeding Out the Unwanted", description = "The roots of the World Trees are infused with both nutrients and the magic of Harandar. As the large vessels that they are, they will draw to them unwanted fauna and flora. Some of them are harmless, but we want to keep the roots clear.\n\nHaranir can often be allergic to the green weeds that flourish beside the roots of the World Trees. If you rip them out by the root, you would be saving us a lot of time--and hives!", objectives = "" }
WordHunterWoW_QuestEN[91361] = { title = "Back on Duty?", description = "Finally! I knew the little guy could do it.\n\nNo, that is a bald-faced lie. If this grovecrawler could somehow find a way back into his cocoon, he would already be there.\n\n<Cyenna sighs.>\n\nHis second favorite treat is the potatoad. If that doesn't work, his third favorite treat is the petalwing. That should get him back onto his mite-hunting duties.\n\n...I have the backbone of a wet frond.", objectives = "" }
WordHunterWoW_QuestEN[91363] = { title = "Harvest of Darkness", description = "You... make yourself useful.\n\nAs a master of terrible beasts, it is my job to mold these hatchlings into dreaded beasts. I pit them against each other and they grow ever more violent.\n\nBut the elves here insist that I will yield better results with just a bit of... tender loving care. Let us put this to the test.\n\nThis runt is Fidoficus. You will show him tenderness and affection, and then we will see how ferocious he becomes.\n\nCollect some delicious dietary treats for him and return to me.", objectives = "" }
WordHunterWoW_QuestEN[91364] = { title = "[DNT] QUEST NOT USED", description = "In order for Fidoficus to become a truly menacing force of destructive power, he needs a strict diet of macro-nutrients. \n\nWe Domanaar have no need for such corporeal sustenance. And therefore, I am not familiar with the process of cooking. \n\nTake the ingredients you've gathered and create something nourishing. \n\nAnd tasty. Not that I'd care. <want to hit beats where the Dom lets slip that it cares for the creature, at least a little>", objectives = "" }
WordHunterWoW_QuestEN[91375] = { title = "The Silence at Fungara Village", description = "Fungara Village has been silent for some time now.\n\nWe've largely been occupied with the Lightbloom and the threat it presents, so we haven't had time to check in on the fungarians to the east. Usually, they are rowdy yet manageable... but it's rare that they go completely silent.\n\nI am going to investigate. If you wish to prove yourself an ally, you would do well to join me.", objectives = "" }
WordHunterWoW_QuestEN[91376] = { title = "Little Monsters", description = "When I sent a request for aid from Har'alnor, I did not expect them to send me an outsider. No matter.\n\nThe denizens of Fungara Village have gone quiet. Normally, I would be thrilled: they're horribly screechy. But the way they are shambling about... it is like they have forgotten that they yet live.\n\n<Ghikal shudders.>\n\nI tried to get close, but they attacked me on sight.\n\nI will need samples of their flesh. Go and bring them to me, so I can see what has happened here.", objectives = "" }
WordHunterWoW_QuestEN[91377] = { title = "Spawn of the Dead", description = "It is obvious that something terrible has happened in the village. I can see the corpses of their largest specimens strewn across the southern reaches from here, but something is off about them too. Fungarians don't usually just leave the corpses of their kin lying about.\n\nAnd though I am watching from afar, I swear that some of them are... twitching.\n\nInvestigate. Find out what you can, and report back to me.", objectives = "" }
WordHunterWoW_QuestEN[91378] = { title = "You Are Legend", description = "Whatever these things are, they're not fungarians. Not anymore. \n\nHar'alnor has enough to worry about with the Lightbloom as it is. It cannot afford to be trapped between its forces and these... things.\n\nDo what must be done. Destroy as many of them as you can.", objectives = "" }
WordHunterWoW_QuestEN[91379] = { title = "Decayed Land", description = "As far as I can tell, these fungarians are all already dead. Something is animating their corpses from within, like puppets attached to unseen vines.\n\nThis fungal matter that's infesting them must be coming from somewhere... and judging from the size of the ones further north, we'll find plenty of it there. Find it, get rid of it, but for Aln'hara's sake don't breathe it in.", objectives = "" }
WordHunterWoW_QuestEN[91380] = { title = "Belly of the Beast", description = "I normally raise my beasts on a diet of raw, bloody carcasses and souls ripped asunder by the Void.\n\nBut we shall try your mortal ways.\n\nI hear you... cook? And that makes the treat better?\n\nDo this. Then, take him on a walk around the Howling Ridge. Even I know exercise is good for digestion.\n\nOnly the most ferocious of creatures is worthy of serving me. I hope neither you nor Fido disappoint me.", objectives = "" }
WordHunterWoW_QuestEN[91381] = { title = "Reticent Evil", description = "I do not understand. We've searched high and low, north and south. Everywhere we go, we find animated corpses and small fruiting fungus, but where is the central body? Where is--\n\nOh, goddess. Of course.\n\nThe water, {class}. Check the water.", objectives = "" }
WordHunterWoW_QuestEN[91382] = { title = "Mighty and Superior", description = "The beast is fed and exercised. Imagine, mortal... one day his maw will grow to fit you inside it a thousand times over. \n\nNow, we will test his potential for true violence. \n\nThere is a beast that has laid claim to a den south of the Howling Ridge. \n\nFidoficus trusts you now. Go with him and bear witness to his might.", objectives = "" }
WordHunterWoW_QuestEN[91383] = { title = "Tidy Up", description = "Captain Dawnrunner is fine, thank the sun. The only danger was... we didn't keep up on our chores.\n\nIt's not heroic, it's not romantic, but we can't go on with Farstrider Enclave in this state. The rangers here are overwhelmed. We can all pitch in to help them get it cleaned up again.\n\nI can't believe it all comes back to sweeping. That's what being a Farstrider is really about.", objectives = "" }
WordHunterWoW_QuestEN[91384] = { title = "Recovery Mission", description = "We've been deploying Farstriders across the forest to fight the Amani, the Lightbloom, the Void... but for all our heroics, there's no one left to tend to the wildlife! Or maintain the building! Or keep track of supplies!\n\nAnd now our beloved Enclave looks like a hawkstrider pen. I've had enough!\n\nI may not be able to help, but I trust you all can gather anything that was taken and get this place looking respectable again.", objectives = "" }
WordHunterWoW_QuestEN[91385] = { title = "A Ranger's Spirit", description = "Taemin has proved himself as capable as any Farstrider today. But I'm afraid he might not see it that way.\n\nHe came to us with such lofty ideas about the rangers--all those swashbuckling adventure stories, all the romantic old legends. But at the end of the day, being a ranger is mostly... chores. Difficult, boring, important chores.\n\nWhy don't you go talk to him, and make sure he's not too disappointed?", objectives = "" }
WordHunterWoW_QuestEN[91386] = { title = "Mad to Measure", description = "These... tourists! These uncultured, ungrateful slobs!\n\nThis Vanguard of Light has brought a lot of business to Silvermoon, to be certain. But none of them actually appreciate what Thalassian craftsmanship means. They have no respect for the elven arts--they just want shiny, glittery souvenirs!\n\nI am no spring runner dancing for their amusement... but I can hardly turn them away, can I? Perhaps an assistant would make this atrocious task easier.", objectives = "" }
WordHunterWoW_QuestEN[91388] = { title = "Uncommon Threads", description = "Our patron--Gaari, I suppose--should count himself lucky. These mana wyrms produce the finest silk in Eversong. I know Magisters who would kill to have a robe trimmed in this, and yet here we are, using it for a mending job. Ah well.\n\nOnce the wyrms have eaten their fill of arcane energy, you can siphon the silk from them onto these bobbins.\n\nIf they are reluctant to release their silk, you may have to, ah... beat it out of them. But I've been assured it's entirely ethical.", objectives = "" }
WordHunterWoW_QuestEN[91389] = { title = "Clothes Make the Man", description = "It is not merely the material that makes an arcanoweave cloak so fine, but the weaving process itself.\n\nTo mend one, particularly one that has built up so much history and latent arcane energy... I am about to embark on a very dangerous bit of tailoring indeed. Finally, a real testament to my skills.\n\nI am excited. I hope nothing explodes. Meet me inside when you're prepared.", objectives = "" }
WordHunterWoW_QuestEN[91391] = { title = "Still Scouting", description = "When the Alliance originally fought the Horde here, Kurdran served as a scout. He's still an excellent one. He took his gryphon to Blackrock Mountain to see what kind of forces we may be dealing with there.\n\nMeet up with him and see what kind of trouble you can cause.", objectives = "" }
WordHunterWoW_QuestEN[91398] = { title = "Tomes of Terror", description = "Knowledge is power, and de ogres been reading.\n\nBring me dey tomes so dey never grow dis powah again.", objectives = "" }
WordHunterWoW_QuestEN[91399] = { title = "Ashes of the Void", description = "De void elementals have one use.\n\nDe dust dey drop is useful for shadow magic rituals.\n\nCollect some for our tribe.", objectives = "" }
WordHunterWoW_QuestEN[91400] = { title = "Blades of the Fallen", description = "After de battle we left a lot of our weapons behind.\n\nPlease go collect dem so de Twilight's Blade doesn't get dem.", objectives = "" }
WordHunterWoW_QuestEN[91401] = { title = "Dead by Dusk", description = "De Twilight's Blade cultists have de audacity to try and take back our temple. Kill de peons and bring me their femurs.", objectives = "" }
WordHunterWoW_QuestEN[91402] = { title = "Ultra Deadly Ultradon", description = "I saw some of de void elementals doing a sketchy ritual in de center of the battlefield. It looked like dey were summoning some void creatures.\n\nMake sure whatever dey summon is dealt with.", objectives = "" }
WordHunterWoW_QuestEN[91403] = { title = "Probable Paralytic", description = "Halazzi says dat de Vilebranch have made a new venom dat para... parliz--makes its victims not move--so they can drag them off to be sacrificed. He says it's frog venom.\n\nI said that doesn't make sense. Frogs are poison, right? Halazzi said frogs are normally poisonous, not venomous. But these have sharp horn bits on them, so maybe they have venom! I didn't know frogs could have venom, did you?\n\nLet's find out if these do--then de Witherbark can make an anti-venom!", objectives = "" }
WordHunterWoW_QuestEN[91404] = { title = "A Most Vile Venom", description = "De Vilebranch are cookin' up more bad things. You should go to de source and make dem stop!\n\nHalazzi has smelled their venom-mixin' place someplace to de southeast, and he thinks it's more den just frog venom.\n\n...Oh, Halazzi also said to bring back some kind of huge fang. Frogs don't have fangs, though. Well, find it anyway!", objectives = "" }
WordHunterWoW_QuestEN[91405] = { title = "Validating the Venom", description = "This means there are both frog and spider venoms in de mixtures. Halazzi says he senses somebody beseeched Shadra with dat fang. Dey must be a really big spider if their fang is dat big!\n\nHalazzi doesn't like that de Vilebranch had it. I can tell. He's unhappy. His ears get all flat like de wings of a kite.\n\nSo we gotta help out. Take de samples and de fang to de Witherbark Chief. We Witherbark have alchemists dat can brew anti-venoms for both spiders and frogs.", objectives = "" }
WordHunterWoW_QuestEN[91406] = { title = "Far from the Hinterlands", description = "As a Torntusk of de Revantusk tribe, I am cautious of Witherbark because of our history with dem in de Hinterlands. My family moved here because of dem.\n\nThe Witherbark here in Zul'Aman seem to respect us, but de Witherbark I remember in de Hinterlands killed and backstabbed their allies for power.\n\nThey worshipped de spider loa, Shadra.\n\nWhen de Hinterlands's Witherbark temple Shadra'Alor fell, de Witherbark must have fled somewhere. Look around for evidence of Hinterlands Witherbark and of Shadra.", objectives = "" }
WordHunterWoW_QuestEN[91407] = { title = "The Eye of the Loa", description = "I lost friends to venoms made from Shadra's spiders in de Hinterlands. I gotta know if Shadra's lurkin' around here, twistin' de minds of these Witherbark. No Revantusk will be safe in Zul'Aman with Shadra-worshippin' Witherbark around!\n\nMaybe I seem paranoid, but I have my reasons. And you have Halazzi's ear. You could ask him to reveal to you any hidden spiders, yes? I know those long ears can hear dem skitterin'!\n\nThere is a shrine behind me. Stand in front of it and see if he'll grant you a boon.", objectives = "" }
WordHunterWoW_QuestEN[91408] = { title = "Seeking Shadra", description = "We will untangle dis mess about Witherbark and Vilebranch soon enough. De loa Shadra and her schemes must be our first priority.\n\nI watched the spiders run in terror from you, and somethin' struck me. De spiders are not just running in panic--they're going somewhere... somewhere dey feel safe, and even I can see dem now. \n\nDey are not hiding anymore. Dey are on de run! Our hunt continues.\n\nLet's follow dem.", objectives = "" }
WordHunterWoW_QuestEN[91409] = { title = "Dreaming of Spiders", description = "There are three relics of Shadra. I only had two. I had de fang in de village and de eye hidden here. Dey musta stolen de fang somehow, then came for de eye!\n\nWe never had de Shell of Shadra--it was lost when we left Shadra'Alor. It's possible de Vilebranch have de shell.\n\nDe fang and de eye should let us talk to Shadra briefly, even if we lack de last ritual relic to summon her.\n\nCome with me. I will show you how.", objectives = "" }
WordHunterWoW_QuestEN[91410] = { title = "Shared Loa", description = "De Witherbark Chief knows many of us came from de Hinterlands with our worship of Shadra'Alor, but believed Shadra was long dead.\n\nWe should let him know how Halazzi helped us to find and restore Shadra, and of Shadra's presence in de Witherbark crypt. He also must learn of de rapport with de Revantusk.\n\nI will stay with Shadra for now. Will you carry de message?", objectives = "" }
WordHunterWoW_QuestEN[91411] = { title = "Maisara Caverns: Deep in Maisara", description = "Shadra has asked dat we recover de third piece of Mixer Jamanga's ritual, de Shell of Shadra. With it, maybe we can bring her back.\n\nShe recognized both de Witherbark and Revantusk as her allies. I felt her approval upon all of us. I believe this is de right choice.\n\nHalazzi set us on dis path, and we each got our roles to see it through. Gather your allies and go into Maisara Caverns! I would expect one of their leaders to hold de shell. Kill dem and take it back.", objectives = "" }
WordHunterWoW_QuestEN[91412] = { title = "Return of the Venom Queen", description = "It is time to bring Shadra to her proper place as a loa of de Witherbark and Revantusk. She will be small at first, but one day could be great like Halazzi and Nalorakk!\n\nEven a small loa will be a good ally against de Vilebranch venoms. She is de Loa of Spies, and will block their thievery of our people and relics, just as Halazzi hides them in the mists.\n\nHold de Shell of Shadra in de center of de room, and we will call de loa to us!", objectives = "" }
WordHunterWoW_QuestEN[91413] = { title = "A Twilight Oath's End", description = "<The ancient runes on the page seem to twist under your gaze. Their power seems to be rapidly fading.>\n\n<Ve'nari would be interested in this.>", objectives = "" }
WordHunterWoW_QuestEN[91417] = { title = "Seek out Arator", description = "I see that my son is spending his time with the wounded. Do a father a simple favor and see if he could use your assistance.", objectives = "" }
WordHunterWoW_QuestEN[91420] = { title = "Swap Meet", description = "<The mysterious mineral thrums in your hand. Someone in Tazavesh will find a use for this. Look around the Veiled Market for an interested party.>", objectives = "" }
WordHunterWoW_QuestEN[91426] = { title = "The People's Champion", description = "I think we've done all we can for the moment, {name}. Let's return to the muster point.", objectives = "" }
WordHunterWoW_QuestEN[91438] = { title = "Infinite Research: Heroic Worldly Deeds", description = "All across the Broken Isles there are people in need. They search for hope but are hard pressed to find any. You can be that hope.\n\nSeek out those in peril in the Broken Isles and be the champion they so desperately need.\n\nIt is through such acts that legends are made.", objectives = "" }
WordHunterWoW_QuestEN[91439] = { title = "Infinite Research: Heroic Invasion Points", description = "The Legion does not fight conventionally. They deceive, manipulate, and undermine their opposition at every turn.\n\nThere are no battle lines against the Legion. They will open rifts at a weak point and then spill out of it sowing death and destruction. When they invade, it is on their terms.\n\nHowever, this strategy is not invincible. Potent champions, able to move and react swiftly, can stop these invasions at their source. Stop the Legion Invasion. Show people that the Legion can be defeated.", objectives = "" }
WordHunterWoW_QuestEN[91440] = { title = "Infinite Research: Hero of the Broken Isles", description = "Heroic deeds are a matter of perspective. What may seem trivial to a mighty hero such as you, could mean the world to another.\n\nSeek out those in need and aid them in whatever task they deem important. In doing so your legend will grow.", objectives = "" }
WordHunterWoW_QuestEN[91441] = { title = "Infinite Research: Heroic Greater Invasion Points", description = "Once the Legion has sown confusion and chaos, then they will begin their real assault. Huge invasion rifts will open and the Legion will march forth in great numbers. The defenders, scattered to protect against smaller rifts, will lack sufficient strength anywhere to stop them.\n\nThat is when champions like you are most needed.\n\nSeek out one of the Legion's major invasions and throw everything you have at it. \n\nShow the people that with enough determination you can cancel the apocalypse.", objectives = "" }
WordHunterWoW_QuestEN[91442] = { title = "Eco-Dome Al'dani", description = "We have received word from Ve'nari that the Wastelanders continue to stand in the way of progress on K'aresh. They threaten the most promising eco-dome.\n\nThe restoration directive of K'aresh must not be interrupted.\n\nPut an end to these inefficiencies.", objectives = "" }
WordHunterWoW_QuestEN[91443] = { title = "Infinite Research: Advanced Combat Studies, Rare", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a rare study, so focus on fighting rare opponents so that we can get a better understanding of your abilities.\n\nAnd remember, this is for the greater good.", objectives = "" }
WordHunterWoW_QuestEN[91444] = { title = "Infinite Research: Advanced Combat Studies, Elite", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be an elite study, so focus on fighting elite opponents so that we can get a better understanding of your abilities.\n\nAnd remember, this is for the greater good.", objectives = "" }
WordHunterWoW_QuestEN[91446] = { title = "Infinite Research: Advanced Combat Studies, Rare Elites", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a rare elite study, so focus on fighting rare elite opponents so that we can get a better understanding of your abilities.\n\nAnd remember, this is for the greater good.", objectives = "" }
WordHunterWoW_QuestEN[91447] = { title = "Infinite Research: Advanced Combat Studies, Demonology", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a demonology study, so focus on fighting demonic opponents so that we can get a better understanding of your abilities.\n\nAnd remember, this is for the greater good.", objectives = "" }
WordHunterWoW_QuestEN[91448] = { title = "Infinite Research: Heroic Terrors of the Broken Isles", description = "It is time to put both you and your artifact to the test.\n\nSeek out a Terror of the Broken Isles and defeat them.\n\nI am certain that, no matter the outcome, you will provide us with much to think about. I will be watching with great interest.", objectives = "" }
WordHunterWoW_QuestEN[91449] = { title = "Infinite Research: Advanced Combat Studies, Empowerment", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a study of the empowered enemies in the experimental, fractured timeline. We need to understand how your abilities fare in the face of terrifying change. \n\nAnd remember, this is for the greater good.", objectives = "" }
WordHunterWoW_QuestEN[91450] = { title = "We Ready Now", description = "Thank you, {name}! We ready for Pit.\n\nWe trained to be strong. You hurt us. Now we more strong.\n\nYou tell Boletus we ready now.", objectives = "" }
WordHunterWoW_QuestEN[91451] = { title = "Stalk Market", description = "<The mysterious plant thrums in your hand. Someone in Tazavesh will know what to do with it. Look around the Veiled Market for an interested party.>", objectives = "" }
WordHunterWoW_QuestEN[91452] = { title = "Range of Knowledge", description = "I've always dreamed of being a Farstrider--the adventure! The romance! The beauty of nature! When they put out a call for help, I knew I had to join.\n\nCaptain Dawnrunner assigned me to the library initially, but with everything going on, we all have to be flexible.\n\nI don't mind, but I had hoped to collect all the overdue books before being sent on a real assignment. If you find any, would you bring them to the library for me?\n\nAnd feel free to give them a read! There are some interesting volumes!", objectives = "" }
WordHunterWoW_QuestEN[91454] = { title = "Phase-Lost Adventurer", description = "Covered in slime and saliva, the journal bears a partial entry of a previous Phase Diver.\n\n<Day 27\n\nUntethered Space is much more vast than I expected, with monsters stronger than I have seen on K'aresh. \n\nThere is a nearby cave I will explore tomorrow. It is brimming with Phase-Altered Essence. This could bode useful for better understanding the ecology out here.>\n\nResearcher Essarae would be very interested in this.", objectives = "" }
WordHunterWoW_QuestEN[91459] = { title = "Manaforge Omega: A Walking Shadow", description = "Hero, can you hear me? There's a translocator the Shadowguard uses to send cargo to their reserves that can carry you directly to their post beneath the Manaforge. An ambush they'll never see coming!\n\nThere is of course, a catch. We do not have clearance to use their supply lines... so we need you to procure some for us. Take down the highest-ranking member of the Shadowguard you can find, return with identification, and we'll forge you a one-way ticket to the front lines.", objectives = "" }
WordHunterWoW_QuestEN[91460] = { title = "Manaforge Omega: A Walking Shadow", description = "Hero, can you hear me? There's a translocator the Shadowguard uses to send cargo to their reserves that can carry you directly to their post beneath the Manaforge. An ambush they'll never see coming!\n\nThere is of course, a catch. We do not have clearance to use their supply lines... so we need you to procure some for us. Take down the highest-ranking member of the Shadowguard you can find, return with identification, and we'll forge you a one-way ticket to the front lines.", objectives = "" }
WordHunterWoW_QuestEN[91461] = { title = "Manaforge Omega: A Walking Shadow", description = "Hero, can you hear me? There's a translocator the Shadowguard uses to send cargo to their reserves that can carry you directly to their post beneath the Manaforge. An ambush they'll never see coming!\n\nThere is of course, a catch. We do not have clearance to use their supply lines... so we need you to procure some for us. Take down the highest-ranking member of the Shadowguard you can find, return with identification, and we'll forge you a one-way ticket to the front lines.", objectives = "" }
WordHunterWoW_QuestEN[91462] = { title = "To the Central Tower", description = "Ranger Asterae is one of our veterinarians. She usually cares for our lynxes, but the mana wyrm molt is too crucial to the health of the forest to go unmonitored.\n\nThe wyrms regulate the flow of magic from the ley lines to the rest of the woods. When the ley lines were disrupted, so was their molting season. It's not so dire as it once was, but they still need help from time to time.\n\nMeet Asterae at the Central Tower. She can tell you more.", objectives = "" }
WordHunterWoW_QuestEN[91463] = { title = "To the South Tower", description = "Despite being new to the Farstriders, Taemin has the hardest assignment. Eversong Woods has mostly recovered, but the further south you go, the more dangerous things get.\n\nHe's a capable mage, though. And we need his nose for magic.\n\nWe'll meet you down there once things are wrapped up here. Captain Dawnrunner was going to provide backup. She should be there by now.", objectives = "" }
WordHunterWoW_QuestEN[91464] = { title = "Stormarion Assault", description = "", objectives = "" }
WordHunterWoW_QuestEN[91466] = { title = "Aiding the Green Dragons", description = "Nozdormu and Queen Alexstrasza believe the best path forward is to aid the Green Dragons.\n\nLike the Black Dragons, the Greens lack a true aspect to lead them. \n\nMerithra is currently hosting guests within the Emerald Gardens. Meet with her to see if you can aid her.\n\nI will continue tracking the incarnates and the other dracthyr.", objectives = "" }
WordHunterWoW_QuestEN[91467] = { title = "Incarnates on the Move", description = "{name}, I thought I'd find you here. I bring word from the other aspects and my scouts.\n\nThe incarnates are on the move. I know not what they're planning, but you should be aware of their actions.", objectives = "" }
WordHunterWoW_QuestEN[91476] = { title = "Behind Enemy Lines", description = "My friend, we've finished working on some new tools to ensure you'll do some real damage to the Shadowguard. Come by and let's sort it out together.", objectives = "" }
WordHunterWoW_QuestEN[91477] = { title = "Behind Enemy Lines II", description = "Our knowledge of technomancy deepens. Let's improve your weaponry inside the Manaforge.", objectives = "" }
WordHunterWoW_QuestEN[91478] = { title = "Behind Enemy Lines III", description = "Our knowledge of technomancy deepens. Let's improve your weaponry inside the Manaforge.", objectives = "" }
WordHunterWoW_QuestEN[91479] = { title = "Behind Enemy Lines IV", description = "Our knowledge of technomancy deepens. Let's improve your weaponry inside the Manaforge.", objectives = "" }
WordHunterWoW_QuestEN[91480] = { title = "Behind Enemy Lines V", description = "We've got one last upgrade to give, my friend. Come by for one last tune-up and we'll make you the strongest you've ever been!", objectives = "" }
WordHunterWoW_QuestEN[91481] = { title = "Speed Siphoner", description = "Great work so far! We've finished some tech that should be useful during your assault on the Manaforge.", objectives = "" }
WordHunterWoW_QuestEN[91482] = { title = "Speed Siphoner II", description = "We've found a way to optimize the Speed Siphoner. Come back to HQ and let me give you a boost.", objectives = "" }
WordHunterWoW_QuestEN[91483] = { title = "Hacking the Mainframe", description = "Our saboteurs have made great progress on hacking Omega's security systems; swing by and let me tell you about what we've learned.", objectives = "" }
WordHunterWoW_QuestEN[91484] = { title = "Hacking the Forgeweaver", description = "We've progressed further in our infiltration of the Manaforge's defenses. Return to HQ and I'll clear you for access.", objectives = "" }
WordHunterWoW_QuestEN[91485] = { title = "Hacking the Planet", description = "Hero... we're in. We have full control of Manaforge Omega's security. I'll brief you on your next trip back.", objectives = "" }
WordHunterWoW_QuestEN[91486] = { title = "Attuned to the Aether", description = "Hello! I've learned valuable information about how exposure to Omega's manaflow is impacting you - let us discuss back at Shadow Point when you have a moment.", objectives = "" }
WordHunterWoW_QuestEN[91487] = { title = "Welcome to the Team", description = "", objectives = "" }
WordHunterWoW_QuestEN[91489] = { title = "A Curious Companion", description = "", objectives = "" }
WordHunterWoW_QuestEN[91493] = { title = "Not What I Ordered", description = "<A bite wound wrecks Hathvelion's forearm.>\n\nSnapdragons... cruel creatures made to kill and feed. Their poison moves as you move. The naga bred the perfect pet.\n\nI'm here on a tip from Lyssara Duskmourne. Sunsail Anchorage's shipping routes have been sabotaged by the naga, and those routes converge... here.\n\nI intercepted a few shipments. Could you help me search them? My team is still out in the field, but they should report back soon.", objectives = "" }
WordHunterWoW_QuestEN[91494] = { title = "One Elf's Trash, Another Elf's Treasure", description = "The arcane arts are not my specialty. I'm more versed in tangible magic--herbs, mixtures, distillation, topical applications, extraction, suture, painkilling...\n\nRegardless--that wand. To my uneducated eyes, it looks usable. Why don't you test it on the arcana container? Maybe it could help us against the naga. If it's truly broken, no harm done.", objectives = "" }
WordHunterWoW_QuestEN[91495] = { title = "Familiar Faces in Peril", description = "Fair winds guide your steps. My wish has come true--Eversong flourishes. But like before, evil threatens all that is good.\n\nTwo townsfolk are unaccounted for since the naga arrived: Enith--Goldenmist's most curious apothecary, and Varnis--he's a student visiting from the city. It is my charge to find them.\n\nMy fellow ranger, Vedoran, must still be in the field. I wonder if he's found something important. Will you keep an eye out for him?", objectives = "" }
WordHunterWoW_QuestEN[91504] = { title = "Arcane Amassing", description = "Well, you heard Numia. She'll have my bow split in two if I don't rest.\n\nRanger Vedoran reported activity at the lighthouse. A swarm of mana wyrms are gathered there, and of course, more naga.\n\nIf that's where the head of the snake lives, chop it off! My rangers Vedoran and Krann'an will accompany you. And take the wand with you. It proved its worth. Powered up, it should pack a punch against whatever you face.", objectives = "" }
WordHunterWoW_QuestEN[91505] = { title = "Daggers in My Spine", description = "The naga have a history of abusing arcane magic. I bet my boots this is no different--arcane is their lifeblood and source of power. They are clever to operate now while Eversong is besieged by other threats.\n\nSince I became a Farstrider, I have safeguarded Eversong's western coast. My strike team set up watch on Goldenmist's perimeter already. Fortunately, the naga do not seem interested in the town yet, but they are far too close for comfort.\n\nOur course of action is simple: clear them out!", objectives = "" }
WordHunterWoW_QuestEN[91522] = { title = "Order from Chaos", description = "Thank you for coming to speak with me, {name}. I know you are very busy these days.\n\nBut it is that very demand on your time that I wish to speak with you about. With all you have accomplished of late, I feel that there is bound to be some valuable data to be gleaned from your experience.\n\n As a {class} without equal, I would like to ask you about your deeds of late. Can you spare a moment for Moratari?", objectives = "" }
WordHunterWoW_QuestEN[91525] = { title = "Head Hunting: Loom'ithar", description = "Our intelligence describes a colossal beast within the Manaforge, responsible for producing the fabric that gives the Shadowguard their very form. Take it down and we'll hinder their ability to produce reinforcements. Oh, and Ba'choso says to bring some of the silk back with you - he may be able to fashion it into something useful.", objectives = "" }
WordHunterWoW_QuestEN[91526] = { title = "Head Hunting: Forgeweaver Araz", description = "My friend, I hope your assault is going well. It's time for you to dispatch the Forgeweaver; using his mastery of technomancy he oversees both the Manaforge's production pipelines... as well as the ritual to return Dimensius to this plane. His workshop will be further in and heavily guarded, but cutting him down should stop their plans of resurrection for good.", objectives = "" }
WordHunterWoW_QuestEN[91527] = { title = "Head Hunting: The Soul Hunters", description = "Careful in the wastes, my friend. Scouts report that a trio of Demon Hunters are training south of the Manaforge - with one of them exhibiting power like we've never seen. You can avoid their path if you wish, but ignoring them could open you up to being flanked should they decide to engage. I recommend taking them out if you can, as well as providing us some samples of their newfound strength.", objectives = "" }
WordHunterWoW_QuestEN[91528] = { title = "Head Hunting: Horrors of the Forge", description = "By now no doubt you've seen some of the Manaforge's Elite coming to Salhadaar's aid. I'm sending you a list of names now - focus on these targets, and you may uncover spoils to aid your assault.", objectives = "" }
WordHunterWoW_QuestEN[91529] = { title = "Head Hunting: Nexus-King Salhadaar", description = "The hour of Salhadaar's demise is upon us. While he may posture upon his Voidwing, he grows desperate at the feet of the All-Devouring. The army he commands is not enough for your might - strike him down.", objectives = "" }
WordHunterWoW_QuestEN[91530] = { title = "Seeing Eye to Eye", description = "", objectives = "" }
WordHunterWoW_QuestEN[91533] = { title = "What We Leave Behind", description = "Lothraxion deserved to pay for his arrogance with his life. Hieron didn't. Without him, I'd be dead. I know that Maella and Darkglen feel the same way.\n\nHieron's journal, the one you recovered for us, ended up with me. I knew Hieron, but Astre knew him better. The two of them had found a closeness I admired. Astre deserves to hold onto it.\n\nLast I saw Astre, Hieron was tending to their wounds back at Locus Point.\n\nYou were there when Hieron passed. They should know of his heroism and sacrifice.", objectives = "" }
WordHunterWoW_QuestEN[91535] = { title = "Home Sweet Grave", description = "<Astre spends a long time in silence, thumbing through Hieron's journal.>\n\nKilled on another world, defending a city that didn't want him. There was so much we planned to do. Now...\n\n<Astre trails off, their eyes focusing on the journal's pages.>\n\nOh. The tea recipe that Hieron was telling me about. He was excited for its properties--called it a purgative for the soul. He never had a chance to brew it.\n\nI know it seems stupid, {name}. I just want to taste Hieron's tea. The leaves should be nearby.", objectives = "" }
WordHunterWoW_QuestEN[91536] = { title = "Like a Weed", description = "<Astre looks from Hieron's journal to the worn letter. Their expression flickers with anger.>\n\nBlood elves. They were our people until we embraced the Void. In their ignorance, they exiled us. Yet they are happy to ask us to fight their battles for them.\n\nThey say we threaten the Sunwell. The truth is, they are afraid of us.\n\nLet's protect something of actual value. Kill any beasts that threaten those flowers for Hieron's tea. Silvermoon can save itself.", objectives = "" }
WordHunterWoW_QuestEN[91537] = { title = "Confronting It", description = "I've put the kettle on. I trust you to brew it, if you wouldn't mind. It shouldn't take more than a moment before the tea is ready to drink.\n\nLet me try it first, just in case it's poisonous. I'm the one that asked to try it.", objectives = "" }
WordHunterWoW_QuestEN[91539] = { title = "A Radiant Echo", description = "<Within your hand, you hold a small Azerite sphere. Its light is steady and bright, but the sound it emits is plaintive and longing. It tugs at you, ever so slightly.>", objectives = "" }
WordHunterWoW_QuestEN[91541] = { title = "Unchecked Emotions", description = "Ren'dorei learn early to check our emotions. That by controlling ourselves, we can control the Void. Otherwise, our unsuppressed feelings can lead us to ruin.\n\nBut I felt just now the powers of facing my feelings head-on. Maybe I could have done it on my own... But the tea, and your aid, made it easier.\n\nWe should share Hieron's recipe with the others. I'll retrieve the kettle you brewed.", objectives = "" }
WordHunterWoW_QuestEN[91542] = { title = "The Town Inside Me", description = "I can't say that drinking the tea is a pleasant experience. But it helps. I want the others to experience that too.\n\nThat Hieron left us with a gift like this is so... him. He was always doing little things like that for others. For me.\n\nShare the tea with the others, then join me at Obscurion Citadel. I know better than to be alone in a place like that.", objectives = "" }
WordHunterWoW_QuestEN[91543] = { title = "Retaking Control", description = "This world is violent and dangerous, but it has an order to things. After you and the others took down the domanaar that ran this citadel and its arena, the food chain must have fallen to disarray.\n\nHarrowers swarm the skies and darken the horizon. I worry they'll seek new hunting grounds closer to our settlements if they aren't dealt with.\n\nPoint them out for me and I'll use my grappling hook to pull them to the ground. Hieron's survival gear proves its use when we need it, as always.", objectives = "" }
WordHunterWoW_QuestEN[91544] = { title = "Familiar Energies", description = "I know that Hieron died here, but I feel echoes of someone else--of a great clash, where Void met Void. Hieron must have crossed blades with someone... something else. Something that's still out there.", objectives = "" }
WordHunterWoW_QuestEN[91545] = { title = "Stronger Than Before", description = "That must be the monster that killed Hieron. It's tearing open a backdoor for the Void's forces to pour into Silvermoon.\n\nThis damn city. I'm not doing this for them.\n\nSignal Umbric. Let's do this. Together.", objectives = "" }
WordHunterWoW_QuestEN[91546] = { title = "To Be Changed", description = "There is one unresolved matter...\n\n<Astre reaches into their pocket and reveals the worn letter you had unpackaged alongside Hieron's journal. They run their fingers over it with a pensive expression.>\n\nHieron wanted her to have it. She should know what happened to him.\n\nThis is on me. Silvermoon again... Guess I'll see you when I'm back, {name}.", objectives = "" }
WordHunterWoW_QuestEN[91550] = { title = "A Game of Silence and Shadow", description = "You're different! That makes you kinda cool... and kinda really suspicious. We wanna see what you're made of!\n\nSo here's the game: we hide, and you try to find us. If you do, well... guess we'll have to train more for next time. But if you don't? Then maybe our parents will finally let us go on our first solo hunt!\n\nThis isn't just a silly game, okay? It's a trial called Silence and Shadow. It's serious. Very, very serious.\n\nAre you ready?", objectives = "" }
WordHunterWoW_QuestEN[91551] = { title = "De-nest-stration", description = "If mom and dad find out, we are going to be stuck on fish gutting duty for the rest of our lives! \n\nThe elders keep telling us that fear is only useful if it sharpens the mind. Right now, we need clarity, not panic.\n\nWe have to get rid of those nests. Maybe if they are gone, we can eventually find the one they took Shao'mal to. And this way, we can finally drive off those stupid birds!\n\nWe're going to find him. Will you help us?", objectives = "" }
WordHunterWoW_QuestEN[91552] = { title = "Feathered Fury", description = "This would have never happened if those stupid petalwings weren't here!\n\nScare them off, chase them, whatever it takes--we just can't let them stay here. If they stay, they'll just keep hurting people. We can't let that happen.", objectives = "" }
WordHunterWoW_QuestEN[91553] = { title = "Haranir Never Say Die!", description = "That's the one! The big one! The one that took him!\n\nWe didn't stop it before. But this time, we will. We are haranir. And haranir never back down. Haranir never give up.\n\nWe're bringing him back. And we're ending this. Are you with me?", objectives = "" }
WordHunterWoW_QuestEN[91556] = { title = "Loa's Flame", description = "I will have to take what's left of de supplies back on foot.\n\nDe boat... it's no good now. De hull's cracked, and de frame's split. Won't carry another soul across de water.\n\nBut it'll still serve one final purpose.\n\nIt can be his pyre. We will burn it, de weapons, de armor he wore--everything with him.\n\nVengeance is done. Now we let de fire take him to de loa and to his rest.", objectives = "" }
WordHunterWoW_QuestEN[91557] = { title = "Message to the Molt", description = "Ah, champion! There are so many unique specimens to identify and catalogue here that I can't keep up.\n\nSpeaking of which, Lady Darkglen took time out of her busy schedule and coordinated an expedition to a particularly dangerous region north of here. I trust in her power, but I've not heard from her or her team in a while and am growing concerned. With any luck, they are simply caught up in their own research.\n\nThat being said, would you please find Lady Darkglen in the Molt and check in on her?", objectives = "" }
WordHunterWoW_QuestEN[91558] = { title = "Pestilent Petals", description = "A strange pathogenic presence has infected my fellow ren'dorei.\n\nWhen we arrived, I was awestruck by the colorful vibrancy of this decay-filled valley and its many blood-stained flowers. I had hoped to gather some for my collection... to study of course, but this pathogen was living in the same pestilent pools these blood petals thrive in. Are they naturally resilient, or do they have purifying qualities we can harness for a cure?\n\nDear {name}, please, cautiously gather blood petals for my research.", objectives = "" }
WordHunterWoW_QuestEN[91559] = { title = "Virulent Vermin", description = "The pathogen appears to spread unevenly among the Molt's wildlife.\n\nWhen my fellow ren'dorei were infected, they grew confused and unresponsive. The local fauna appear more resistant. I suspect some of the Molt's denizens have a stronger resistance than others. Perhaps by examining these beasts we can extract elements for a curative elixir.\n\nCould you gather livers from the creatures nearby?", objectives = "" }
WordHunterWoW_QuestEN[91560] = { title = "Expunging Explorers", description = "Let us hope we are able to concoct a cure from the reagents you acquired.\n\nI have already prepared the base potion, but now we need to carefully mix in the blood petals and livers you procured. With some calculated determination and a bit of luck, we should be able to craft an antidote and administer it to the afflicted ren'dorei scouts nearby.\n\n{name}, assist Blocciniux by mixing in the gathered ingredients.", objectives = "" }
WordHunterWoW_QuestEN[91561] = { title = "Bloodborne Pathogen", description = "The bloodborne pathogen has mutated!\n\nThe ooze-like carriers of this pathogen usually die quickly, but this new variant is stable even without a host. If it escapes from here, it could infect more ren'dorei and spread across Voidstorm, or worse yet, Azeroth. Our entire operation is at risk.\n\nWe must stop this mutated variant before it spreads!", objectives = "" }
WordHunterWoW_QuestEN[91563] = { title = "Halazzi's Hunt", description = "All of these spiders... \n\nThere must be someting dat we are missing. Halazzi knew exactly how to reveal them, though.\n\nGo to Halazzi's temple. I have no doubt that there is more to dis. Seek out his loa speaker.", objectives = "" }
WordHunterWoW_QuestEN[91565] = { title = "Voidscar Arena: The Grief Spire", description = "You, hero!\n\nVidious here wars with his nemesis, Ziadan, who has brought the most cutthroat, volatile members of the Horde here to fight for her. Murderers and traitors!\n\nThe leaders of the Alliance do not listen to our calls for action and vengeance! We must take matters into our own hands and support Vidious.\n\n<Amari looks you up and down and raises an eyebrow.>\n\nAnd if it is not hatred of the Horde that drives you, consider what valuable information you may glean by helping a powerful domanaar.", objectives = "" }
WordHunterWoW_QuestEN[91566] = { title = "Voidscar Arena: The Hate Spire", description = "Lok'tar ogar, {class}.\n\nThis domanaar, Ziadan, wars her old foe, Vidious, who has brought the most bloodthirsty, vengeful members of the Alliance here to Slayer's Rise to fight in his name.\n\nZiadan now gives the Horde a chance to stand up for our honor. Our leaders may not sanction this conflict, but when have we let anyone keep us from fighting the good fight?\n\nEven if you have no grievance with the Alliance, Ziadan's efforts keep Vidious from turning his eye on Azeroth. Report to her for your orders.", objectives = "" }
WordHunterWoW_QuestEN[91583] = { title = "Voidscar Arena: The Bastion of Valor", description = "Ziadan recently added your great foes, the Horde, to her ranks. However, it is not your fellow mortals that I see sieging my home.\n\nNo, I see monsters of Voidstorm, twisted and empowered, instead. Something is afoot. Has Ziadan added yet another new force to her army?\n\nGo and fight these monsters. Bring me any clues you find as to the source of their newfound power.", objectives = "" }
WordHunterWoW_QuestEN[91585] = { title = "Fresh from the Garden", description = "Age has caught up with me this morning and I have pulled something. \n\n<Yu'relen clutches his back.>\n\nStill, our village meal must be prepared. Otherwise, it will mean the loss of much more than just an empty stomach.\n\nIf you would gather some ingredients for the meal, your aid would not go unappreciated.", objectives = "" }
WordHunterWoW_QuestEN[91586] = { title = "Soil-Based Alternatives", description = "This meal is more than tradition--it is a promise.\n\nThe haranir, rutaani, and fungarians share no love, but in Har'mara they share this table. To honor that pact, each must be fed in their own way. That is what this meal means.\n\nFor the rutaani, they will need nutrient-rich soil as they draw sustenance through their roots. A few bags of it should do.", objectives = "" }
WordHunterWoW_QuestEN[91587] = { title = "Carcass Cuisine", description = "The fungarians are caretakers of decay, transforming death into life's renewal. \n\nThey require a sporeglider carcass to sustain their vast community. There is one--larger than most--that has taken to warding off the root drifters we need to sustain our village.\n\nIts end will feed many, and ease our burden. Balance, in more ways than one.", objectives = "" }
WordHunterWoW_QuestEN[91588] = { title = "Harandar's Kitchen", description = "Now comes the true work: preparing what's been gathered. \n\nThe vegetables must be washed, the bones removed, and the fish roasted. A shared meal is only worthy if made with care. Only then may the meal carry the weight of peace.", objectives = "" }
WordHunterWoW_QuestEN[91589] = { title = "Root Dash Delivery", description = "It's simple fare, but made with care and meaning. Please, take it to the gathering place. I am sure the villagers will show up when the food comes.\n\nDespite the simplicity, if it brings quiet among them, it has done its part.", objectives = "" }
WordHunterWoW_QuestEN[91597] = { title = "Voidscar Arena: For My Alliance", description = "My bastion is besieged by Ziadan once more!\n\nYou Alliance have proven to me you are strong. I am eager to see you in action upon the battlefield. \n\nMy own forces could use a taste of your courage. Take this Voidclarion and embolden the void underlings that fight for me. Let them know they have your backing. Let them feel the glory of your Alliance!", objectives = "" }
WordHunterWoW_QuestEN[91598] = { title = "Voidscar Arena: Pre-Provoked Violence", description = "So, Ziadan would stoop so low as to use shadowgraft? Can she not adequately stir the bloodlust of her Horde minions? She's lost her touch.\n\nI need no such army to overpower her. I have you.\n\nShow her how it's done. Decimate her forces before they reach beyond the bounds of Slayer's Rise. They could threaten your precious mission here, after all.", objectives = "" }
WordHunterWoW_QuestEN[91599] = { title = "Voidscar Arena: A Familiar Grudge", description = "It is time to take the fight to Ziadan.\n\nShe undoubtedly has her own favorite pet--someone from your world who takes this conflict personally. She is particularly fond of the flavors of rage.\n\nI prefer aching, heart-wrenching grief, myself, and we shall prove which fuels you mortals with greater strength.\n\nAmong their forces is a dark warlock that has slain many of your kind. I've tasted their rage in the air.\n\nGo. Savor the fight.", objectives = "" }
WordHunterWoW_QuestEN[91600] = { title = "Voidscar Arena: Setting It Aside", description = "I knew shadowgrafting was beneath Ziadan. I would not spend eons locked in conflict with one so uncouth.\n\nTherefore, our little game has an uninvited guest. Not you, of course. We love watching you kill for us.\n\nTo the far north is the Voidscar Arena. The last time another domanaar tried to come between us, they built that citadel. It has laid empty for ages.\n\nIf another domanaar intends to challenge us, they will have staged their forces there.", objectives = "" }
WordHunterWoW_QuestEN[91603] = { title = "Voidscar Arena: Two Against One", description = "You. Alliance weakling.\n\nShadowgraft requires a potent font to power it--likely more than one, given this many creatures. They will be nearby. Destroy the power sources, then meet us on the next ridge.\n\nRemember: if this domanaar succeeds, their conquest will not end in Slayer's Rise. They will find a way to your homeworld. They would shadowgraft Azeroth herself. Put an end to this.\n\nMeanwhile, I suppose I shall relish in this opportunity to observe Vidious's weaknesses up close.", objectives = "" }
WordHunterWoW_QuestEN[91605] = { title = "Voidscar Arena: The Wrong Side", description = "Indeed, the Voidscar Arena is crawling with Void once again. A domanaar rules here, I have no doubt.\n\nThey have not yet emerged to parlay. Our mysterious interloper must not be present. That is well.\n\nLet's have you put an end to this charade. Destroy their forces. Destroy their resources. And turn their tools against them. Make them feel the disdain I feel for them.\n\nZiadan and I shall investigate this interloper.", objectives = "" }
WordHunterWoW_QuestEN[91606] = { title = "Voidscar Arena: Clearing House", description = "A waste of a great monstrosity. Imagine its cunning were it not frenzied! It would have made a fine addition to my collection.\n\nThe shadowgrafting must end. I doubt this domanaar is doing the work himself. There must be a grafter nearby. \n\nWhile Ziadan and I weaken this monster, find and slay the grafter. Then these shadowgrafted monsters will never breach your precious world.\n\nIf nothing else, that will finally draw out our enemy.", objectives = "" }
WordHunterWoW_QuestEN[91613] = { title = "Infinite Research Promotion: Timely Assistant", description = "", objectives = "" }
WordHunterWoW_QuestEN[91614] = { title = "Focusing the Energies", description = "In addition to shards of nightmare, we need Blood of Sargeras to reactivate the portal to the Rift of Aln.\n\nThis rare reagent can be obtained from around the Broken Isles. Rumor has it that emissaries are in search of hardened adventurers, and may offer these in reward.", objectives = "" }
WordHunterWoW_QuestEN[91615] = { title = "A Thirst For Blood", description = "Blood is the fountain of life and the fuel of my creations. Unfortunately, Deathlord, my supply is running low and the quality as of late has been disappointing at best.\n\nIf my undead offspring are to reach their full potential, I will need pure blood of the highest quality. Bring me the Blood of Sargeras and I will use it to fuel my finest creations!", objectives = "" }
WordHunterWoW_QuestEN[91616] = { title = "Required Reagents", description = "The Sentinels know of a trusted and talented enchanter who specializes in enchantments that affect demons.\n\nShe provides her services for free to the Sentinels, but she does require specific reagents to perform her enchantments.", objectives = "" }
WordHunterWoW_QuestEN[91618] = { title = "A Few Things First", description = "Lately I've been working with the ore of this land, leystone it's called. I've found its qualities to hold remarkable strength and durability. We'll need a lot of it for this.\n\nThere is felslate, but that's probably too tainted for what you're looking to do with this barding.\n\nYou know, I also like to adorn my pieces with something sparkly, like a jewel. I've heard that the elves of Suramar have particularly beautiful ones. Perhaps you could acquire one for this project.", objectives = "" }
WordHunterWoW_QuestEN[91619] = { title = "Blood of Sargeras", description = "We will require a powerful reagent to bind the magic in our weapons and armor. A rare material that will do just the trick is Blood of Sargeras.\n\nWe will need a plentiful quantity. Bring me whatever you can muster.", objectives = "" }
WordHunterWoW_QuestEN[91620] = { title = "Noggenfogger's Reasonable Request", description = "Oh, the gall of that little green twerp! Marin Noggenfogger is blackmailing us. He says that if we do not meet his \"very reasonable requisition request\", he is going to close off access to the crucible.\n\nMarin's asking for a hefty amount of Aethril. He said something about you recently holding a blade to his throat and that he's simply returning the favor.\n\nOf course, if you would rather, I can eliminate him.", objectives = "" }
WordHunterWoW_QuestEN[91621] = { title = "A Taste For Blood", description = "Such an egg is quite precious, fleshling. Yet, my hunger gnaws so deep...\n\nSuch a barter will cost you... greatly.\n\nBring me 3 Blood of Sargeras, and I will give you the egg.", objectives = "" }
WordHunterWoW_QuestEN[91624] = { title = "Spark of Starlight", description = "A vision of starlight permeates your mind.\n\nCustodian Khubon might have more information regarding these Fractured Sparks of Starlight.", objectives = "" }
WordHunterWoW_QuestEN[91627] = { title = "Saltheril's Haven", description = "{name}, I presume? Very good. Your reputation precedes you.\n\nLord Saltheril sends his most sincere greetings, along with a cordial invitation to join him at his estate south of Silvermoon.\n\nA portion of the grounds have been carved out as a decadent haven for those seeking refined company and pleasant conversation. He believes you would bring a... unique perspective.\n\n<He looks you over with a hint of polite disdain.>\n\nReceiving an invitation is a rare honor. His lordship hopes you will accept.", objectives = "" }
WordHunterWoW_QuestEN[91628] = { title = "Honored Guests", description = "I am pleased you could join us. Today marks the start of a very special occasion.\n\nThe sin'dorei are no strangers to the war table, but its aristocracy prefers to play more coy. In wartime, the crown sends representatives to curry favor with the nobles. If they are pleased, they might lend gold to the war effort.\n\nIt is very much like courting a lover, with all the jealous games you might imagine.\n\nSo let us play the game, shall we? Deliver these invitations while we finish preparations here.", objectives = "" }
WordHunterWoW_QuestEN[91629] = { title = "High Esteem", description = "Invitations to my Haven are highly exclusive, especially at a time like this. Extending an offer, even a temporary one, is a great honor.\n\nMy favor carries quite a bit of weight amongst the aristocracy. If I invite an ally of one of our representatives, it suggests I think highly of them--and if I think highly of them, so too will our noble guests.\n\nBut is it not terribly fun if I let you choose an invitation instead?\n\nGo peruse any enticements they may offer, then make your selection.", objectives = "" }
WordHunterWoW_QuestEN[91630] = { title = "Stolen Sight", description = "I can explain, I swear it!\n\nI concealed my knowledge of Shadra before because so many people assume she is an evil force. Our lady is merciless, but only to her enemies. \n\nWhen de Witherbark left de Hinterlands, we had to leave our temple of Shadra'Alor. I brought two of her relics with me: de eye and de fang.\n\nDe Vilebranch stole de fang. Dey are near where I hid the Eye of Shadra, collectin' venom from her children! Please kill de Vilebranch trespassing in the crypt. We can't let dem find de eye.", objectives = "" }
WordHunterWoW_QuestEN[91631] = { title = "Epoch Progress", description = "", objectives = "" }
WordHunterWoW_QuestEN[91632] = { title = "The End of an Epoch Journey", description = "", objectives = "" }
WordHunterWoW_QuestEN[91639] = { title = "Embrace Your Own Legend", description = "I will keep a close eye on your progress and watch your exploits with that artifact unfold with great interest.\n\nOnce you have embraced the power of your own legend, I would like to hear your perspective on how important the artifact you wield has been on your journey.", objectives = "" }
WordHunterWoW_QuestEN[91691] = { title = "The Vanishing of Iridikron", description = "As you traveled through Zaralek caverns, Chronormu and I confronted Iridikron and the Infinite Dragonflight.\n\nWhile we defeated the Infinite Dragonflight's champion, Chrono-Lord Deios, I fear Iridikron escaped.\n\nAllow me to show you what happened, for it gives us a clue of what must be done next.", objectives = "" }
WordHunterWoW_QuestEN[91693] = { title = "The Subtle Game", description = "Appearances are everything. If the court sees that I favor a certain group, they will follow suit.\n\nTake these tokens of my favor and hand them out to our honored guests as you see fit. I suspect they may invite you to partake in their plans and share in the profits, if you choose to align yourself with their cause.", objectives = "" }
WordHunterWoW_QuestEN[91694] = { title = "Voidscar Arena: Breaking the Triad", description = "That glint in your eye! You've already identified me as an enemy and are thinking about how to slay me, yes? Good. \n\nI sent my forces to Ziadan and Vidious's bastions to overthrow them. Then, Xal'atath's bidding pulled me away and I missed all the action.\n\nFortunately, you are here now. You seem like even greater entertainment than watching these two smitten fools refuse to actually end one another.\n\nCome, then! I will prepare my arena and we will put on a real show! Slay me, if you can!", objectives = "" }
WordHunterWoW_QuestEN[91695] = { title = "Tracking Down Incarnates", description = "We must turn our attention to Fyrakk and Vyranoth with Iridikron seemingly vanished from our sight.\n\nMerithra and the Green Dragonflight have been pursuing him and have a lead. \n\nThey've received the aid of Shandris Feathermoon in this task.\n\nShe awaits you within Valdrakken. Shandris will need your help with what is to come.", objectives = "" }
WordHunterWoW_QuestEN[91700] = { title = "Darkness Unmade", description = "The Void energies concentrated in this citadel have given rise to numerous aberrant creatures.\n\nWildlife mutated by residual energy and horrors originating from beyond the anomalies, continue to feed and draw upon the energies here. It is most unpleasant!\n\nTo safeguard my future enterprises, these threats must be neutralized.", objectives = "" }
WordHunterWoW_QuestEN[91721] = { title = "Surpass Your Own Legend", description = "While artifacts are key, we must not dismiss the power of the individuals who wield them.\n\nContinue in your fight against the Legion. Grow strong, stronger than you ever thought possible.\n\nThen we will compare the might of your legend against that of the artifact.", objectives = "" }
WordHunterWoW_QuestEN[91722] = { title = "Shape a New Legend", description = "It is clear now that the person is at least as important as the artifact they wield.\n\nPerhaps it is the quality of mortality that diminishes the importance of the individual through the lens of history. While an artifact is eternal, the people wielding them are fleeting.\n\nBut no flame that burns brightly burns forever.\n\nI want you to burn as brightly as you can. Empower your artifact and carve a new legend into the world for all to see.", objectives = "" }
WordHunterWoW_QuestEN[91726] = { title = "Unstoppable Force", description = "This statue seems out of place here. Nothing else like it. But this is where Anduin Lothar fell against Orgrim Doomhammer at the Battle of Blackrock Mountain.\n\nMany fought on this field. Many didn't make it. Lothar... \n\nLet me tell ye what happened all those years ago.", objectives = "" }
WordHunterWoW_QuestEN[91727] = { title = "Isles United", description = "I never doubted you for a second, {name}.\n\nI wanted to reflect on all that you accomplished in your fight against the Legion.", objectives = "" }
WordHunterWoW_QuestEN[91728] = { title = "Suramar Liberated", description = "You have come a long way, {name}. I never seem to tire of following your exploits. Even from afar, as a silent observer, I find myself absolutely invested in what you will do next.\n\nI do have one question though.", objectives = "" }
WordHunterWoW_QuestEN[91729] = { title = "Armies Gathered", description = "The stakes have never been higher than now, {name}.\n\nI would very much like to know what you are thinking right now.", objectives = "" }
WordHunterWoW_QuestEN[91730] = { title = "Azeroth Saved", description = "{name}.\n\nYou have done it! Sargeras is gone and Azeroth is saved.\n\nI can only imagine what must be going through your mind at this moment.\n\nLet us remedy that.\n\nAllow me to record your thoughts and your words. Not as written by a historian who you never met, but by a friend who wished nothing more than to listen.", objectives = "" }
WordHunterWoW_QuestEN[91731] = { title = "Midsummer Test", description = "", objectives = "" }
WordHunterWoW_QuestEN[91747] = { title = "Not Quite Nalorakk", description = "Were you the one we saw enter Nalorakk's temple with Zul'jarra?\n\nI thought so! Zul'jarra spoke to him, didn't she?\n\n<Furgh growls in an unsettling way from deep in his throat.>\n\nThat doesn't make sense. The new Voice of Nalorakk says Nalorakk won't speak to anyone but him.\n\nHe gave some of the tribe trinkets to feel closer to Nalorakk. But the tribe now fights over them. The ursas think it's unfair they don't get any. But the chosen cling to them.\n\nWe must take them before more blood is spilled.", objectives = "" }
WordHunterWoW_QuestEN[91748] = { title = "Too Much Twilight", description = "This big bear called himself the Voice of Nalorakk and has \"chosen\" some of our tribe as his favorites. He doesn't know, but I saw him put dark, glowing lodestones in the totems around the village to give his chosen power.\n\nDark power radiates from them. The power smells wrong. Not like Nalorakk.\n\nOur guardian bears get agitated and upset near them. They can smell it too!\n\nWe must cleanse the camp. Get rid of those totems!", objectives = "" }
WordHunterWoW_QuestEN[91749] = { title = "It's Just Not Right", description = "If Chief Groffa is leading the tribe into the dark, he needs to be stopped. The Voice of Nalorakk dazzled Groffa with trinkets. He keeps them locked away so no one else can have them.\n\nIf that is true, he's corrupted too. Even more than the others!\n\nStop him and get the gifts out of the village.", objectives = "" }
WordHunterWoW_QuestEN[91750] = { title = "Perils of Trust", description = "That was scary. We nearly lost Furgh!\n\n<Fleeg's fur twitches in fear and worry as he looks Furgh over.>\n\nFurgh said he heard the Voice of Nalorakk talking to him after touching the treasures.\n\nBut it can't be Nalorakk's voice. Nalorakk doesn't need trinkets!\n\nRip out the throat of this evil that dares to say it speaks for Nalorakk!", objectives = "" }
WordHunterWoW_QuestEN[91757] = { title = "Until Our Next Hello", description = "Well, the moment is fast approaching now.\n\n<Moratari subtly nods in the direction of the raging temporal storm overhead.>\n\nYou would think after so many goodbyes I would be better at this, but alas, I simply prefer hello over goodbye. I know a lot of people around here are going to miss you too.\n\nYou should go say goodbye to them while there is still time.", objectives = "" }
WordHunterWoW_QuestEN[91768] = { title = "Sweating Mana", description = "Default Description", objectives = "" }
WordHunterWoW_QuestEN[91780] = { title = "Ethereal Delves", description = "There's even more tae do in delves, {name}! \n\nMeet me in Dornogal. There's loads to discuss!", objectives = "" }
WordHunterWoW_QuestEN[91781] = { title = "Seasonal Reminder", description = "We're back tae uncovering even more things within delves! \n\nLet's get ye up to speed on what's new first.\n\nAfter that I'll need your help with a wee problem of my own...", objectives = "" }
WordHunterWoW_QuestEN[91782] = { title = "Repossessed!", description = "I think ye may have guessed what my problem is by now, {name}.\n\nMy clothes, my tools, my curios! Everything but my boots and hat, which I'm nae giving up again.\n\nAll repossessed by some cartel thug who said I was delinquent on my void storage payments, if ye can believe it.\n\nWould ye be willing to help Ol' Brann out of this pickle? I'm sure if ye just explain that this is all some sort of mistake, they'll give back all my hard earned gear.\n\nOr at least me britches.", objectives = "" }
WordHunterWoW_QuestEN[91787] = { title = "The Journey Ends", description = "The Light takes many forms. But I know now what it means to me, and how I want to wield it.\n\nI'm not just a weapon like my father, nor can I devote myself purely to service like Dezco.\n\nBut I can protect people from the evil that threatens them. Right now, that's Xal'atath and her Devouring Host.\n\nWe should return to Lor'themar and do whatever is needed to defeat the Void.\n\nBeyond that, I shall see where protecting others with the Light takes me.", objectives = "" }
WordHunterWoW_QuestEN[91795] = { title = "Disrupt the Call", description = "We do not know where they intend to strike, but we do know they aim to summon more to their cause.\n\nDestroy the Twilight's Blade before they complete their rituals. We must not let a single champion of the void remain to inspire the new recruits.", objectives = "" }
WordHunterWoW_QuestEN[91813] = { title = "The Spiritpaw", description = "I just chased away some furbolg dat were actin' real strange.\n\nDey were arguin' and then one walked toward Lilaju with his hands in de air.\n\nI charged at dem an' scared dem off. Dey are usually hostile and who knows what dey were gonna do?\n\nBut Lilaju wants to see what dey wanted.\n\nOur scouts saw dem follow de river east to de north side of de lake. Track dem down. See what dey want.\n\nIf it's a trick, then kill dem.", objectives = "" }
WordHunterWoW_QuestEN[91821] = { title = "Out of Time", description = "There you are, {name}. This timeline is collapsing!\n\nPresumably you have noticed the great rift tearing through reality above us. We don't have much time remaining before we must retreat from this timeline.\n\nTo make matters worse, infernals from other timelines are starting to pour in. Send them back from when they came.", objectives = "" }
WordHunterWoW_QuestEN[91822] = { title = "The Regent's Request", description = "Lor'themar has requested our presence. He wasn't exactly forthcoming with the details, but the location he chose speaks volumes.\n\nSilvermoon Harbor. Quiet and out of sight. Not exactly the kind of place one picks for diplomacy or ceremony. No, this feels like something else entirely. Whatever he's planning, it won't be written down in any official record. \n\nCome. Let's find out what the Regent Lord has to say.", objectives = "" }
WordHunterWoW_QuestEN[91823] = { title = "Lines Cut, Tongues Silenced", description = "The Twilight's Blade slipped into Tranquillien so easily because they'd stolen knowledge and secrets. About our defenses, our magic, our people. Once inside, they uncovered even more information. \n\nNow they pass that intelligence between themselves using enchanted orbs. Quiet whispers drifting through the dark. Every message tightens the noose around Quel'Thalas.\n\nFind the orbs. Break them. Every shattered crystal is a whisper silenced.", objectives = "" }
WordHunterWoW_QuestEN[91824] = { title = "The Thieves' Trail", description = "From what I can see, it looks like the Twilight's Blade stole several arcane artifacts used by our Magisters to enhance long-distance communication. If they learn to wield them, they'll cast their reach far beyond what we can contain. They might even be able to hear our communications... and we can't have that.\n\nRecover the artifacts. If anyone gets in your way... you know what to do.", objectives = "" }
WordHunterWoW_QuestEN[91825] = { title = "Dead Men Keep No Secrets", description = "From what I've seen, this group isn't acting without direction. There's someone leading them, a man hiding in one of their structures.\n\nIf I had to guess, he's the one holding whatever they considered too important to trust to crystal or courier. Documents, plans, names.\n\nFind him, silence him, and bring back whatever he was protecting.", objectives = "" }
WordHunterWoW_QuestEN[91826] = { title = "Tripwire Tango", description = "This cache isn't locked with magic. It's craftsmanship. I can hear the mechanism ticking inside. Tiny cogwheels, tension springs, and probably a poison vial ready to shatter the moment someone tries to pick the lock.\n\nWe'll have to do this together. I'll take the pins, you keep the mechanism from snapping. One wrong move and it'll be enough to drop an ogre in mid-charge. Steady now.", objectives = "" }
WordHunterWoW_QuestEN[91827] = { title = "No Loose Ends", description = "You handled yourself well.\n\nThese documents are too important to pass through couriers or ravens. I'd like you to deliver them personally to Lor'themar. He'll want to see the truth for himself and know who brought it back.\n\nKeep them close, and don't let anyone else near them.", objectives = "" }
WordHunterWoW_QuestEN[91828] = { title = "A Favor for the Lion", description = "A letter arrived for me. No seal, no name. Just folded parchment and handwriting I'd recognize anywhere.\n\nIt didn't say much. He never wastes words. \n\nI've known his family a long time. When they reach out, I answer.", objectives = "" }
WordHunterWoW_QuestEN[91829] = { title = "One by One", description = "Every last cultist is a threat to the people we're trying to save. To Silvermoon itself.\n\nBlasted fanatics with blood on their hands and no intention of letting anyone walk out alive.\n\nWe're already in the camp. Let's make it count. I want them to feel this.", objectives = "" }
WordHunterWoW_QuestEN[91830] = { title = "Intercepted", description = "The Twilight's Blade hit Tranquillien hard. Slipped in and took all the supplies and information they could ever need, right beneath everyone's nose.\n\nTime to return the favor.\n\nI've marked a few tents. Command posts, messengers' satchels, a supply ledger tucked under a wine crate. That's where they keep their orders, maps, and routes.\n\nGrab everything you can.", objectives = "" }
WordHunterWoW_QuestEN[91831] = { title = "Keys Are Optional", description = "These people joined the Twilight's Blade looking for purpose, power, or place to belong. For a reprieve from the fear and a promise of certainty.\n\nNow they see it for what it is--a prison dressed up as faith. And they want out.\n\nWe go in together. Get them out before the cult realizes what's happening.", objectives = "" }
WordHunterWoW_QuestEN[91833] = { title = "Dirty Deeps", description = "De Vilebranch are sinkin' deeper into their cursed minds. Dey spit in de face of de loa, and believe dey have mastered death.\n\nI could see a certain... someone not likin' dat way of thinkin'.\n\nDey have taken our kin and now dey take our shaman. Meet my scout there and help dem break their plans.\n\nCut de head off de beast and de body will fall.", objectives = "" }
WordHunterWoW_QuestEN[91834] = { title = "Guardians Must Go", description = "Get rid of shield face and meet me in de hut below.", objectives = "" }
WordHunterWoW_QuestEN[91835] = { title = "Send Dem Home", description = "My friend, dis is a mighty gift. Shadra is givin' us a blessin' for de tasks ahead.\n\nThese Vilebranch really are livin' up to their name. Dey drain de spirit from de Witherbark and create undead to serve dem.\n\nWe must free de Witherbark from these necrotic bonds.\n\nMy friend's still in there... I hope. Me and Bin'zin cut our tusks together growin' up. He grew into a strong shaman. Our village needs him, and he is like a brother to me.", objectives = "" }
WordHunterWoW_QuestEN[91836] = { title = "Respect de Totem", description = "When dey took Bin'zin, de priestess destroyed his totems and gave de shattered remains to her minions--like some grisly memento.\n\nTake de pieces back, one by one if ya have to. Dat disrespect will not stand.", objectives = "" }
WordHunterWoW_QuestEN[91837] = { title = "Bring Back De Bones", description = "Big thanks for breakin' us free. Some were not so lucky.\n\nBring dey bones back to de Chief, he will know what to do.", objectives = "" }
WordHunterWoW_QuestEN[91838] = { title = "De Vile Diminished", description = "These vile orbs are harvestin' de souls of our people and sendin' dark energy to de Knife Priestess. She's gettin' mighty powerful.\n\nDestroy de orbs so her ritual of death is ruined. With de gift of Shadra, ya will not fail.", objectives = "" }
WordHunterWoW_QuestEN[91839] = { title = "Sacrifice Denied", description = "Our shaman is home and Jin'zin's full of joy to see him again. She was always his little wildcat apprentice.\n\nDey will have sad moments--Tan'zin is a mighty loss.\n\nToday, ya brought him home. Go enjoy dat for a bit, {name}, before ya be on ya way.", objectives = "" }
WordHunterWoW_QuestEN[91840] = { title = "One Will Not Rise", description = "Now's our best shot! We end de sacrifices here! Stoppin' de dark energy has weakened her hold.\n\nThen, you can be de one to bring back her head.\n\nUh, and {name}--no tellin' de chief about me callin' him Big VunVun. He'll be turnin' me into a frog if he hears dat again.", objectives = "" }
WordHunterWoW_QuestEN[91842] = { title = "Disarm the Dark Horde", description = "The Dark Horde have no love fer their equipment. Look at their weapons! Cracked, rusted, blunt, and bent. Ach!\n\nThe only way they function is by making more shoddy tools to constantly replace the ones they've broken.\n\nIf ye see any of their weapon racks, destroy 'em. Let's see how well they fight without their rusty blades.\n\nA bare-fisted orc is nothing to sneeze at, but it'll further delay any daft plans they've got.", objectives = "" }
WordHunterWoW_QuestEN[91843] = { title = "Recap: The Harbinger", description = "To understand the story of The War Within, one must first begin with the mysterious entity known as the Harbinger, and how the heroes of Azeroth uncovered the truth...", objectives = "" }
WordHunterWoW_QuestEN[91844] = { title = "Infinite Research Promotion: Honorary Chronographer", description = "", objectives = "" }
WordHunterWoW_QuestEN[91845] = { title = "Infinite Research Promotion: Senior Executive Chronographer", description = "", objectives = "" }
WordHunterWoW_QuestEN[91846] = { title = "Infinite Research Promotion: Principal Chronoquery Investigator", description = "", objectives = "" }
WordHunterWoW_QuestEN[91854] = { title = "Deepening Shadows", description = "Champion, I could use your assistance. The natives here in Silvermoon are proving to be less hospitable than we had hoped. \n\nIn their defense, their city is facing down a darkness unlike anything Azeroth has ever faced, so tensions are high.\n\nCan you use your unique perspective and help de-escalate some of the hot spots that are emerging around Silvermoon?", objectives = "" }
WordHunterWoW_QuestEN[91855] = { title = "Worldsoul: K'aresh World Quests", description = "I know now that the heroes of Azeroth venture wherever help is needed. K'aresh is a strange, faraway place, but our allies there need us.\n\nGo there and help them. See what you can do to bring respite to the ethereals and brokers.", objectives = "" }
WordHunterWoW_QuestEN[91863] = { title = "My First Home", description = "Welcome to the neighborhood! Feel free to explore and have a look at the plots available.\n\nSpeak to the steward to learn more about the process of becoming a homeowner or if you wish to create your own neighborhood.", objectives = "" }
WordHunterWoW_QuestEN[91864] = { title = "Recap: Fractured Visions", description = "All across Azeroth, many were having visions of a Radiant Song. Efforts to understand what seemed to be a warning centered on the heroes in Dalaran.", objectives = "" }
WordHunterWoW_QuestEN[91865] = { title = "Catch Up: Khaz Algar", description = "The Earthen of Khaz Algar eventually welcomed the outsiders into their land, but all was not well with them. Divisions had grown among their people. To unravel Xal'atath's plot with the Nerubians, the Champions would have to address these issues.", objectives = "" }
WordHunterWoW_QuestEN[91866] = { title = "Catch Up: The Ringing Deeps", description = "The Champions travel with Brinthe of the Earthen and Moira, Dagran and Magni Bronzebeard to the Ringing deeps. There they find not all is well as a mysterious affliction has touched some of the workers.", objectives = "" }
WordHunterWoW_QuestEN[91867] = { title = "Catch Up: Hallowfall", description = "King Anduin Wrynn, Alleria and the Champions travel deeper into Azeroth, arriving at a place known as Hallowfall. It quickly become apparent that this place has also been touched by the machinations of Xal'atath.", objectives = "" }
WordHunterWoW_QuestEN[91868] = { title = "Recap: Shadowy Pursuits", description = "King Anduin Wrynn, Alleria, and the champions travel deeper into Azeroth, arriving at a place known as Hallowfall. It quickly becomes apparent that this place has also been touched by the machinations of Xal'atath.", objectives = "" }
WordHunterWoW_QuestEN[91869] = { title = "Catch Up: A Light in the Dark", description = "The War Within continued on Khaz Algar as the peoples of the land began to unite against Xal'atath and her Dark Heart.", objectives = "" }
WordHunterWoW_QuestEN[91871] = { title = "Recap: The Dark Heart", description = "The champions and Alleria were invited to Undermine by Gazlowe as the peoples of Khaz Algar and beyond began to unite against Xal'atath and her Dark Heart.", objectives = "" }
WordHunterWoW_QuestEN[91872] = { title = "The Former Rootwarden", description = "{name}, I was the Rootwarden of Teldrassil. For years, I watched the roots here below the surface, but I was not aware of what was threatening the tree outside of Harandar.\n\nFor just as long, I have regretted that failure, but we cannot change the past.\n\nI wonder, however, if roots so great may still have life within them. Might there be something which can still be done?\n\nI do not know, but I do hope. Will you join me at the Shrine of Ages, to tend the roots?", objectives = "" }
WordHunterWoW_QuestEN[91873] = { title = "Buffer Zone", description = "At this shrine, I have worked to gather roots that seem to still have the possibility of life within them. They are each greatly damaged, some more than others. My hope is some might recover, with enough time and enough care. In that way, I honor the great tree's memory.\n\nFor that to be possible, though, we have to keep them safe from the hazards of Harandar.\n\nPlease be sure that nothing nearby threatens them.", objectives = "" }
WordHunterWoW_QuestEN[91874] = { title = "Flare Up", description = "{name}, I see smoke rising above Har'mara. The roots are on fire--not here, but beneath the remnants of the tree!\n\nI have seen this happen many times, but we must always respond with haste.\n\nTake to the skies and douse them, immediately!", objectives = "" }
WordHunterWoW_QuestEN[91875] = { title = "Natural Remedy", description = "If we ever hope to see new growth, Teldrassil's roots needs a great deal of special attention.\n\nThe source of this stream is one of the great roots. The water carries ash, which I believe still contains the tree's essence.\n\nThe stalkers in the stream carry a mixture of that ash and slime from their tendrils--a very potent mixture.\n\nBring me as much of it as you can carry, and I will combine it with reagents I've gathered. Then we'll be ready to apply it to the roots.", objectives = "" }
WordHunterWoW_QuestEN[91876] = { title = "Tending Hope", description = "Thank you for tending to those fires, {name}. While you were gone, I've used that sludge to make a salve. Help me spread it over Teldrassil's roots.\n\nIt may take years to see a difference, if we ever do. But though I failed, I made oaths to her, and I can still choose to keep them. I will never stop doing what I can to... help her perhaps grow again.\n\nIf I do not succeed, the next Rootwarden, or the one who comes after that, may be the one to finish this work. Even so, I shall not stop trying.", objectives = "" }
WordHunterWoW_QuestEN[91884] = { title = "The Illusion of Motion", description = "You! Have YOU seen them?\n\nI've been tasked to investigate some of our scouts that have gone missing. My reconnaissance had come up empty until recently.\n\nNow I've been catching glimpses of the missing scouts, but... they appear formed of pure Void energy.\n\nEach time I chase the figures, they lead me further and further before disappearing!\n\nThe others think I'm crazy. You haven't seen anything like that, have you?", objectives = "" }
WordHunterWoW_QuestEN[91885] = { title = "Drain You", description = "Do you... see...? They follow... They plead... for help...\n\n<The voidwalker strains and shudders as it tries to communicate.>\n\nToo weak... too starving...\n\n<It feebly hands you a shard of dark matter.>\n\nThis... will feed me... then together... we find the missing elves...", objectives = "" }
WordHunterWoW_QuestEN[91886] = { title = "Voices of Omens", description = "The voices of your elven allies rattle inside my head.\n\nI know of a way we can find them. There is a way to locate missing things... using old domanaar scanning devices.\n\nBut they require immense energy to function. Together, we can use these devices to focus the images of your lost friends. Their cries for help will become clearer, and then you can find them.\n\nCome. Lend me your strength.", objectives = "" }
WordHunterWoW_QuestEN[91887] = { title = "Dominion of Deceit", description = "We were right to be cautious. The threats we've found here in the Voidstorm are corrupting and irredeemable.\n\nThis voidwalker's meticulous deceptions are unusual... I can't help but wonder why it would go through all the trouble. \n\n<She looks up at you from weary, withered eyes.>\n\nBut I'm too weak to go on. It really did a number on me. You have the upper hand now! It thinks you're walking into its trap.\n\nWalk in with weapons drawn and spells ready!", objectives = "" }
WordHunterWoW_QuestEN[91918] = { title = "Delves: Measure Once, Cut Twice", description = "We've done well to see those deserters to safety, but don't fool yourself into thinking we've freed them all.\n\nI've heard whispers of a place they use to break those whose loyalty is in question. The location isn't common knowledge, but I know where to start looking.\n\nIf we're quick, we might find others before the cult decides they're too great a risk to keep alive.\n\nMeet me near the site. Keep your blades sharp and your steps light.", objectives = "" }
WordHunterWoW_QuestEN[91928] = { title = "What's For Lunch?", description = "My Shadowtrade Mercenaries will fight for Stormarion Cores, no questions asked, but they do get hungry also!\n\nFood is quite scarce here, so we need supplies!\n\nTake a mercenary out with you and find some food for them to eat. I'll make it worth your while!", objectives = "" }
WordHunterWoW_QuestEN[91929] = { title = "What's For Lunch?", description = "My Shadowtrade Mercenaries will fight for Stormarion Cores, no questions asked, but they do get hungry also!\n\nFood is quite scarce here, so we need supplies!\n\nTake a mercenary out with you and find some food for them to eat. I'll make it worth your while!", objectives = "" }
WordHunterWoW_QuestEN[91930] = { title = "The Abundant Lands", description = "De loa have reunited with us forest trolls, and de land reacts with glorious bounty!\n\nDo ya wish to take part? Then go north, and meet me at de entrance to Loaknit Den.\n\nThere I will introduce ya to prosperity and plentitude like ya never seen...", objectives = "" }
WordHunterWoW_QuestEN[91932] = { title = "The Abundant Awakening", description = "De Loa of Abundance accepts everyone, and everyone de Loa of Abundance accepts is granted de privilege of learnin' how best to serve abundance.\n\nSpeak with his glorious visage and become a fellow acolyte.", objectives = "" }
WordHunterWoW_QuestEN[91933] = { title = "The Abundant Honor", description = "On to the next phase of your education: mercantilism!\n\nImagine yourself, offering the bounty of endless harvest to my glorious self, and reaping the abundant rewards I bestow upon you in kind.\n\nNow let us put that beauteous vision into practice! \n\nI will grant you a minute portion of unalloyed abundance. You, in turn, shall trade it to your fellow acolyte for one of many premium goods.", objectives = "" }
WordHunterWoW_QuestEN[91954] = { title = "Freezing Over", description = "", objectives = "" }
WordHunterWoW_QuestEN[91955] = { title = "Just Between Us", description = "The artifact we snatched from the timeline earlier was replaced with a simulacrum so none would notice the true artifact's absence.\n\nSuch a wealth of infinite energy should not be abandoned so readily. You should seek it out and reclaim it.\n\nOnce you have recovered the simulacrum you can scrap it for an embarassing sum of bronze and infinite power.", objectives = "" }
WordHunterWoW_QuestEN[91958] = { title = "Den of Nalorakk: Unforgiven", description = "Nalorakk is de Loa of War. His trial must be a battle!\n\nThere would be no greater death for an Amani than to die in combat against de Loa of War. No greater thrill than fightin' him.\n\nDoes it not make your blood pump faster and harder in your veins, hash'ura?\n\n<Zul'jarra lets out a feral howl and laughs.>\n\nCome. Meet me at Nalorakk's Prowl and we will sit at his fire and face our last trial--together.", objectives = "" }
WordHunterWoW_QuestEN[91963] = { title = "Running Amok", description = "I've heard from the other scouts about that metal--the shadowgraft. The domanaar use it to enforce their control over others.\n\nI have to imagine that there's someone holding the reins still. Maybe it's Xal'atath, or maybe someone else. Gather pieces of their shadowgraft and maybe we can make sense of who.", objectives = "" }
WordHunterWoW_QuestEN[91967] = { title = "You Know This Evil?", description = "Champion, we have a bit of a delicate situation.\n \nThe Vanguard of the Light has just informed me they have taken Magister Umbric into custody. Apparently he was trying to get close to the Sunwell.\n\nI do not have to tell you that tensions are high between my city and the Vanguard. We need Umbric to continue his research if we are to have a chance at contending with the Voidstorm.\n\nI want you to represent me in negotiating Umbric's release. Whether we like him or not, we need him.", objectives = "" }
WordHunterWoW_QuestEN[91968] = { title = "Welcome Home", description = "What a mess! Perhaps the previous owners left in a hurry. Best tidy up!\n\nThe items removed will be sent to the house chest. They can always be placed down again, if cobwebs are your thing.", objectives = "" }
WordHunterWoW_QuestEN[91969] = { title = "Time to Decorate", description = "Now that we've got this place tidied up, let's decorate!\n\nThe community has chipped in with donations to make sure you have plenty of options to work with.\n\nLet's have a look!", objectives = "" }
WordHunterWoW_QuestEN[91970] = { title = "WANTED: Gelatonius", description = "Are you ready to test yourself against a true foe? In the center of the Gloom Mire is Gelatonius, a fungal giant of enormous proportions. \n\nKill him, if you think you can. I'm willing to be impressed, and to pay handsomely for this task.", objectives = "" }
WordHunterWoW_QuestEN[91971] = { title = "Hitting the Hammer", description = "The Twilight Hammer is dirtying up the ruins of Zeb'tala. Clean up the area and bring back some of their personal tokens. One never knows what curiosities may appeal to those vying for relevancy.\n\nThose mindless cultists may stomp around and act tough, but you will make quick work of them.", objectives = "" }
WordHunterWoW_QuestEN[91972] = { title = "Hold the Watch", description = "There is still a lot of friction on the border with Zul'Aman, but we must hold the watch on all fronts.\n\nCheck in with Bloodguard Nelric at the Thalassian Pass. It is rumored to be one of the most uneventful posts. I am certain he would appreciate a reprieve, if only for a few moments.\n\nStay alert, {name}!", objectives = "" }
WordHunterWoW_QuestEN[91973] = { title = "Naga Blades", description = "It seems the locals currently find great appeal in naga blades--the brinier the better. On our southwestern shore, you will find the Daggerspine naga.\n\nThey have these grungy, barnacle-encrusted scimitars that would perfectly fit the bill.\n\nGo grab a few of those. They could have value in some of our upcoming discussions.", objectives = "" }
WordHunterWoW_QuestEN[91974] = { title = "Sunfire to the Blade", description = "I guess there is one benefit to being part of the courtly intrigue: one does hear things. We have this concoction of sunfire infused with the holy energy of the Blood Knights, courtesy of the court alchemists.\n\nTake this down to the Sanctum of the Moon and test it on the Twilight intruders. I look forward to hearing the results in detail.", objectives = "" }
WordHunterWoW_QuestEN[91975] = { title = "That's Our Wood", description = "It seems the lure of the lightwood continues to be a problem.\n\nWe may as well take advantage of the trolls' hard work! Collect what they have harvested. We can make use of it.\n\nWhat we do not use for weapons, we can hand over to the carvers. The nobles will clamor over lightwood decor.", objectives = "" }
WordHunterWoW_QuestEN[91976] = { title = "Lightbloom Dimmed", description = "All of this small talk makes my ears twitch. I would be so much more useful doing field work. For now, you get to do the fun part.\n\nThe creatures within the Lightbloom are getting a bit dense. I need you to get out there and lower the volume.\n\nI am sure you'll run into many options while you are out there. Take a whack at a few for me.", objectives = "" }
WordHunterWoW_QuestEN[91977] = { title = "Less Lawless", description = "The Tideborne are always running just over the legal line. They are an annoyance at best, but will push boundaries when given too much rope.\n\nThe ones in Sunsail Anchorage made the mistake of ripping off some nobles not too long ago. Maybe go smack them around a bit--remind them to respect their betters.", objectives = "" }
WordHunterWoW_QuestEN[91978] = { title = "Taxing the Tideborne", description = "Have you ever noticed, that sometimes there is benefit in letting someone think they are getting away with something? The Tideborne will continue to smuggle in plain sight, feeling clever at the taxes they're avoiding paying to Silvermoon.\n\nThis does add up, though, over time. When you have a moment, please head down to the harbor and relieve them of some of their back taxes.", objectives = "" }
WordHunterWoW_QuestEN[91979] = { title = "Chop It Down", description = "We received word there's a creature from Lightbloom Ath'Ran making trouble on the western coast. It has caused a bit of drama.\n\nHead over and resolve the issue.", objectives = "" }
WordHunterWoW_QuestEN[91980] = { title = "WANTED: Hellebora's Thorn", description = "See that huge creature over that way? That's Hellebora. She's set herself up too close to the road and we're concerned she's going to wander out of the mire and become even more of a threat. \n\nDeal with her, if you can, and bring me back one of her thorns as proof of your hunt.", objectives = "" }
WordHunterWoW_QuestEN[91982] = { title = "WANTED: Toadshade's Petals", description = "The three-headed hydra, Hellabora, has been causing havoc in the lower end of Gloom Mire.\n\nGive her a good pruning and bring me back her petals as proof.", objectives = "" }
WordHunterWoW_QuestEN[91983] = { title = "Lovely Plumage", description = "The beautiful members of the Silvermoon Court do so love their colorful embellishments.\n\nFor this, we can stock up while doing a good deed! Head over to Thuron's Livery and pick up some of the brightly colored feathers shed from the hawkstriders in training.\n\nVaelith gets clean up service and we get the lovely plumage.", objectives = "" }
WordHunterWoW_QuestEN[91984] = { title = "Sungrub Silk", description = "Oh, {name}, have you ever visited the Solaarian Sunbath? If not, it's highly recommended.\n\nThe sungrubs that wander nearby have a precious silk from which amazing fabric can be made. Solwin Brightstitch is reputed to be masterful in this, with his sartorial magic.\n\nThe raw materials are often sought out to have him create unique and personalized goods from scratch. Bring us some of that lovely silk. It will provide a soft cushion when faced with harder discussions.", objectives = "" }
WordHunterWoW_QuestEN[91985] = { title = "Windrunner Memorabilia", description = "The nobles do so love the unusual. Take a look around Windrunner Village. There are sure to be some interesting mementos still tucked away there.\n\nI will find an advantageous home for the pieces you bring back.", objectives = "" }
WordHunterWoW_QuestEN[91986] = { title = "Put a Little Snap in Their Step", description = "Those naga are, as ever, being a beachfront nuisance. Do they not understand that is a prime location?\n\nWe may not be able to reliably drive them off, but a little mischief would not be untoward.\n\nI found this tune that drives the snapdragons mad. They will just attack whoever is nearby. Take this and give it a shot!", objectives = "" }
WordHunterWoW_QuestEN[91987] = { title = "Potted Lashers", description = "It seems some of the nobles are botany-curious where the Lightbloom is concerned. They seek the exotic to adorn their windowsills and lurk in the dangerous section of their greenhouses.\n\nThat's where you come in, {name}!\n\nGo harvest those small and pernicious plants. Their bulbs will be the best for planting.", objectives = "" }
WordHunterWoW_QuestEN[91988] = { title = "Brightwing Conservation", description = "The conservators at Brightwing Estate have a mischievous young dragonhawk named Cerul that likes to run away whenever their backs are turned. He doesn't go far, but it has become a game for him to get them to chase him.\n\nTake this delicious treat with you and use it to lure him back home.", objectives = "" }
WordHunterWoW_QuestEN[91989] = { title = "Ghostland Peppers", description = "The delicate blue ghostland peppers may not look like much, but they have a mean burn. Many nobles won't admit it, but they are quite popular in the noble games of \"Truth or Challenge.\"\n\nPlease procure a few for me. I like to watch them sweat.", objectives = "" }
WordHunterWoW_QuestEN[91990] = { title = "Sunset to Sea", description = "Naga have set up camp on the Sunset Strand. The sunset slugs that called it home are distraught and seem unsure what to do. This little tune will remind them of their home.\n\nGo inspire them to seek the freedom of the open sea.", objectives = "" }
WordHunterWoW_QuestEN[91991] = { title = "A Little Errand", description = "When conversations get tense, it can be challenging to keep words flowing in a productive way. At times like these, I find a little social lubrication is in order.\n\nSwing over to Goldenmist Village and pick up a cask of Vintner's Golden. It's proven to have a euphoric side effect that can be quite helpful.", objectives = "" }
WordHunterWoW_QuestEN[91992] = { title = "Where Has the Wine Gone?", description = "I entrusted one of my apprentices with the delivery of several cases of particularly expensive wine. He was to bring them here from my private storage, but he has not yet arrived.\n\nI should hate to ask you to retrieve him, but I cannot stress enough how expensive those bottles are.\n\nPlease see if you can locate him and my delivery. He should have been traveling from the north to arrive here.", objectives = "" }
WordHunterWoW_QuestEN[91993] = { title = "Diminutive Demand", description = "Keeping preciously small animals as pets is a popular pastime among the nobility. The more unconventional the animal, often obtained through magic, the more of a conversation piece it is.\n\nI have enchanted this wand with the appropriate shrinking spell. Use it on some of the colorful toads out near the ponds and bring them back here. The nobles will find them delightful.\n\nNaturally, the toads may not take kindly to the enchantment. But I trust you can handle that, should it occur.", objectives = "" }
WordHunterWoW_QuestEN[91994] = { title = "Pyrepetal Purposes", description = "Lord Saltheril, that old lynx, has put me in a bit of a bind.\n\nHe has requested a grand fireworks display to accompany tonight's dinner service, but we are dreadfully low on pyrepetal dust. It is an herb native to Eversong, highly flammable and quite dazzling when set aflame by pyromancy.\n\nCould you help us replenish our stores? We mostly harvest it from the woods near Scintilas Falls.", objectives = "" }
WordHunterWoW_QuestEN[91995] = { title = "What Horrible Magic", description = "Have you seen the encampments the naga have been constructing along our coast? Dreadful business.\n\nNot only do they menace our ships and disrupt our trade routes, but they might pose a real threat to Eversong's inland settlements if allowed to continue operations unchecked.\n\nTheir arcanists are particularly dangerous. Dispose of them and our guests will be in your debt.", objectives = "" }
WordHunterWoW_QuestEN[91996] = { title = "Fit for a Magister", description = "Battle prowess and magical skill are important, of course, but one cannot deny the power of appearances. A well-dressed army instills far more faith than one bedecked in rags.\n\nFortunately, a fine set of robes can be both flattering and functional. The mana silk produced at the North Sanctum can be woven into robes that deepen and intensify our magical reserves.\n\nBe a dear and gather some for us, would you? My wardrobe could use a seasonal refreshment.", objectives = "" }
WordHunterWoW_QuestEN[91997] = { title = "Power Clean", description = "The festivities have been wonderfully entertaining, which means the nobles have been leaving a bit of a mess around the estate. Lord Saltheril's servants have been keeping up with the cleaning, but the Magisters could lend a hand.\n\nEnchanting a few brooms to sweep the pavilion should be an easy but impressive feat.\n\nI was informed that an arcanist was employing the same tactic over at Farstrider Hold. Go retrieve some of his brooms and I will have them re-enchanted here.", objectives = "" }
WordHunterWoW_QuestEN[91998] = { title = "WANTED: Muckmire's Choking Vines", description = "Deep within the swamp is a creature of mud, leaves, and rage. His vines choke the life out of any who come near, and this dangerous creature cannot be allowed to live.\n\nDefeat Muckmire and bring me back his vines as proof of the deed.", objectives = "" }
WordHunterWoW_QuestEN[91999] = { title = "A Bit of Bloodthistle", description = "You know, I bring Saltheril a lot of \"imported\" wine, but one of the first things I started supplying him with was bloodthistle. It's an herb that only grows around Eversong. It's got a smooth bite to it, sort of like mana. Nice and classy. His parties really go through the stuff.\n\nI took a look and I don't think he has enough to last this whole thing. We should get some more.\n\nThe best stuff grows over by the West Sanctum. Grab as much as you can carry. Trust me--it'll go fast.", objectives = "" }
WordHunterWoW_QuestEN[92000] = { title = "Bring the Ruckus", description = "This place is pretty fun so far, despite all the dry political talk. I know Saltheril is trying to get the nobles to buy up war bonds, but we could really use some more energy in here. If the nobles are all asleep, no one's buying anything.\n\nTell you what. Go invite some of my friends. They hang out under the bridge right outside of Silvermoon's gates.\n\nIf anyone can bring some energy to the soiree, it's us.", objectives = "" }
WordHunterWoW_QuestEN[92001] = { title = "One Smuggler to Another", description = "The whole point of this deal is showing the nobles what we bring to the table, both for Silvermoon and for them personally.\n\nThese other groups bring strength, power, and really nice armor. What we bring is resources: getting the sin'dorei what they need, when they need it, with no questions asked.\n\nI heard some folks over at Sunsail Anchorage have been trying out the same business, but they're putting gold in the wrong pockets. Swipe their stock and bring it here.", objectives = "" }
WordHunterWoW_QuestEN[92002] = { title = "Dangerous Showpieces", description = "You'd be surprised at the money you can make off of weapons. No, not the kind you're meant to use--the kind you stick up on the wall and have conversations about.\n\nUsually those weapons are expensive, or dangerous, or otherwise hard to get your hands on. The more rare and exclusive, the better.\n\nThe weapons those Twilight cultists are carrying around should sell pretty well, especially to buyers with edgier tastes. If you happen to come across any, I'll gladly take them off your hands.", objectives = "" }
WordHunterWoW_QuestEN[92003] = { title = "Artisanal Replicas", description = "Don't let the austere demeanor fool you. Nobles are just as susceptible to flashy party favors as the rest of us.\n\nI had my people bring over a batch of Felo'melorn replicas. They look great on display, and even better--they're enchanted. Swing them around and they leave a trail of fire.\n\nI haven't sold an enchanted batch before, so I'd like to do some testing before I hand them out. Saltheril wouldn't be too happy if I burned a guest to a crisp.\n\nWanna take one of the replicas for a test run?", objectives = "" }
WordHunterWoW_QuestEN[92004] = { title = "Shady Dealings", description = "I feel like I just got here and I'm already fresh out of half the poisons I brought.\n\nWhat? Don't look at me like that. Nobles are some of my top customers for poisons. Quieter than magic and cleaner than blades.\n\nI need to restock. The frogs way down in the south produce a poisonous slime that I can bottle without much fuss. Bring some of it to me and I'll get you a cut of the earnings.", objectives = "" }
WordHunterWoW_QuestEN[92005] = { title = "Throw the Dice", description = "We've been making friends with some of the guests by teaching them how to play dice. It's a nice way to draw people out of the crowd and get them in a quieter space where you can talk privately.\n\nI wasn't expecting so much interest, to be honest. We're running out of dice sets.\n\nI can carve some more, but I'll need materials. Usually teeth or bone are good picks. Actually, the fangs from those naga along the coast would be perfect. Now that's a conversation starter!", objectives = "" }
WordHunterWoW_QuestEN[92006] = { title = "We Need a Refill", description = "I talked to some of the servants earlier and it sounds like the casks are running low. That's a recipe for disaster at an event like this.\n\nFortunately, I've got a lot of contacts across Eversong who can help us restock.\n\nI need to stay here and play politics, but could you head over to Tranquillien and grab a few bottles? I'll give you a list.", objectives = "" }
WordHunterWoW_QuestEN[92007] = { title = "Begged, Borrowed, or Stolen", description = "The oldest trick in the book is to create a problem on purpose, solve it yourself, and look like the hero.\n\nOne of the nobles just got word that some prized valuable was stolen from their estate while they were occupied here. It just so happens I might have put one of their servants up to it.\n\nGo talk to a man named Seridis over at the livery. He'll hand over the valuable to you, then you'll come back here and pretend you valiantly subdued the thief and retrieved the item.\n\nEveryone's happy.", objectives = "" }
WordHunterWoW_QuestEN[92010] = { title = "WANTED: Slewstalk's Stalks", description = "Not far from here, Slewstalk lurks in the shallows. This creature has developed a taste for flesh and bones, and it won't be long until she wanders out of the Mire in search for warmer blooded prey.\n\nTake her out and bring me her luminescent stalks. They'll serve as proof and also make a fine centerpiece for an evening table.", objectives = "" }
WordHunterWoW_QuestEN[92012] = { title = "WANTED: Gorebarb's Pincers", description = "Gorebarb is a creature quite unlike most others who make Harandar their home. He's incredibly violent and his kind is not seen here very often. \n\nLet's see less of him. Kill him and bring me his pincers as proof of the deed.", objectives = "" }
WordHunterWoW_QuestEN[92013] = { title = "WANTED: Dionaea's Thorntusks", description = "Many thornmaws make the mire their home, but none as are vicious as Dionaea. Unlike the others, she kills merely for the joy of it, and her gluttony threatens the delicate balance of the wildlife in this area. \n\nTake her out and restore the equilibrium. Bring me back her thorntusks as proof of the deed.", objectives = "" }
WordHunterWoW_QuestEN[92021] = { title = "Graveblossom Gardening", description = "My colleague Amalthea has taken ill. She requires a specialized poultice of sorts in order to ease the symptoms. I would forage for the plants myself, but the local fauna have grown so testy as of late!\n\nWhile you are out and about, could you gather some graveblossoms for me? I'd happily make it worth your while.", objectives = "" }
WordHunterWoW_QuestEN[92022] = { title = "A Venomous Vocation", description = "My poultice requires venom samples from the local giant bat populations. Please retrieve some of those, as well. Six common vials' worth should do.\n\nDon't give me that look. They're bats. There are mad Light-plant-things to the east and a storm of voidwalkers swirling over our heads. Don't you dare give me guff about the dangers of big, fluffy bats. Now shoo. My colleague is depending on your prompt and efficient aid.", objectives = "" }
WordHunterWoW_QuestEN[92023] = { title = "Suspicious Sundries", description = "Forgive me for my failure to provide specifics, traveler. The mournbat venom and the graveblossoms were only the first of the reagents I require for my associate's medication.\n\nLuckily, the final few things I require can all be easily obtained in Goldenmist Village to the north. Be a dear and fetch these last few things for me, won't you? With these, my toil will be nearly complete.", objectives = "" }
WordHunterWoW_QuestEN[92024] = { title = "House Call", description = "That woman, that \"apothecary,\" has snared you in one of her schemes.\n\nI'd be careful around her, {class}. Rumors travel like wildfire in Eversong. And while I would never disparage a fellow artisan of Eversong without cause, I have heard enough rumors to know that your apothecary deals in more than simple herbs.\n\nTake your wine and your reagents, I suppose. But before you pass them off to your patroness, I'd recommend doing some digging--lest you find yourself wrapped up in something you come to regret.", objectives = "" }
WordHunterWoW_QuestEN[92025] = { title = "Flowers for Amalthea", description = "<The final pages of the tome detail a meeting place. Whatever Talandra Dawnsprite intends to do, she means to do it amidst the ghosts of Windrunner Spire.\n\nThe time for Talandra's ritual grows nigh.>", objectives = "" }
WordHunterWoW_QuestEN[92028] = { title = "Pardon the Interruption", description = "{name}! Glad to see you. The defenders in the fortress could use your help.\n\nOne of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on.\n\nShe needs the help of someone who can properly interrupt the robot's attacks so it can be repaired.\n\nDo you have a moment to help?", objectives = "" }
WordHunterWoW_QuestEN[92030] = { title = "A New Tradition", description = "Chon was just looking for you. You can find him at his house, serving drinks with Chen.\n\n<Lorewalker Cho laughs--a deep, warm rumble.>\n\nGo on, {name}! I won't be leaving anytime soon, that's for sure.", objectives = "" }
WordHunterWoW_QuestEN[92031] = { title = "Meet the Vandals", description = "<The Manaforge Vandals at Shadow Point are eager to see the Shadowguard and their allies removed from Manaforge Omega. It's probably a good time to pay them a visit.>", objectives = "" }
WordHunterWoW_QuestEN[92061] = { title = "Rising Storm", description = "That was an entropic wave. We felt them just before Xal'atath launched her assault on the Sunwell. \n\nChampion, you move faster than my best messengers. I need you to check in with the Vanguard commanders and see if their defenses will hold against this latest assault by Xal'atath's Devouring Host.", objectives = "" }
WordHunterWoW_QuestEN[92078] = { title = "A New Recipe!", description = "", objectives = "" }
WordHunterWoW_QuestEN[92082] = { title = "Someone Like Me", description = "", objectives = "" }
WordHunterWoW_QuestEN[92084] = { title = "Halazzi's Guile", description = "Who are these people? Where did they come from?\n\nDid dey find their way here from Numazon? How? De mist keeps you from knowin' if you are comin' or goin'.\n\nAnd where is Halazzi?\n\nI need answers... now!", objectives = "" }
WordHunterWoW_QuestEN[92104] = { title = "Broomstick Express", description = "Hmm. You look like you can ride a broom without crashin' into a chimney.\n\nHallow's End is a busy time for all kinds of deliveries. Got sweets, potions, pumpkins, haunted socks - don't ask - all goin' to the usual oddballs.\n\nTake that broom over there, fly fast to make those deliveries, and don't drop nothin'.", objectives = "" }
WordHunterWoW_QuestEN[92106] = { title = "Ignite the Skies: Northern Kalimdor", description = "Midsummer is the time to reflect and a time to tell stories by the bonfire.\n\nOne such story is the tale of the sun blossom ritual and how this offering to An'she first came to be.\n\nOur journey will take us through Northern Kalimdor, into territories beyond the lands of the shu'halo.\n\nIf you wish, take to the skies of Kalimdor and ignite the blossoms as I tell the tale.\n\nOur story begins in the Western Barrens...", objectives = "" }
WordHunterWoW_QuestEN[92136] = { title = "Infusion of Hope", description = "I hope my staff's light has been enough to uphold those at the Sunwell while we have sought these relics.\n\nTogether with those from Light's Hope, they should be a much more significant aid.\n\nLet us return there quickly.", objectives = "" }
WordHunterWoW_QuestEN[92155] = { title = "Object Exorcism", description = "I reached out to examine a console that had dark energy moving through it, but something screamed in my face. It was so unexpected.\n\nIt didn't feel like an alarm, more like something... vicious. Angry. Hungry. It almost felt like it wanted to grab me.\n\nTerrifying. And interesting!\n\nTake a look around and see what you can learn. Check for visible disturbances.", objectives = "" }
WordHunterWoW_QuestEN[92156] = { title = "It Follows Me", description = "You must listen. An evil creature attached itself to me not long ago. It followed me about, angrily hurling objects, playing tricks, and consuming anything it could.\n\nJust now, it stopped following me. It likes you now, I think.\n\nIf you feed it, it should leave you be for a time. Mark the defeated in the Sparring Grounds with this brand. It should consume them, giving us time to talk more.", objectives = "" }
WordHunterWoW_QuestEN[92157] = { title = "Ritual Activity", description = "While you were gone, we were busy.\n\nMy idea is to force the malevolent entity out into the open--out of its hiding places. Havazza gathered up items that have the entity attached to them. I don't trust her, but if she wants to lift heavy things, at least I don't have to.\n\nBy destroying the scattered things it is possessing, we will flush it out of hiding!", objectives = "" }
WordHunterWoW_QuestEN[92158] = { title = "Let It In", description = "The entity is definitely attached to you, {name}. It even imitated you. I bet it mimics the body of its main target, changing depending on what it's eating. Now that I've seen it in action, I'm confident I can make a container to hold it.\n\nYou trust me, right?\n\nJust outside of Shadow Rise, there is a clear area on the upper bluffs of Claw's Edge. I want to get it away from these objects, like that chair.\n\nBrand yourself as defeated and wait. It will come. Ambush it when you see an opening. We'll trap it!", objectives = "" }
WordHunterWoW_QuestEN[92159] = { title = "A Final Destination", description = "Havazza betrayed us and left you to clean up after her. It could have killed you. She should face the consequences of her actions.\n\nI am sure she is back to duels, revelling in her returned strength at your expense. We should start with the Shenzar Refinery area next to the Sparring Grounds.\n\nChallenge her to a real duel!", objectives = "" }
WordHunterWoW_QuestEN[92163] = { title = "The Loa of Murlocs", description = "Have you heard of de commotion comin' from Atal'Abasi? De murlocs there are gettin' riled up about somethin'.\n\nIt seems like de murlocs have summoned a loa of their own. And dis loa is rallyin' de murlocs to war.\n\nI saw it myself! Just today, lookin' down from dis cliff. De biggest murloc you've ever seen!\n\nI'm not de only one who've seen it either! But de elders say we have bigger problems. Bah!\n\nDey better not come to me when we get overrun by murlocs!", objectives = "" }
WordHunterWoW_QuestEN[92164] = { title = "Murloc Madness", description = "These murlocs have come to me, the Loa of Murlocs, to seek my protection against an evil invader.\n\nThe Deepfin have risen from the abyssal depths of the ocean. They have invaded this land and defiled its grounds!\n\nI charge you, champion, to defend this kingdom and drive the Deepfin back into the sea!\n\n<King Mrgl-Mrgl lowers his voice to a whisper.>\n\nGet rid of the invaders and maybe the natives won't need me to protect them, and I can leave!", objectives = "" }
WordHunterWoW_QuestEN[92165] = { title = "Fish Are Food, Not Friends", description = "I have heard your mrgls, my people. Your stomachs grgl in hunger!\n\nThe invaders have cut you off from the food you so desperately need to survive.\n\nI will send my champion to gather fish so you may fill your bellies once more!\n\n<King Mrgl-Mrgl lowers his voice to a whisper.>\n\nOr you can just give me fish if you have some?", objectives = "" }
WordHunterWoW_QuestEN[92166] = { title = "Following Suit", description = "My fellow murlocs! One among you was chosen to be my... my chosen!\n\nShe is destined for greatness and is my assistant... erm, priestess! Yes, priestess of the loa!\n\nYour priestess has gone missing, possibly taken by the treacherous Deepfin.\n\nTo showcase my great power, I will send my champion to find and return her to you.\n\n<King Mrgl-Mrgl lowers his voice to a whisper.>\n\nMy assistant is missing, and I'm stuck here! Find her and tell her I'm on top of the temple!", objectives = "" }
WordHunterWoW_QuestEN[92167] = { title = "There Can Be Only One", description = "I've observed the Deepfin kidnapping native murlocs and raising troll corpses as undead thralls. But they don't push further inland--they take them all back to the sea.\n\nI think they're being led by a powerful murloc who remains safely offshore, hiding from view as it accepts its minions' tribute.\n\nWe can draw it out. If you put on this murloc suit and offer tribute, it might fool the leader into showing itself.\n\nIf we eliminate the leader, we might be able to save the native murlocs!", objectives = "" }
WordHunterWoW_QuestEN[92177] = { title = "One Hero's Prey", description = "Again, we sin'dorei find our city under assault. And again, it is up to the finer minds among us to come to Silvermoon's aid.\n\nMortal anguish, it seems, is a powerful reflection of the soul. When contained and manipulated, anguish acts as a form of magic that we can wield to protect this great city.\n\nI've located a number of anguish-filled targets across Azeroth.\n\nSelect and hunt one such target, storing their anguish in this crystalline vessel. Then return to me.", objectives = "" }
WordHunterWoW_QuestEN[92178] = { title = "Practical Magic", description = "While you've been out pursuing targets, I've been developing various applications for anguish.\n\nThe power these raw emotions contain is unfathomable. For now, our applications might seem quaint, but given enough time, I'm certain my discoveries will further Silvermoon's aims.\n\nLet me show you. Take the crystalline vessel and meet me below.", objectives = "" }
WordHunterWoW_QuestEN[92179] = { title = "Dark Mending", description = "So far, anguish has been invaluable in bolstering our forces. Our weaponry and golems are all the more hardy and potent thanks to this newfound power.\n\nI've also been developing ways to shape anguish into robust enchantments that can strengthen us elves.\n\nMeet me downstairs. I will show you what I've found.", objectives = "" }
WordHunterWoW_QuestEN[92180] = { title = "Precious Jewels", description = "{name}...\n\nWhile you've been away, I've been refining our work.\n\n<He produces a jeweled ring in the palm of his hand.>\n\nSmall trinkets and jewelry that contain crystallized anguish.\n\nI've discretely gifted these to a few willing Silvermoon citizens. I wish to observe the effect of a controlled concentration of anguish over time.\n\nI've shaped the magic to lend the bearer health and strength. Seek our volunteers out and check up on them.", objectives = "" }
WordHunterWoW_QuestEN[92181] = { title = "Garden Variety Sacrifices", description = "{name}... I need you to attend to a matter in the city.\n\nI've received word from Knight Captain Solara that there's been an incident in the Gardens of Remembrance. She reports elves have begun acting out violently, causing coalesced anguish to manifest and terrorize the residents.\n\nYou can use the crystalline vessel to reclaim the coalesced anguish and soothe the elves whose minds have crumbled.\n\nSo much of the magic will weigh heavy upon you, but I'm confident you have the strength.", objectives = "" }
WordHunterWoW_QuestEN[92182] = { title = "The Sheep or the Wolf", description = "I heard word of your heroics in the garden. Silvermoon thanks you for quelling the chaos.\n\nAnd I thank you for recovering so much anguish.\n\nThe crystalline vessel may be the conduit, but the body must be robust to handle so much power... Like me, you have the strength to withstand the torrent of anguish inside you, at least for a short while.\n\nCome, let me relieve you of the burden.", objectives = "" }
WordHunterWoW_QuestEN[92185] = { title = "The Tale of the Frost Lord", description = "Midsummer is the time to reflect on the past and share stories by the fireside.\n\nOne such tale is the defeat of Frost Lord Ahune!\n\nBut this is a story you must witness for yourself so you may share it around the bonfire with others!", objectives = "" }
WordHunterWoW_QuestEN[92319] = { title = "A Favor to Axe", description = "Kurdran and I spent twenty years in Outland on the other side of the Dark Portal, after we'd pushed the Horde back with Khadgar, Turalyon, and Alleria.\n\nThere were some good times, but any day I don't wake up in Honor Hold is already a good day.\n\nThat whole time, Kurdran led our scouts with his gryphon, Sky'ree. And on his way out of Honor Hold, he would fly low and fast, dodging everything the orcs threw at him. I think it'd be hilarious if you could go find him some mementos!", objectives = "" }
WordHunterWoW_QuestEN[92320] = { title = "Still Behind Enemy Portals", description = "In our reminiscing of past events, we were reminded of an artifact that we did not recover during our war with the Burning Legion.\n\nThis item is a vessel of great evil, and should not stay in the clutches of the remaining demonic forces.\n\nTo reach this item, we must journey to the Broken Shore where Tehd has a portal he has repurposed for our use. Will you join us on this hunt?", objectives = "" }
WordHunterWoW_QuestEN[92321] = { title = "A Frostbitten Tally", description = "Tarenar and I heard stories about the invasion of Icecrown Citadel from all the way out in the Plaguelands.\n\nBut he's got it all wrong!\n\nThe elf thinks there were more Ebon Blade commanders than Argent Crusade in the Ashen Verdict. He's completely daft. Obviously there were more paladins!\n\nWould you go poke around Icecrown Citadel and find me some proof? I'm sick of arguing with him!", objectives = "" }
WordHunterWoW_QuestEN[92322] = { title = "Timear Foresees a Proof of Demise!", description = "Hello, {name}. Do you have a moment?\n\nThere's something important I lost during the assault on the Isle of Thunder: a pocket watch gifted to me by my old friend, Archmage Timear. Yes, that Timear... the one that can foresee the future. He told me this day would come and that you would assist me.\n\nThe watch was taken by the Council of Elders, specifically by High Priestess Mar'li. If you would go to the island and retrieve it from the Throne of Thunder, and we both know you will, I can get you there.", objectives = "" }
WordHunterWoW_QuestEN[92323] = { title = "Where the Fire Once Burned", description = "Hard to believe, isn't it? Horde and Alliance, same room, no stabbing.\n\nI was reminiscing about my days in the Firelands, gathering luciferns. They had such a distinctive smell... somewhere between smoke and something long dead. It's been a while, and I almost miss it.\n\nGrab a few for Zen'tabra and me, will you? She deserves the full experience.", objectives = "" }
WordHunterWoW_QuestEN[92324] = { title = "Uncrowned's Cold Case", description = "We are lucky the Uncrowned survived, and its archives, thanks to Taoshi. We've been reading them...\n\nHave you heard of the great highborne city Dire Maul? The Uncrowned kept tabs on the dangerous prince, Tortheldrin, but since he died, the case was shelved.\n\nThese notes say there might be objects of interest in the city ruins, with a notable mention of Nostro's Compendium of Dragon Slaying. That book was retrieved some time ago, but few know that several chapters were missing.\n\nLet's reopen the case.", objectives = "" }
WordHunterWoW_QuestEN[92325] = { title = "Hellscream's Heritage", description = "My sister Krenna was once a Conqueror in the Horde's armies. Ruthless. Brutal. Some said a tyrant. But she was different when we were young. Scared, but always kind to me. Warm to those she would let in. Did power change her? \n\nAnd if it changed her into a tyrant, did it change Garrosh Hellscream as well? I know who Krenna was. I do not know who Garrosh was. \n\nTravel to Nagrand and find out.", objectives = "" }
WordHunterWoW_QuestEN[92326] = { title = "The Fragrance of the Dunes", description = "I miss the smell of the desert. It is the fragrance of freedom in a wild land. I would love to refresh that scent memory.\n\nWhile you're there, grab something from the caravans. This place could use some nomad personality.\n\nMaybe hop over to Shatterstone Harbor and get something for the big guy. Maybe an anchor? That would be perfect! Imagine watching him lug that around.", objectives = "" }
WordHunterWoW_QuestEN[92327] = { title = "A Generational Moment", description = "It's always good to see someone with your history continue to speak to us old dogs, {name}.\n\nEitrigg and I have been talking about legacy recently. Did you know we both fought with the Valarjar against the Legion? Interesting how long histories can intertwine.\n\nBut our real legacy is our children. I wonder if you would have time to check in with them both. While you're there, make sure they're keeping their skills sharp.", objectives = "" }
WordHunterWoW_QuestEN[92331] = { title = "Turbo-Boost: Trade Must Flow", description = "<The Trust is under pressure from the cartels to keep markets open. We seek associates capable of removing certain... obstacles. Cartel So has been authorized to distribute substantial riches if you are successful.\n\nComplete the task, and collect a special reward from Fixer So'kir outside of the Dornogal Treasury. Parties shall remain unbound by any implied oaths arising in the course of trade. Uniform Broker Code standard terms apply.>", objectives = "" }
WordHunterWoW_QuestEN[92365] = { title = "Creating Defenses", description = "Deploying defenses is crucial to safeguarding operation of the Singularity Anchor. I need to ensure you fully understand the process.\n\nFirst, collect the Stormarion cores I have in storage. Then, activate the defensive positions, and finally, choose and deploy one defense at each position.\n\nWhen you have completed that I can entrust you with further Stormarion Cores to use as you see fit.", objectives = "" }
WordHunterWoW_QuestEN[92386] = { title = "A Handful of Voidlight Marl", description = "", objectives = "" }
WordHunterWoW_QuestEN[92387] = { title = "A Cluster of Voidlight Marl", description = "", objectives = "" }
WordHunterWoW_QuestEN[92388] = { title = "A Trove of Voidlight Marl", description = "", objectives = "" }
WordHunterWoW_QuestEN[92390] = { title = "Risk for Research", description = "There is some peculiar activity in Shadow Rise to the northeast. Supposedly it is cursed! The Shadowguard usually have a heavy presence there, but I have word that they are abandoning the site.\n\nI want to find out the truth of why they'd leave. Would you accompany me?", objectives = "" }
WordHunterWoW_QuestEN[92396] = { title = "Calling in the Cavalry", description = "The wards on the runestones weaken by the hour. Without fresh arcane-charged crystals, the Lightbloom will gain ground.\n\nI know this is not your burden to bear as you have much more to handle, but if you could see these supplies delivered, it would mean more than I can say.\n\nWill you lend your strength to this task, for the sake of all who call this place home?", objectives = "" }
WordHunterWoW_QuestEN[92397] = { title = "Dawnstar Defense", description = "The nearby runestone has gone dark, and the Lightbloom is on its way. I can't hold this ground alone. Help me set the weapons, line up the potions, and get our supplies in order.\n\nWe'll meet that growth with discipline and precision and send it back in pieces.", objectives = "" }
WordHunterWoW_QuestEN[92398] = { title = "And Then They Came", description = "Brace yourself--the time is upon us!\n\nHold the line and keep them from reaching the runestone at all costs. I'll focus on restoring its power, but I need you to protect me and everyone here.\n\nAre you ready?", objectives = "" }
WordHunterWoW_QuestEN[92402] = { title = "Magical Touch", description = "Oh hey, just the person I was looking for!\n\nSome of your neighbors are looking to get into enchanting. They aren't quite ready for prime time yet, but I have an idea to get them started.\n\nIt looks like there's an area in your neighborhood that has slight magical energy. Can you take this locator and find some crystals for them?\n\nThey only need to be slightly magical. We don't want them to cause an accident!", objectives = "" }
WordHunterWoW_QuestEN[92405] = { title = "Meet Arator", description = "Greetings, champion. I have an urgent message for you from Arator. He asks that you join him and his aunt Vereesa on Oztan Isle, off the coast to the west.", objectives = "" }
WordHunterWoW_QuestEN[92407] = { title = "Hidey-Hole", description = "When Xal'atath departed she left behind a large number of anomalies, small pocket dimensions where enemies can hide. As Romuul calls them, \"Hidey-Holes\".\n\nThe Artificer has rigged up a device that should do the job.\n\nWe need to close these Hidey-Holes and flush out any enemies lurking inside.", objectives = "" }
WordHunterWoW_QuestEN[92408] = { title = "Material Gains", description = "How on Azeroth one of these encroaching paladins managed to come by such an exquisite example of Thalassian tailoring is beyond me. But it would be negligent of me to turn down this opportunity.\n\nThe materials we need are far more bespoke than I keep in my shop, however. We'll need to source our manasilk directly. Fortunately, it isn't far--just outside the city gates.\n\nAnd at least there we'll be safe from these dabblers.", objectives = "" }
WordHunterWoW_QuestEN[92417] = { title = "Farm to Table", description = "Hey, it's {name}!\n\nI'm in a bit of a pickle here. I'm making food for everyone, but underestimated how many people would turn up!\n\nI can whip up a quick stew and the local farmers said I could use their produce, but the other dishes are at a vital point, I can't leave them unattended!\n\nCould you gather some ripe ingredients, and bring them back?", objectives = "" }
WordHunterWoW_QuestEN[92418] = { title = "Abundance", description = "", objectives = "" }
WordHunterWoW_QuestEN[92420] = { title = "Ignite the Skies: Southern Kalimdor", description = "Each year, as tribes from southern and central Kalimdor journeyed to Stonetalon to spend the summer season, the rite of the sun blossoms became common practice.\n\nMany saw it as a way to give back to An'she, who worked tirelessly during this long season.\n\nThe rite became especially important towards the end of Midsummer, as the southern tribes journeyed back home.\n\nIf you're up for another journey, take to the skies once more, my friend, and listen close...", objectives = "" }
WordHunterWoW_QuestEN[92429] = { title = "Alternative Skinning", description = "Hey there!\n\nI'm working on a new method for making leather, but without harming animals.\n\nI just need small samples, fur, saliva, that sort of thing. Nothing invasive.\n\nI have this handy device that should help out!", objectives = "" }
WordHunterWoW_QuestEN[92430] = { title = "Embracing the Infinite Chaos", description = "{name}, make haste to the Infinite Bazaar. I believe you are ready for a new kind of experiment.", objectives = "" }
WordHunterWoW_QuestEN[92435] = { title = "Ignite the Skies: Orgrimmar", description = "Midsummer is a time to reflect on the past and future. As old traditions fade, new traditions are born. \n\nOne old tradition, practiced long ago, involved the offering of sun blossoms to An'she. As summer winds took them upwards, the blossoms would burn bright blue and orange.\n\nBut faded traditions need not remain lost.\n\n\nWill you take to the skies to ignite the sun blossoms and help rekindle this old tradition?", objectives = "" }
WordHunterWoW_QuestEN[92437] = { title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nStone laid by lost hands.\nBridging the mountain runoff.\nLook where lilies listen.\n\nGood luck!", objectives = "" }
WordHunterWoW_QuestEN[92439] = { title = "Infinite Research: Combat Studies, Felrunner", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a study of fighting the Legion with their own power, so focus on using demonic fel energy to slay your foes.\n\nAnd remember, this is for the greater good.", objectives = "" }
WordHunterWoW_QuestEN[92440] = { title = "Infinite Research: Combat Studies, Stormrunner", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a study of your attunement to the storm, so focus on fighting opponents by turning the tides quite literally.\n\nAnd remember, this is for the greater good.", objectives = "" }
WordHunterWoW_QuestEN[92441] = { title = "Infinite Research: Combat Studies, Magerunner", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a study of your attunement to the arcane, so focus on fighting opponents with powerful magic.\n\nAnd remember, this is for the greater good.", objectives = "" }
WordHunterWoW_QuestEN[92442] = { title = "Infinite Research: Combat Studies, Lightrunner", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a study of your attunement to the Light, so focus on wielding holy justice to smite your enemies.\n\nAnd remember, this is for the greater good.", objectives = "" }
WordHunterWoW_QuestEN[92443] = { title = "Reverse Herb Farming", description = "Hey there, I was collecting herbs around your neighborhood, and I kind of zoned out, and lost track of time. It's so pretty here!\n\nI think I may have picked too many herbs. I have an enchanted watering can that should help new ones grow back in, if you have the time to help them grow back?", objectives = "" }
WordHunterWoW_QuestEN[92445] = { title = "Smelting for Two", description = "People keep coming up to me and asking me about mining, I'm not a miner, I'm a smelter!\n\nI'm looking to teach some people about smelting, but I've been struggling with getting a crowd.\n\nCould you help me out while I talk you through smelting?", objectives = "" }
WordHunterWoW_QuestEN[92448] = { title = "Where Dust Dances", description = "You find a faintly glowing powder in your hands after catching the moth. It is fine, dry, and oddly luminous. \nIt doesn't hum or shift, but it catches the light in a way that feels deliberate.\n\nYou recall Mothkeeper Wew'tam is known to have a particular interest in the moths that reside in Harandar.\n\nPerhaps this dust would be of interest.", objectives = "" }
WordHunterWoW_QuestEN[92450] = { title = "Growing Up is Hard", description = "Oh, hi! You're new. I'm Ani. Dis is Jynx.\n\nHave you been to de waterfall yet? All de kids dare each other to jump off, but I'm too scared.\n\nDo you want to see it?", objectives = "" }
WordHunterWoW_QuestEN[92451] = { title = "I Think I Can", description = "Yeah, it's pretty far down.\n\nBut if I don't jump, dey'll make fun of me. Maybe if you cheer me on, I can do it?", objectives = "" }
WordHunterWoW_QuestEN[92452] = { title = "Not According to Plan", description = "<Ani's trinket bag sits in the soft mud of the river bank, but her trinkets are nowhere to be found.\n\nIf you're lucky, you may be able to follow her trail.>", objectives = "" }
WordHunterWoW_QuestEN[92453] = { title = "Fearless", description = "Those lizards were waitin' at de bottom and dragged me off!\n\nDid you find my toys and stuff? I tried droppin' dem so someone could find me. I can't believe dat worked!\n\nI think you scared dem off. It should be safe enough for Jynx to help me out of here.", objectives = "" }
WordHunterWoW_QuestEN[92455] = { title = "Specter Inspector", description = "Every Hallow's End, same thing... spirits crawl outta the dirt like they forgot they're dead.\n\nWe tried smashin'. We tried burnin'. Didn't work. Now we got these new tools some goblin made that'll take care of those ghosts.\n\nGear up and get goin'! Get enough of em to clear the streats for now, but don't go gettin' lazy. They always seem to find a way back.", objectives = "" }
WordHunterWoW_QuestEN[92492] = { title = "Honorin' de Sacrifice", description = "It's de hash'ura again. You willin' to help me, or does Zul'jarra got you on a short leash?\n\nNo? Then I got a job for you. One of my guards, Idago, was killed in de massacre at Revantusk Sedge. I wish to honor him with funeral rites. We Revantusk burn de bodies of our dead. But we don't have Idago's body.\n\nSo, I'm goin' back to de sedge to retrieve somethin' of his. We'll burn dat instead.\n\nMy honor guard Pel'na will not go and says it is too dangerous, but you'll keep me safe, won'tcha?", objectives = "" }
WordHunterWoW_QuestEN[92493] = { title = "What Remains of Idago", description = "Idago was my most trusted guard. He was a mentor to me for as long as I remember. I never thought dat he would be taken from me so soon--and then de Twilight's Blade attacked us without warnin'.\n\nIdago is de one that saved me from de village. He left his spear and his banner behind. I also left a note he gave me in case he...\n\nBring me those items. With dem, we can honor his strength and his loyalty--and send his spirit on.", objectives = "" }
WordHunterWoW_QuestEN[92495] = { title = "Disruptin' de Blade", description = "Look at what these cultists did to Revantusk Sedge!\n\nDis was once a place of peace... dis was our home. An' dey are desecrating it.\n\nI know we're here to retrieve Idago's things, but I won't be bothered if you take up arms against de Twilight's Blade.\n\nPut dem in de ground. Show dem de ferocity of de bear.", objectives = "" }
WordHunterWoW_QuestEN[92496] = { title = "Spears Against de Shadow", description = "Idago's still alive, {name}!\n\nI saw him dragged up into de crypt, bound in magic runes. \n\nDe cultists say dey are takin' him to some Deathchanter Mish'mosh. Dis cultist must be behind the death and destruction brought to our sedge.\n\nFor the honor of the people we lost, root this snake out of our home!", objectives = "" }
WordHunterWoW_QuestEN[92497] = { title = "Simply Magical", description = "Who... Who are you? Who sent you? Lilaju?\n\nDe cultists massacred our village. I stayed behind to make sure everyone got out.\n\nBut de cultists captured me and now dey say dey got somethin' extra special for Idago. I'd rather not find out what.\n\nDis magic holdin' me here is amateur work. De spells to release de bindings are sure to be in de magical tomes de cultists brought here.\n\nFind de tomes and rip some pages out. Then we can piece together de right words to release me.", objectives = "" }
WordHunterWoW_QuestEN[92498] = { title = "Sugar Run", description = "Ahh, Hallow's End. The perfect time for spooky stories, glowing pumpkins, and sweet, sweet candy!\n\nBut this year, I want to craft something truly unforgettable. A delicious range of candy inspired from regions across Azeroth!\n\nFor that, I've enlisted some help. A certain... eccentric culinary genius. You may know him. I've sent him off to Drustvar in search of haunted recipes that are sure to thrill everyone.\n\nFind him and bring back some of those cursed candies.", objectives = "" }
WordHunterWoW_QuestEN[92499] = { title = "The Wisest Leaders Follow", description = "Idago reminded me dat my first obligation is to my tribe. I missed him dearly, but it was not right for me to put my own life--or yours--at risk to find him.\n\nPel'na tried to tell me this. I would not listen.\n\nI must be a model for my people. I will allow de bear loa to guide my direction. Sometimes we must sacrifice de things we hold dear.\n\nNalorakk grant me strength and resilience.", objectives = "" }
WordHunterWoW_QuestEN[92503] = { title = "Ignite the Skies: Northern Eastern Kingdoms", description = "Have you heard the tale of the wildsages and their summer star?\n\nNo? Well, you're in for quite the treat!\n\nThis story will take you on a journey that follows the path the Wildhammer elders once travelled many moons ago.\n\nTake to the skies and ignite the blossom lights as I tell the tale.\n\nOur journey begins here in the hills of Loch Modan...", objectives = "" }
WordHunterWoW_QuestEN[92504] = { title = "Ignite the Skies: Southern Eastern Kingdoms", description = "The fire festival is a time for people to come together and share stories around the fire.\n\nOne such tale tells of a celebration of Midsummer and the elemental chaos it wrought for the humans of Stormwind.\n\nOur story will take us over the skies of the surrounding regions into lands now scarred by flame and ash.\n\nTake to the skies and ignite the blossom lights as I tell you the story.\n\nIt begins in the Burning Steppes...", objectives = "" }
WordHunterWoW_QuestEN[92505] = { title = "Truth of the Past", description = "Thanks for freeing me from those ethereal cages in the Ethereum Overcroft. The Void is powerful here in ways we're only beginning to understand, and that danger brings new opportunities.\n\nIf you remember, my quest to combine the power of the Void with the strength of the Illidari has not changed.\n\nBacking Adarus was a mistake, but a necessary one to progress. And now I've found a willing teacher in Allari. I ask for your help again, {name}. Help me find the strength to protect my people.", objectives = "" }
WordHunterWoW_QuestEN[92506] = { title = "The Soul Price", description = "Argus.\n\nOriginally the homeworld of the Eredar, now the stronghold for the Burning Legion. Years ago, Illidan used the Seal of Argus to open the way here. And he was met by one of the naaru who delivered a dire message.\n\nTo understand the Illidari's connection to the Void, you must see what Illidan saw when he arrived. Hostile spirits in the area should provide the necessary power for our needs.\n\nDefeat them to release their essence, and with their sacrifice we will peer into the past.", objectives = "" }
WordHunterWoW_QuestEN[92507] = { title = "A More Potent Foe", description = "We have what we need.\n\nPrepare yourself to see Illidan's confrontation with the naaru so many years ago.", objectives = "" }
WordHunterWoW_QuestEN[92508] = { title = "The Mark of Sacrifice", description = "The tattoos that mark our flesh are more than just ink. They're a promise inscribed across our flesh.\n\nThe promise that we will hold back the dark and the infernal with our very bodies. That our lifeblood is a currency used to purchase Azeroth's future.\n\nSurprised? We are not simply rage and defiance manifest, although we are also that.\n\nHelp Leona collect the vitae of the void creatures at Nexus-Point Antius. We'll use it to inscribe her tattoos, affirming the vow she makes to protect her people.", objectives = "" }
WordHunterWoW_QuestEN[92509] = { title = "One Cruel Implement", description = "Voidstorm is a world of apex creatures. One in particular, the ultradon, stands above others in its strength and ferocity.\n\nBut make no mistake, {name}. We demon hunters are the true apex predators wherever we go, because we are willing to go to any length in order to dominate. I see no better creature to harvest an implement in which to inscribe Leona's tattoos.\n\nHead to Nexus-Point Antius with Leona. Defeat as many ultradons as it takes to find the perfect implement.", objectives = "" }
WordHunterWoW_QuestEN[92510] = { title = "Dark Infusion", description = "The branding ritual we're about to perform is adapted from what demon hunters go through on the Fel Hammer. But given Leona's unique nature and the experimental substitution of Void energy for fel, there's considerable risk here. Even more so than usual.\n\nLeona will be vulnerable during this process, as will I. We've found a secluded area to perform it, but we'll need your protection once we start.", objectives = "" }
WordHunterWoW_QuestEN[92511] = { title = "Event Horizon", description = "It may not surprise you to know that the stabilization of portal entry points is something I'm quite familiar with.\n\nIf Leona lives, and I believe she does, she'll need beacons to help triangulate her exit point. Take these beacons, set them up where I've marked on your map, and return here.\n\nIf Leona is alive, she should be able to use these beacons to identify and stabilize her exit.\n\nIf she isn't--\n\n<Umbric pushes the thought away.>\n\nLet's focus on the task at hand for now.", objectives = "" }
WordHunterWoW_QuestEN[92512] = { title = "Devourer", description = "I'm not sure where I was when I stepped through that portal, {name}. Somewhere in between, Void energy surrounding and suffusing me.\n\nWithout Umbric, I wouldn't have made it back. I feel different now, but I don't think this is over until we confront that domanaar.\n\nWill you meet us at the Voidspire?", objectives = "" }
WordHunterWoW_QuestEN[92520] = { title = "Wake of the Darkwell", description = "The Sunwell--no... the Darkwell is overrun. \n\nVoid-spawned creatures swarm the regions where our greatest champions of the Light held their ground to the very last.\n\nChampion, can you survey Quel'Danas? Find any survivors? If you tag them with these tokens, our mages here will be able to teleport the individuals back. We must try to save as many as we can.", objectives = "" }
WordHunterWoW_QuestEN[92523] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[92531] = { title = "The Medicine Loa's Shrine", description = "Everyone has their own path toward understanding, even Akutu--though he has yet to set foot on it, unfortunately.\n\nMy shrine was once a place of discovery and understanding for the Amani. Please take word to them that I welcome their return.\n\nThe ghosts will calm in time.", objectives = "" }
WordHunterWoW_QuestEN[92535] = { title = "Witchbane Truffles", description = "Truffles are simple enough to find if you've got a strong nose. Luckily, I can lend you one!", objectives = "" }
WordHunterWoW_QuestEN[92536] = { title = "Bewitched Berry Bites", description = "My favorite! Bewitched berries are quite tricky. There's no telling what will happen when you pick them!", objectives = "" }
WordHunterWoW_QuestEN[92537] = { title = "Hexed Honeycombs", description = "Quite the risk taker! Honeycombs are delicious, but can be a pain to retrieve - literally! Don't expect a warm welcome from the habitants of the hives that you will be extracting honeycombs from.", objectives = "" }
WordHunterWoW_QuestEN[92554] = { title = "Addition of Anguish", description = "?", objectives = "" }
WordHunterWoW_QuestEN[92555] = { title = "Honor the Flame", description = "The time of Dawnsummer Festal has long been a cherished season for our people.\n\nEven during the years under the cold grasp of the Ghostlands, the people of Tranquillien strived to maintain this ancient celebration and bring a little light to these once-cold lands.\n\nNow, warmth yourself by the bonfire and honor the flames of summer!", objectives = "" }
WordHunterWoW_QuestEN[92556] = { title = "Honor the Flame", description = "A joyous Midsummer and Dawnsummer Festal upon you, {race}!\n\nWhile celebrating around the bonfire, it is important to pause for a moment of reflection.\n\nMuch has happened here in Silvermoon in recent times and while we cannot dwell upon the darkness of the past, we must look towards the rising Dawn.\n\nTake a moment, while you honor the bonfire, and reflect upon its warmth!", objectives = "" }
WordHunterWoW_QuestEN[92557] = { title = "Honor the Flame", description = "Fetna Alai-nazdo is upon us once again!\n\nAlthough her trample may be dark, her flame burns brightly in all of us! \n\nMay this turn of the Season burn bright and bring good fortune to you and all who celebrate Fetna Alai-nazdo!", objectives = "" }
WordHunterWoW_QuestEN[92558] = { title = "Honor the Flame", description = "I remember the Dawnsummer Festal celebrations back in Eversong and thought 'why not light my own bonfire here in the Howling Ridge?'\n\nThankfully, the local denizens didn't need much convincing.\n\nI told them the bonfires were sacrificial wells for vessels of esoteric magic and... well, that's one way to describe midsummer blossoms, right?\n\nWill you take a moment and honor the voidflame?", objectives = "" }
WordHunterWoW_QuestEN[92559] = { title = "Honor the Flame", description = "The season of Midsummer may be unfamiliar to us, but telling stories by the glow of our root flames is not.\n\nTake a moment to reflect by the bonfire, friend, and listen to those around you.\n\nPonder that which has come before you and that which has yet to unfurl.", objectives = "" }
WordHunterWoW_QuestEN[92563] = { title = "Awoken by Accessory", description = "<As you equip the jewelry, you feel it surge with power, flowing through you and into your artifact weapon.\n\nThe jewelry has unlocked hidden potential of your artifact weapon, enabling and empowering one of its traits.\n\nMoratari will want to record this data.>", objectives = "" }
WordHunterWoW_QuestEN[92572] = { title = "Furniture Favor", description = "Greetings! I see you are eyeing our fine furniture.\n\nMy siblings and I were sent on a mission to find only the finest Decor in the land.\n\nDecor is more than furniture, you see. Crafting a truly great decoration requires attention to so many different details.\n\nCome, friend, let us go on that journey together! Starting today. Today, we find a crate. Not just a normal crate, one that is fantastic. A great crate.\n\nI hear they may sell them nearby, actually...", objectives = "" }
WordHunterWoW_QuestEN[92577] = { title = "Dreamy Inspiration", description = "A crate is nothing more than a box in the dark without lighting. \n\nToday, we go in search of the tiny suns that light our spaces. \n\nNot just any light will suffice. As you can clearly see from my chandelier, we have many lights of varying quality already.\n\nWe seek a unique shape, a unique feel. \n\nThe crafters of Bel'ameth in the Dragon Isles are well-known for their dream-inspired designs. Travel through the Dragon Isles and you will find them at the far end of the plains.", objectives = "" }
WordHunterWoW_QuestEN[92578] = { title = "Draconic Decor", description = "The chandelier I showed you? You must think it so fancy. \n\nBut here I am without the matching sconces!\n\nWhat room lighting can I create without matching sconces? It will be woefully incomplete!\n\nHead over to the Dragon Isles and see if you can find one from the vendors of Valdrakken.", objectives = "" }
WordHunterWoW_QuestEN[92580] = { title = "Spare A Chair", description = "We cannot enjoy our Decor designs without a place to enjoy them from. \n\nBehold, the chair.\n\nWhat better way to enjoy Decor than on Decor itself?\n\nI cannot imagine something more appropriate.\n\nFind me a chair to match this coil. The gearcrafters of Mechagon know the style.", objectives = "" }
WordHunterWoW_QuestEN[92581] = { title = "Last Light", description = "I have sat in the chair and looked at the lights, and yet I am still not satisfied. \n\nThe Decor still does not strike the dramatic tone that we require.\n\nI must trouble you for another source of the light's rays. \n\nTravel to Suramar and speak to the crafters there. They are masters of the art of soft lighting.", objectives = "" }
WordHunterWoW_QuestEN[92600] = { title = "Cracked Keystone", description = "Fragmentary images of heroic deeds flash though your mind as you touch the stone, but they fade as fast as they arrive.\n\nPerhaps performing a suitably impressive task will stabilize the stone's magic once more?", objectives = "" }
WordHunterWoW_QuestEN[92603] = { title = "O Lonely Star", description = "<The void elf writhes in a fitful sleep, tormented by the nearby shade.\n\nPerhaps you should try to wake him.>", objectives = "" }
WordHunterWoW_QuestEN[92604] = { title = "Speak in Blood", description = "After my failed creation, I sought wisdom from the Void, and it told me of this place.\n\nThere was a voice--strange, yet familiar. It promised a tool for shaping Void and shadow--something that would free me from my failure, but the Void gives nothing freely. We must command it, and violence is this land's mother tongue.\n\nSlay the beasts here and bring me their ichor. We'll use it to write our demands.", objectives = "" }
WordHunterWoW_QuestEN[92605] = { title = "Honest as Bone", description = "If ichor is to be the carrier for our message, bone shall be its pigment. This is a place of scavengers, with bones stolen from across this land: old, new, all carrying the echoes of violence that brought their ends.\n\nBring me bone splinters and I will powder them for our ink.\n\nPlease hurry. This shade is a wrong thing, and I must put it right.", objectives = "" }
WordHunterWoW_QuestEN[92606] = { title = "Take Up Your Gift", description = "This place--this wound--is what the voice from the Void told me I'd find. There's something waiting inside... something to put an end to this broken creation.\n\n<Orin winces and glares at the shade.>\n\nYou can't hear it? It howls. Sometimes in rage. Other times it sounds so lonely that it breaks my heart.\n\nIgnore it. With the proper runes written in ichor and bone, I believe we can open this rift wider. Then you can seize what lies within.", objectives = "" }
WordHunterWoW_QuestEN[92607] = { title = "And Carve New Shapes", description = "This is what the voice from the Void promised me: the means to divest myself of this shade.\n\nYou'll have to wield it. Don't worry--it won't harm me. It will separate me from the shade. Then it should simply fade away, no more than an unmoored shadow.\n\nGo on. I'm ready.", objectives = "" }
WordHunterWoW_QuestEN[92608] = { title = "Landscape Photography", description = "I'm having just the best time in your lovely village, it's so quaint!\n\nI'm feeling inspired. I would like to paint a landscape picture to commemorate the occasion. But you know the area better than I.\n\nCould you provide me with some pictures of the landscape I can use for inspiration? You can use my camera. It's top of the line, of course.\n\nI'm sure the perfect spots will just beam at you.", objectives = "" }
WordHunterWoW_QuestEN[92616] = { title = "Mushrooming Courage", description = "Brakko sorry that Brakko let {name} and TeamName down.\n\nBrakko is much scared of sporegliders. Could sneak up at Brakko above cap, where cannot see. Could really hurt cap!\n\nVery sorry, {name}. Brakko doesn't think Brakko can be tank for team.\n\nUnless... {name} practice sporegliders with Brakko?", objectives = "" }
WordHunterWoW_QuestEN[92617] = { title = "Mushrooming Resilience", description = "First Tuktuk runs, then Brakko runs. Cannot be the only one still fighting.\n\nZiny will fail by Ziny's self. Fight is too hard alone, will not be strong enough.\n\nDo not want to fail. Cannot let PH_Teamname down!\n\nHad choice, fail or run.\n\nBut run was also fail. Ziny very sorry to {name}!\n\nCan practice, fight big and scary enemies together?", objectives = "" }
WordHunterWoW_QuestEN[92618] = { title = "Mushrooming Confidence", description = "Tuktuk's poison is not good enough. Tuktuk had to run, before we lose.\n\nSorry if you lose! Tuktuk did not lose. Tuktuk quit. Quit is safe from lose.\n\nGrudge Pit very, rrr... is so intense. Tuktuk cannot handle. Tuktuk will stay out where is safe.\n\nTuktuk will find place to relax. Away from Grudge Pit.\n\nTuktuk cannot lose if stay far away.", objectives = "" }
WordHunterWoW_QuestEN[92630] = { title = "The Pursuit Continues", description = "I bring word from Magister Umbric!\n\nHis apprentice, Leona, has been preoccupied with a desire to learn how the ways of the Illidari.\n\nShe apparently found another demon hunter willing to train her, should she prove herself worthy. But after what happened the last time she sought such a mentor, Umbric is concerned for her safety.\n\nUmbric requests you join Leona for this trial. Make sure she is not getting involved in something she is not prepared to handle.", objectives = "" }
WordHunterWoW_QuestEN[92631] = { title = "Abhorrent Gauntlet", description = "Leona must demonstrate mastery of her weapons--and of her own enmity--by retrieving undamaged pieces of her kills.\n\nI will observe from here.\n\nYou, {name}, will go with her.", objectives = "" }
WordHunterWoW_QuestEN[92632] = { title = "Trial of Wrath", description = "Cutting through scores of lesser foes is a simple task for any demon hunter. It's when we face a large, singular threat that our skills are truly tested.\n\nThat will be Leona's trial. You will act as her second.\n\nLet us see how she vanquishes a particularly dangerous opponent.", objectives = "" }
WordHunterWoW_QuestEN[92634] = { title = "Midsummer's Journey to Loch Modan", description = "While Midsummer may be sacred to the tauren, we are not the only people to pay respects to the spirits of fire during the summer months.\n\nThe Wildhammer, for example, have shared their own customs with us over the years. It seems this time of year has long been important to the dwarves and denizens of the Eastern Kingdoms.\n\nJourney to their celebration grounds across the sea in Loch Modan and visit with the Wildhammer. \n\nPerhaps they too will tell you a tale...", objectives = "" }
WordHunterWoW_QuestEN[92635] = { title = "Midsummer's Journey to the Barrens", description = "Although we have our own traditions during this time, we are not the only ones who pay respects to the spirits of fire during the summer months.\n\nIf you wish to hear the origins of the tauren traditions, travel to Kalimdor to continue your journey.", objectives = "" }
WordHunterWoW_QuestEN[92647] = { title = "A Shadowed Journey Through Time", description = "Champion! The curiosities hidden within the Shadowlands are numerous, as are the dangers. I could use some assistance clearing a path, so to speak.\n\nThere is much wealth to be gained should you choose to seek it.", objectives = "" }
WordHunterWoW_QuestEN[92650] = { title = "The Flickering Anima", description = "The strange anima shimmers with a gentle hum, barely larger than a candle. As your hand draws near it erupts, flooding your mind with a torrent of visions. Triumphs earned through blood, regrets etched in grief, serene stillness all too fleeting, the bitter taste of betrayal. The unbearable cascade threatens to shatter your mind like glass. \n\nThen, silence. The visions end leaving an image Oribos seared into your mind.", objectives = "" }
WordHunterWoW_QuestEN[92652] = { title = "Lorewalking: Warchief, Shaman, Hero", description = "Thrall is well known for his heroics. You would be hard pressed to find someone who hasn't at least heard of him. I will be focusing on his more recent moments, rather than older history.", objectives = "" }
WordHunterWoW_QuestEN[92657] = { title = "The Brewing Storm", description = "Our foothold in Stormarion is tenuous at best. We're barely holding the enemy off on one front. We certainly don't have the forces to assault the rest of the citadel.\n\nThat's where you and I come in. Meet me in Stormarion Citadel when you're ready to get to work.", objectives = "" }
WordHunterWoW_QuestEN[92658] = { title = "Tactical Acquisition", description = "All our forces are focused on this courtyard, but I think we've got another problem. I've scouted between assaults: there's activity in the lower keep. Not to worry you, but there are signs of another singularity.\n\nUp for a little reconnaissance? We'll go through the trench. They've got an impressive operation for gathering Void energy. Might as well hit that on the way. After all, our defenses here can't power themselves.\n\nIf I'm wrong, we can tell Maella we were proactively shoring up supply lines.", objectives = "" }
WordHunterWoW_QuestEN[92659] = { title = "Resource Denial", description = "I've got a hunch I need to follow in the lower keep, and that means going through the trench. I hate to miss targets of opportunity, and the Host's energy collecting operation is right there.\n\nHow do you feel about wrecking their production capacity? The longer it takes them to recover, the easier it'll be to maintain the offensive up here.\n\nIt's not complicated. If it looks useful to the enemy, smash it. After that, we'll move onto the main objective in the keep itself.", objectives = "" }
WordHunterWoW_QuestEN[92660] = { title = "Null Implements", description = "Yes, there may be another unstable singularity. No, I didn't tell anyone. We don't have enough forces to divert our attention--that's why I asked you to accompany me. Besides, we've only got the one Singularity Anchor.\n\nDon't worry though, I've got a plan. These domanaar are experts on shaping the Void, so they must have some means of controlling singularities. Get in there and grab any tools that look important.\n\nWe'll find a way to stabilize this singularity ourselves.", objectives = "" }
WordHunterWoW_QuestEN[92661] = { title = "Hammer Meet Anvil", description = "I don't approve of Lysikas's disregard for duty, but I do trust his instincts. If he says there's something here we need to see, then he's probably right.\n\nEven if he's wrong, we shouldn't waste this opportunity. A domanaar weaponsmith and researcher does his work from here. With most of the Stormarion forces attacking our Singularity Anchor, he should be an easy target. Take him out.", objectives = "" }
WordHunterWoW_QuestEN[92662] = { title = "Core Collapse", description = "This singularity could reach critical mass at any moment. We've no time to evacuate. It will devour our forces in the upper citadel, maybe even the Ingress.\n\nWill you handle the tools? I've no idea how they work, but you've used more artifacts and seen more strange magic than most. Remember, the Void responds to will. Use the tools and command the singularity to stabilize. I trust you'll figure out the rest.\n\nThe Host will try to stop us. Lay down some defenses, then I'll cover you while you work.", objectives = "" }
WordHunterWoW_QuestEN[92667] = { title = "UNUSED", description = "Thrall's parents had lost their life while he was an infant - the start of a rough upbringing. Found by humans, he was raised within the internment camps from the Second War. The one in charge, a man named Blackmoore, was a terribly cruel taskmaster.\n\nA rare friend during that time, Taretha Foxton, promised to help Thrall escape from his shackles.", objectives = "" }
WordHunterWoW_QuestEN[92671] = { title = "Lorewalking: Rise of the Horde", description = "Let us keep the focus on Thrall, yes?\n\nThe Horde's history is expansive - and fascinating. Perhaps we can learn about it another time.\n\nThis period denotes the beginning of our hero's restlessness. His time as warchief now over by his own reckoning. Clinging to something he had learned in his journeys, he sought out the Earthen Ring and continued his studies of shamanism. But the life he left behind shadowed him every step of the way...", objectives = "" }
WordHunterWoW_QuestEN[92672] = { title = "UNUSED", description = "The Cataclysm upended both Eastern Kingdoms and Kalimdor. But it is from these wounds where Thrall showed Azeroth what he was truly capable of.\n\nAzeroth needed a Shaman to take care of Deathwing, and they got one.", objectives = "" }
WordHunterWoW_QuestEN[92673] = { title = "Lorewalking: In Pride's Wake", description = "Thrall left the Horde behind with the hope that the foundation he had laid would lead them towards the future.\n\nUnfortunately turmoil quickly followed - Garrosh, the young orc Thrall had named as warchief, had a very different idea on what the Horde should be. One that left a major scar on Azeroth.", objectives = "" }
WordHunterWoW_QuestEN[92674] = { title = "Lorewalking: Across a Burning Portal", description = "", objectives = "" }
WordHunterWoW_QuestEN[92675] = { title = "Lorewalking: The Weight of Doubt", description = "After Garrosh's death, Thrall found himself doubting his abilities. And so he made a choice - his new path would be his family.\n\nThey retreated back into Outland, where his ancestors once lived, and found personal peace. All the while, Azeroth was facing a new war - one that could burn everything he had once fought for to the ground.", objectives = "" }
WordHunterWoW_QuestEN[92676] = { title = "Lorewalking: In Another's Footsteps", description = "Thrall was at a crossroads, stuck between what he once was and what he should be.\n\nAnd his hesitation affected more than just his mental state. The elements he once commanded effortlessly barely whispered a response to his call. The hero was held down by his own perception of the past.\n\nBut an answer that helped him push forward would come - amusingly, from the same past that haunted him.", objectives = "" }
WordHunterWoW_QuestEN[92677] = { title = "Lorewalking: Paths Ever Onward", description = "We have just about reached the end of my tale, despite Thrall's story continuing.\n\nIt is hard to tell a story that hasn't been finished yet.\n\nBut I have no doubt we will continue to see great things from Thrall. Warchief, shaman, hero of Azeroth, Go'el. May he forge forward with all of his names in pride.", objectives = "" }
WordHunterWoW_QuestEN[92688] = { title = "Bronze Simulacrum", description = "<Erus will be delighted to scrap this for you for a heaping sum of bronze.>", objectives = "" }
WordHunterWoW_QuestEN[92689] = { title = "A Path Forward", description = "{name}, today will be a day of ceremonies and great magic.\n\nBefore we begin to cleanse the Darkwell, agreements must be made. \n\nWe have two events that have requested your presence, both as a mediator and as a witness. What we lay down today will have lasting ramifications, and it is important to all of us that we have you at the center of it all. \n\nMeet with Aethas and Rommath for their respective events. Once you are done, return here and we shall continue to the Darkwell together.", objectives = "" }
WordHunterWoW_QuestEN[92690] = { title = "[DNT] Quest Test Test Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[92692] = { title = "Hero's Call: Test!", description = "All able-bodied citizens of the Alliance are to report to Foreman Eksos in Talador.\n\nThe Iron Horde seek to control Talador. The area is perfect to send reinforcements to any other part of Draenor quickly and without resistance.\n\nForeman Eksos is currently establishing an outpost in Talador. Travel there and stop the Iron Horde.\n\nGlory to the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[92694] = { title = "Dusk Among Pigments", description = "As Zur'ashar, our oath is to safeguard the harmony within the visions and the histories we preserve.\n\nYet Orn'shan's crude strokes are reckless. Their creative impulses lack refinement, disturbing the balance we are sworn to protect. In a misguided attempt at creativity, they've created uncontrollable chaos and are distorting the very truths they sought to record.\n\nPerhaps they will heed the words of an outsider before their reputation collapses entirely.", objectives = "" }
WordHunterWoW_QuestEN[92695] = { title = "The Stroke of Storms", description = "I... I don't think I can mend this. The Zur'ashar were right. I am no true paintmaker. I cannot even capture history properly within my own memories... how could I ever hope to honor it in moments that matter?\n\nI thought I could create something beautiful... something worthy. I was foolish to try.\n\nCan you... can you help me clean this mess? I... I have no hope left to do it myself.", objectives = "" }
WordHunterWoW_QuestEN[92696] = { title = "Colors Born Anew", description = "Outsider... thank you. I'm still shaken... but I can feel a small spark returning. I'd nearly abandoned my work entirely, yet your kindness... it has steadied me.\n\nI think I finally see what I'm meant to create: something meaningful that honors the Zur'ashar tradition through my voice, but to begin, I need the raw essence of color itself.\n\nWill you help me collect the ingredients I need? I'd be looking for anything I can use to turn into paint.", objectives = "" }
WordHunterWoW_QuestEN[92697] = { title = "Hues of Tomorrow", description = "I... never expected to feel this again. Your help has given me hope. These ingredients feel right, and maybe even enough.\n\nI want you to be the first to paint. Do not fret over perfection. Paint what you feel, and I'll capture its essence into the memory I preserve.\n\nI look forward to see what you create.", objectives = "" }
WordHunterWoW_QuestEN[92711] = { title = "Ignite the Skies: Stormwind", description = "Welcome to the Midsummer Festival of Fire, friend!\n\nHave you come to toss a few torches? Or maybe dance around the maypole?\n\nAh, you must be here to ignite the blossom lights over the skies of Stormwind, aren't you? It is an old tradition, long forgotten but newly rekindled!\n\nWell, come on then. Take to the skies and fly!", objectives = "" }
WordHunterWoW_QuestEN[92713] = { title = "Echoes Rekindled", description = "The relics you restored still hum with the visions you once walked.\n\nTheir stories yearn to be lived again, and each retelling leaves the world just a little richer than before.\n\nReturn them to the shrines, let the memories flow, and I shall place in your hands a reward for one who walks the paths of legend.", objectives = "" }
WordHunterWoW_QuestEN[92715] = { title = "By Invitation Only?", description = "Fancy yourself a Brawl'gar contender do you, {class}? They don't let just anyone in there, you know. Certainly not without an invitation.\n\nThat said... just between you and me, if you know where to look and you've the means they say anyone can have their moment in the spotlight these days.", objectives = "" }
WordHunterWoW_QuestEN[92716] = { title = "The Story of Wey'nan's Ward", description = "You have walked this path before, {name}, yet the Vale of Secrets stirs anew.\n\nThe Visionstone awaits, its sacred paintings familiar to your eyes, the handprint at its heart calling for you again.\nPress your hand upon it once more and let your spirit be known. The trance will take you as before, carrying your soul through visions whose truths still shift with every telling.\n\nReturn to me with what new wisdom the echoes grant you.", objectives = "" }
WordHunterWoW_QuestEN[92719] = { title = "The Story of the Cauldron of Echoes", description = "Once more, the Cauldron of Echoes stirs.\n\nWhen I first walked the path of the Zur'Ashar, my master spoke of its place at our beginning. Even they could not grasp its full meaning. Now, it beckons again.\n\nStep into its quiet and draw forth what the ages have hidden. Bring me the truth as it speaks to you this time.", objectives = "" }
WordHunterWoW_QuestEN[92720] = { title = "The Story of Aln'hara's Bloom", description = "The bloom still waits, its stillness carrying the same quiet call you once followed.\n\nYet the bloom's story deepens with each telling. Walk its path again, let the stillness speak anew, and see what more the goddess chooses to share.", objectives = "" }
WordHunterWoW_QuestEN[92721] = { title = "The Story of the Echoless Flame", description = "The Echoless Flame rests as you left it, yet the air around it stirs once more.\n\nYou have walked Obayo's path before, felt the echo of that first Shul'ka's purpose. But the past is a shifting thing, and the Flame's silence may yet hide verses you have not heard.\n\nReturn to its vigil. Follow Obayo's steps again, and let the vision show you what remains untold.", objectives = "" }
WordHunterWoW_QuestEN[92722] = { title = "The Story of Russula's Outreach", description = "The spear still waits where you last left it, pale threads of mushroom slowly weaving new patterns into its grain.\n\nThe culling grounds draw you again. Walk their softened paths, follow what spores still rise, and let the visions show what time has chosen to reveal this season.", objectives = "" }
WordHunterWoW_QuestEN[92724] = { title = "The Story of the Root of the World", description = "The Root of the World stands as it did before--ancient, unbowed--yet the soil breathes differently today. Beneath your feet, the pulse of Harandar quickens, as though eager to share another verse of its oldest story.\n\nYou have seen through Ruilla the Huntress's eyes once before. But the Rootways are never walked the same way twice. Go again, and let the land decide which truths it will show you now.", objectives = "" }
WordHunterWoW_QuestEN[92725] = { title = "The Story of Sky's Hope", description = "Sky's Hope rests in its cradle as before, yet the heavens above seem sharper tonight.\n\nYou have traced Awe'ohna's path once, but the tale shifts with every telling. Walk the path again, and perhaps the sky will tilt just so, revealing a truth you missed before.", objectives = "" }
WordHunterWoW_QuestEN[92728] = { title = "Dogged Disturbances", description = "That dog! It ran through here and disrupted every lesson on the schedule. Now there are fire elementals everywhere and my students are ill-prepared to handle this mess. How am I supposed to teach in all of this chaos?\n\nYou look capable--would you clear out some of these rowdy little elementals? The sooner we get this situation under control, the better!", objectives = "" }
WordHunterWoW_QuestEN[92729] = { title = "Hounded and Hassled", description = "Gilneas and Kul Tiras are both known for their hunting hounds. With the resurgence of elfhounds in Silvermoon, I thought perhaps they could be similarly utilized. They're dogs, after all. How hard could training possibly be?\n\nLong story short, that dog made a mess and dashed off. I have to clean this up. \n\nWould you please find that creature and bring him back to me before the local canine cafe has my head? I only borrowed him for the day!", objectives = "" }
WordHunterWoW_QuestEN[92732] = { title = "Light Disturbance", description = "We have had victories against the Lightbloom, but Alndust is rare. Until we can gather more, the Lightbloom continues its spread. Our forces are stretched too thin to watch their every movement.\n\nA scout spotted a strange corpse by the road to the east, along with a report of a general disturbance of the light-cursed creatures. I can't look into both at once. Could you find that corpse while I investigate deeper into the Encroaching Bloom?", objectives = "" }
WordHunterWoW_QuestEN[92736] = { title = "Light Stroll", description = "<These potatoad creatures are seldom seen near the Lightbloom. It is covered in spores and looks like it was trying to escape. You should search for more clues.>", objectives = "" }
WordHunterWoW_QuestEN[92737] = { title = "Light Carnage", description = "The Lightbloom has infected many of these potatoads and spurred them into a frenzy. They spread the spores and reproduce at a dangerous rate.\n\nIf we don't act, we will be overrun. Will you cull this heard while I search for the source of the corruption?", objectives = "" }
WordHunterWoW_QuestEN[92738] = { title = "Potatoad Tots", description = "It is too late for the adults, but the young may still be saved. If you can capture them, we can remove the spores before they take root.\n\nGather up the spore covered potadpoles and bring them to me. I will take them to Har'alnor myself to purge this Lightbloom.\n\nDo not let their first breaths be their last. Please, {name}: save the babies.", objectives = "" }
WordHunterWoW_QuestEN[92739] = { title = "O.K. Bloomer", description = "I have discovered the lair of a cunning creature I call Adzikel. With luck, this name will soon be forgotten. \n\nAdzikel sneaks into the potatoad nests to steal their young, and plants the Lightbloom spores to accelerate their growth into the frenzied toads, which spread more spores.\n\nFor the little ones to have a chance, I must return to Har'alnor, but you have earned the right to slay this beast. Go with honor, and finish the hunt!", objectives = "" }
WordHunterWoW_QuestEN[92740] = { title = "Questionable Qualifications", description = "Well {class}, it's your lucky day. I just happen to have an extremely genuine Brawler's Guild Invitation right here in my stockpile.\n\nThat said I'll need a moment to process the paperwork. That requires my complete concentration without your prying eyes on me. So do please give me a moment.", objectives = "" }
WordHunterWoW_QuestEN[92816] = { title = "A Letter for Adventure", description = "<You look down to see a rough looking letter with your name on it.\n\nWhy not open it up to see what's inside?>", objectives = "" }
WordHunterWoW_QuestEN[92821] = { title = "Ignite the Skies: Silvermoon", description = "The season of Midsummer is celebrated by many cultures across Azeroth.\n\nEven now, bonfires across the land are ignited in honor of the spirits of fire.\n\nTo share our customs with all who dwell under the sun's warmth, I've had crates of sun blossoms brought to Silvermoon.\n\nTake to the skies and ignite the blossoms above, {name}!", objectives = "" }
WordHunterWoW_QuestEN[92826] = { title = "Lorewalking: The Loa of Kings", description = "Where to begin? There's so much to say!\n\nThere's a great story from the Zandalari about the connection between troll and loa. Let's start there!", objectives = "" }
WordHunterWoW_QuestEN[92829] = { title = "Lorewalking: Death of the Drakkari Loa", description = "The Drakkari of Zul'Drak are well known for massacring their loa. The prophets of the Drakkari loa decided to take the full power of the loa by force.\n\nThe loa were blind-sided by this betrayal. They never dreamed rituals existed that could permanently kill them and steal their essence.", objectives = "" }
WordHunterWoW_QuestEN[92831] = { title = "Lorewalking: The Blood Loa", description = "Not every loa is a protector and companion to trolls. There are loa that eat their followers, like the blood loa, Hakkar. In trade for sacrifices, Hakkar grants dark blood powers to his followers. But he always takes more than he gives.\n\nHakkar the Soulflayer has absorbed so much blood from his cultists that he's become almost a perpetual threat to the world.", objectives = "" }
WordHunterWoW_QuestEN[92832] = { title = "Lorewalking: The Hash'ey", description = "The last story I want to share is about the Darkspear trolls... and Mueh'zala.\n\nMueh'zala is a mighty Loa of Death. Highly manipulative, he puts his plans into motion by using others as his pawns.\n\nHe's used a hash'ey in the past. A hash'ey is a troll imbued with the full power of the loa.", objectives = "" }
WordHunterWoW_QuestEN[92836] = { title = "Reignite the Skies: Stormwind", description = "Welcome to the Midsummer Festival of Fire, friend! \n\nHave you come to toss a few torches? Or maybe dance around the maypole?\n\nAh, you must be here to ignite the blossom lights over the skies of Stormwind, aren't you? It is an old tradition, long forgotten but newly rekindled!\n\nWell, come on then, take to the skies and fly!", objectives = "" }
WordHunterWoW_QuestEN[92839] = { title = "Reignite the Skies: Orgrimmar", description = "Midsummer is a time to reflect on the past and future. As old traditions fade, new traditions are born. \n\nOne old tradition, practiced long ago, involved the offering of sun blossoms to An'she. As summer winds took them upwards, the blossoms would burn bright blue and orange.\n\nBut faded traditions need not remain lost.\n\n\nWill you take to the skies to ignite the sun blossoms and help rekindle this old tradition?", objectives = "" }
WordHunterWoW_QuestEN[92845] = { title = "By Invitation Only?", description = "Fancy yourself a Brawlpub contender do you, {class}? They don't let just anyone in there, you know. Certainly not without an invitation.\n\nThat said... just between you and me, if you know where to look and you've the means they say anyone can have their moment in the spotlight these days.", objectives = "" }
WordHunterWoW_QuestEN[92851] = { title = "Questionable Qualifications", description = "Well {class}, it's your lucky day. I just happen to have an extremely genuine Brawler's Guild Invitation right here in my stockpile.\n\nThat said I'll need a moment to process the paperwork. That requires my complete concentration without your prying eyes on me. So do please give me a moment.", objectives = "" }
WordHunterWoW_QuestEN[92855] = { title = "Make Haste, Not Waste", description = "", objectives = "" }
WordHunterWoW_QuestEN[92857] = { title = "Ta'readon's Mount Voucher", description = "This token bears the seal of Overseer Ta'readon in Oribos. They would be interested in seeing this.", objectives = "" }
WordHunterWoW_QuestEN[92864] = { title = "Drift Them Away", description = "With the hydras hunted out of the area, the drifter population in the cascades to the west is on the rise. Egg sacks are making the water murky and undrinkable, and the drifters are becoming very territorial.\n\nWe must ensure that the reintroduction of the hydras will succeed. We need to cull the number of drifters and clear some of their egg sacks.\n\nYou look like someone capable of doing this task. Will you help me?", objectives = "" }
WordHunterWoW_QuestEN[92865] = { title = "Feeding the Buds", description = "The orchid hydra's favorite food is the violet chloroceros--especially the buds on the bull's back.\n\nWith the hydras gone for so long, the violet chloroceros grazed too much of the fauna. Soon, there will only be mud in that once lush and beautiful part of Harandar.\n\nI want to introduce my hydras to their primary source of food, and I would appreciate it if you could bring me four of those buds.", objectives = "" }
WordHunterWoW_QuestEN[92866] = { title = "Re-Hydra-ted", description = "With the previous tasks done, it is time to reintroduce the budlings to the wilds.\n\nI have marked suitable locations to place the budlings. The little hydras will be an easy pick, so expect predators to attack you.\n\nI am sad to see them go. However, I know it is for the ecosystem's and their own good.", objectives = "" }
WordHunterWoW_QuestEN[92868] = { title = "He Went Thataway", description = "You've been invaluable, {name}. As for that little menace, after he was done wreaking havoc here, I didn't really pay attention to where he went next. I'm sure you'll find him eventually. \n\nLet's hope you do before he wrecks half the city, hmm?", objectives = "" }
WordHunterWoW_QuestEN[92869] = { title = "Fishy Dis-pondencies", description = "That dog tore right through the pond and sent half the sunwhiskers flying right out of the water! Quickly, get them back in the pond before they perish!", objectives = "" }
WordHunterWoW_QuestEN[92870] = { title = "Scoot Along Now", description = "That dog! The last I saw he was tearing through the pond. I didn't see where he went, but he has to be nearby!\n\nHis barks... they haunt me...", objectives = "" }
WordHunterWoW_QuestEN[92875] = { title = "Understanding the War Within", description = "I fear your time in Valdrakken must come to an end.\n\nDark forces gather to threaten other parts of Azeroth. We will do what we can to uncover Iridikron's schemes.\n\nYou must learn more of what has unfolded.", objectives = "" }
WordHunterWoW_QuestEN[92876] = { title = "Never", description = "", objectives = "" }
WordHunterWoW_QuestEN[92882] = { title = "A Hunter's Plight", description = "I am desperate enough to ask an outsider for help.\n\nTo join the Ka'dani, the elite hunters of Har'athir, you must complete a ritual under the guidance of an experienced Ka'dani. However, there are none left to guide me, so I cannot take the trial.\n\nBut I have heard words of your actions. Maybe Akazi, the Ka'dani Elder, would let you stand as my guide. You may not know the ritual, but you know the hunt.\n\nPlease, let us speak to Elder Akazi. We must try.", objectives = "" }
WordHunterWoW_QuestEN[92883] = { title = "A Hunter's Duty", description = "At the start of the trial, the mentor and trainee gather materials to forge a hunting weapon.\n\nThe weapon is more than an extension of the Ka'dani-- it's part of their being. There is no other weapon like it, as each is unique.\n\nYou will help Ketan hunt and gather the materials and decorations, as well as a gift for the weaponsmith.", objectives = "" }
WordHunterWoW_QuestEN[92884] = { title = "A Hunter's Weapon", description = "Forging the Ka'dani weapon is a crucial moment in the trial. We will have to follow Al'yaat's instructions.\n\nOnce Al'yaat forges the weapon, you will bring it to Elder Akazi.\n\nThere will be a short ceremony where he will hand me the weapon. The ceremony concludes with the elder announcing our final task.\n\nI shouldn't let the excitement take the better of me, but one thing at a time. We must be patient and calculated as if we were on a hunt.", objectives = "" }
WordHunterWoW_QuestEN[92885] = { title = "A Hunter's Prey", description = "The last trial stands before you. Together, you have forged a weapon that will fell any beast, but the weapon is nothing without the hunter.\n\nSince you are not a Ka'dani, I present you with a difficult hunt. Ketan and you will hunt down and slay a prey known to all Har'athir hunters: the great Radooni. The beast ventured too close to Har'athir and should be a suitable hunt.\n\nReturn to me once your hunt is complete and Radooni's sap is on the spear.", objectives = "" }
WordHunterWoW_QuestEN[92890] = { title = "A Handful of Voidlight Marl", description = "", objectives = "" }
WordHunterWoW_QuestEN[92891] = { title = "A Cluster of Voidlight Marl", description = "", objectives = "" }
WordHunterWoW_QuestEN[92892] = { title = "A Trove of Voidlight Marl", description = "", objectives = "" }
WordHunterWoW_QuestEN[92895] = { title = "Hagar's Invitation", description = "Hagar has a message she believes the elves and trolls of Azeroth must all hear. She has sent a call to leaders from the elven and troll tribes to come to Harandar.\n\nI have come here to ask the blood elves to join us, but you should be there as well. You have been with us through so much of this.\n\nThe Rootways from Silvermoon would be the fastest way.", objectives = "" }
WordHunterWoW_QuestEN[92897] = { title = "The Preparations Are Complete", description = "{name},\n\nI bear an important message from Hagar. You are invited to a special meeting in Harandar. Please meet me in Silvermoon to discuss it.\n\nOrweyna", objectives = "" }
WordHunterWoW_QuestEN[92899] = { title = "History Lesson", description = "Hagar requested that we invite to this meeting all of the troll and elven leaders we know.\n\nIt was not easy to convince them to come. There are some... past grievances between these groups. Hagar hopes to overcome these divisions.\n\nAs we wait for the others to arrive, feel free to speak to the other delegates. The wait is making them restless, so try not to inflame tensions.", objectives = "" }
WordHunterWoW_QuestEN[92900] = { title = "A Favor for Kinduru", description = "Zul'jarra could not leave Zul'Aman as the Amani still recover. She sent Zul'jan in her stead.\n\nShe hoped showing trust and giving him dis responsibility would bring him out of her shadow. Make use of his talents. But dis news...\n\nI am an old troll. I have a hard time reining Zul'jan in, but he may listen to you.\n\nWould you join us? Zul'jarra and I would be grateful if Zul'jan stayed out of trouble.", objectives = "" }
WordHunterWoW_QuestEN[92901] = { title = "Revisionist History", description = "Not all of the visions in this place were clear to us. Some of them were... strange.\n\nOne in particular seemed to revolve around an unfamiliar people: a people that we learned are the Amani trolls.\n\nThe magic used to create the painting, to pull the memories from the past, are tied to the haranir and those close to us. If there was no connection, the Zur'ashar--who create the paintings--could not have recalled troll history.\n\nI can show you and Zul'jan, and you can judge for yourselves.", objectives = "" }
WordHunterWoW_QuestEN[92902] = { title = "Rescue Amani from Priest Sacrifices", description = "", objectives = "" }
WordHunterWoW_QuestEN[92903] = { title = "Fight Alongside Ula'tek", description = "The third vision shows Ula'tek and the amani fighting against the enemies of the amani. You help them fight. Zul'jan is a talking head during this sequence.", objectives = "" }
WordHunterWoW_QuestEN[92904] = { title = "Return to Zul'Aman", description = "I have heard de story since I was a child! De Amani were outnumbered and still dey fought on! Dey claimed victory through sheer will!\n\nOrweyna says de visions cannot lie. Uncle thinks details of de battle could have been lost. Dey would question everything it means to be Amani.\n\n<Zul'jan scowls.>\n\nI must find de truth of dis. Uncle says if anyone would know, it would be de loa. De loa have said nothing of dis before, but we must start somewhere.\n\nIt's time to go home.", objectives = "" }
WordHunterWoW_QuestEN[92905] = { title = "Help Uncle with Loa", description = "You go find Uncle Kinduru. Uncle doesn't know anything about Ula'tek but can ask the eagle loa. You help him perform a ritual to ask the loa. He says the loa don't know either.", objectives = "" }
WordHunterWoW_QuestEN[92906] = { title = "Breadcrumb to Eagle Rise", description = "", objectives = "" }
WordHunterWoW_QuestEN[92907] = { title = "Amani Answers", description = "My uncle has already started communin' with de loa to find information on dis Ula'tek. Meanwhile, we gonna dig through his boxes to see what we can find.\n\n<Zul'jan points to all the boxes scattered around the terrace.>\n\nMy uncle has de biggest collection of histories among de Amani. I used to read through dem when I was a boy.\n\nLook for anything about Ula'tek, snakes, or early Amani history. I'll take these, you search de others.", objectives = "" }
WordHunterWoW_QuestEN[92916] = { title = "A Call for Aid", description = "{name}, I call upon you to aid the Amani again as a fellow hash'ura. Another dire threat is upon them.\n\nMalacrass has returned.\n\nWitherbark Bluffs is under attack by a monstrous enemy the likes of which I have never seen. And with our brush against the Twilight's Blade, the timing could not be worse.\n\nZul'jan deserted us and... we believe he may be at least partially at fault.\n\nWe will deal with both of them in time. For now, help us before we are overrun.", objectives = "" }
WordHunterWoW_QuestEN[92917] = { title = "Saving Those Bound", description = "<Liadrin wipes sweat from her brow and addresses you without turning. You see minor cuts and scrapes she has neglected to heal.>\n\nWe fell back from the town gates. There were so many wounded and poisoned. Orweyna, Tak'lejo, and I best serve the Amani here.\n\nBut you should be out there helping Zul'jarra.\n\nMalacrass's serpents are capturing Witherbark, coiling around them, and filling them with poison.\n\nFree them--and make sure to find Dak'zor. He was on the front line and first to fall.", objectives = "" }
WordHunterWoW_QuestEN[92919] = { title = "All Bark, All Bite", description = "The wounds I have seen... the ferocity.\n\nNot only do these serpents slither on the ground and coil around our warriors' bodies, but they cut deep with their poisoned blades and target them with their talons as they dive from the skies.\n\nZul'jarra and her forces cannot win this on their own, but my hands are needed here. \n\nHelp Zul'jarra by taking them down.", objectives = "" }
WordHunterWoW_QuestEN[92920] = { title = "Down With the Skies", description = "I will need some time to call upon Akil'zon and open de way. Dat's where you come in.\n\nProtect me, my hash'ura.\n\nI entrust you with my life. We've taken great leaps before, eh?", objectives = "" }
WordHunterWoW_QuestEN[92921] = { title = "To the Skybridge", description = "<Zul'jarra's face is dark with rage as she looks off toward the Skybridge.>\n\nZul'jan... you let dat snake Malacrass taint your mind and heart. For what? Power?\n\nDe lightwood was one thing. But dis?\n\nI don't know what Malacrass has planned for de captives, but we have to take de fight to him and away from our people.\n\nFollow de monsters' path back to de Skybridge. I will consult de loa and meet you there.\n\nWith their help, we will stop this.", objectives = "" }
WordHunterWoW_QuestEN[92922] = { title = "Those Who Can't Fight", description = "Zal'jarra also asks us to rescue a few people!", objectives = "" }
WordHunterWoW_QuestEN[92924] = { title = "What Lies Beyond the Fog", description = "With de loa, we are powerful. Without de loa, we are still the Amani. We will get our kin back.\n\nLiadrin will join us soon with reinforcements, and my warriors are eager to take vengeance.\n\nThere can be no delay. For my people's sake and for Zul'jan's.", objectives = "" }
WordHunterWoW_QuestEN[92925] = { title = "The Glint of History", description = "The ruins across this island are ancient, built by the Amani long ago. If we discover how they came to be here, we may learn the truth of Ula'tek.\n\nThen we can show Zul'jan what he is really chasing.\n\nI have an idea of where to look for that crypt. Let us go together, {name}.", objectives = "" }
WordHunterWoW_QuestEN[92926] = { title = "Prey: Astalor's Initiative", description = "Ah, {name}. I am glad to see you here in our city, even if the times are trying.\n\nWe are once again beset on all sides by uncertain friends and dangerous foes, but I am not unprepared. I have a... guest, housed nearby. They may hold the key to our city's survival. \n\nMeet me near the harbor if you have the strength to do what must be done.", objectives = "" }
WordHunterWoW_QuestEN[92927] = { title = "Echoed Steps", description = "Sometimes the goddess' visions are not easy to understand at first, but in time she reveals her intentions.\n\nI will keep the Children of Ula'tek out of your path as you follow her memories.\n\nTrust that she will reveal what we need to learn.\n\nMeet me up ahead once you have witnessed her memories of the Amani.", objectives = "" }
WordHunterWoW_QuestEN[92928] = { title = "What Was Buried", description = "The visions of Nek'zali led us here. That we found where she took her last breath is no coincidence.\n\nThere must be something within this crypt that the goddess wishes for us to see.\n\nZul'jarra bid us to find the truth of Ula'tek. Perhaps here we will find the answers we seek.\n\nLet us see where the story we were told in the Den of Echoes ends, and where the truth begins.", objectives = "" }
WordHunterWoW_QuestEN[92929] = { title = "Lurking in the Dark", description = "Those who built this crypt would not have sealed it without good reason.\n\nA great evil from the past must dwell here.\n\nWe should put to rest any spirits and undead we find. They cannot keep us from the answers we seek.", objectives = "" }
WordHunterWoW_QuestEN[92930] = { title = "Written by the Victors", description = "A version of this history is written into the Den of Echoes. The same events, only recorded by Amani hands instead of haranir ones. \n\nBut something is missing: Nek'zali. How is she part of the story of Ula'tek? \n\nAnd we do not know how Ula'tek came to this world.\n\nWe must go deeper into the crypt and witness the truth written on its walls.", objectives = "" }
WordHunterWoW_QuestEN[92931] = { title = "Delay the Venom", description = "The wound from Zul'jan's blade. It won't heal.\n\nZul'jan must have poisoned her. She's weakening, and I have not been successful in curing her with Light.\n\n<Liadrin engulfs Zul'jarra in Light again. Nothing changes.>\n\nBlast it!\n\nWhatever you found in that crypt can wait.\n\nThe Amani are trying to find a cure. Ask Raz'taka if he's made any progress.\n\nIf you need anything else, talk to Tak'lejo. Zul'jarra needs to focus on recovering.", objectives = "" }
WordHunterWoW_QuestEN[92932] = { title = "Clear the Swamp", description = "Look in the distance. Restless, evil energy fills the sky. That structure ahead must have the answers we seek.\n\nThe creatures that stand in our way must be culled. We cannot risk being overcome on such a vital mission.", objectives = "" }
WordHunterWoW_QuestEN[92933] = { title = "Haunted Shore", description = "With Zul'jarra down, de Amani are losin' heart with each passin' moment. We gotta do somethin' to show dem that dis isn't over.\n\nThose tortollans have been helpin' where they can. Let's repay de favor and help out de captain. \n\nSeein' a bunch of their lost crew return to town oughta give dem some hope in dis cursed land.", objectives = "" }
WordHunterWoW_QuestEN[92934] = { title = "Fuel the Calling", description = "<Your loyal follower keeps her voice low as you approach.>\n\nAs you foretold, red rain falls from de sky. De heavens align. A great beast rouses at de door beneath de world. At last, a weapon for de Amani--one greater than any Zandalari loa. We just need de fuel to summon it.\n\nMost of de warband is injured and isolated. Fallen soldiers will welcome de sight of you, expecting you to heal dem.\n\nTake your dagger and do what must be done. Only you can save us, Nek'zali.", objectives = "" }
WordHunterWoW_QuestEN[92935] = { title = "Pushed to the Brink", description = "De ocean at our back slithers with tentacles and eyes, but we are safer there than on dis land. We were fools to think we could claim it from Kith'ix.\n\nI have stood by your new obsession with rituals and superstitions, Nek'zali. Now, I need you to be de healer you once were.\n\nHelp my soldiers fight off de aqir. Buy us the time we need for de transport boats to arrive.", objectives = "" }
WordHunterWoW_QuestEN[92936] = { title = "The Summoning of Ula'tek", description = "Where is de rest of our warband?! De lines are breaking!\n\nMy soldiers will hold dem off as long as dey can. De weak should run. But you and I... if we die, let it be together with weapons in hand, sister.", objectives = "" }
WordHunterWoW_QuestEN[92937] = { title = "Awakened Evil", description = "Nek'zali, dat priestess... We should bring word of what we've seen back to de hash'ey.\n\nOrweyna. Ay! Wait--what's wrong with her?", objectives = "" }
WordHunterWoW_QuestEN[92938] = { title = "Site of Terror", description = "The air is thick with restless spirits. But there's more--it is the goddess. Where her voice was once quiet, I can feel it is now raised in anguish. Like a scream of terror.\n\nI fear for what we may find ahead.\n\nI will follow her voice. Come. Together, we uncover her memories of this place.", objectives = "" }
WordHunterWoW_QuestEN[92939] = { title = "It's Not Just a Rock!", description = "{name}, I have something strange, here.\n\nWhile scouting in the Storm Fields, I found this rock a beast was chewing. Look at it! Could these be runes? Writing?\n\nBut so ancient? Here? What could it mean?\n\nStrangely, I think I've been hearing a voice in my head since I found this thing...\n\nWe must investigate further. Maybe we can find more of this rubble in the bellies of those beasts?", objectives = "" }
WordHunterWoW_QuestEN[92944] = { title = "Sifting Through Void", description = "There's no rubble on the surface. The beasts are burrowing, so they must be finding it in a cavern underground.\n\nI've been thinking of how to get there.\n\nYou've noticed the vortexes that dot the Storm Fields? They twist space, moving things from place to place.\n\nStep through one and I can reveal the anomalous residue that surrounds them.\n\nCollect the residue and I can make a spell to redirect the portal to where the source of the rubble is!", objectives = "" }
WordHunterWoW_QuestEN[92945] = { title = "The Power of Anguish", description = "These threats we chase are intelligent. Determined. Deadly.\n\nTheir ingenuity will seek to confound you. Their strength will seek to destroy you. It is from their very will to live--to predate--that we will extract the essence required to fuel the magical defenses of our city. \n\nI have had my assistants lay out our friend's toys. You'd do best to familiarize yourself with them.", objectives = "" }
WordHunterWoW_QuestEN[92946] = { title = "Buried in the Dark", description = "We're at the brink of a monumental discovery! Hurry, there's no time to even call for backup. We must find this strange spirit!\n\nWith this residue, I can make a spell to adjust the vortex. It'll lead us to the source of this engraved rubble.\n\nBased on the specter's guidance, I believe we'll find an entire cave.\n\nBe ready, {name}.", objectives = "" }
WordHunterWoW_QuestEN[92948] = { title = "In Over My Head", description = "Akintunde created a weapon to end all intelligent life on this world, eons and eons ago?\n\nI hardly believe it.\n\nBut truth or lie, we can't leave this spirit be. He's clearly dangerous.\n\nIf he truly knows how to create such a weapon, we can't let him contact anyone from Azeroth. We both know a few warmongers who would do anything for that kind of power...\n\nI think I can realign the vortex again to take us directly to Akintunde. Ready yourself for a fight, {name}.", objectives = "" }
WordHunterWoW_QuestEN[92949] = { title = "Breadcrumb to Bitterbark", description = "", objectives = "" }
WordHunterWoW_QuestEN[92950] = { title = "Collect Ingredients for Uncle", description = "", objectives = "" }
WordHunterWoW_QuestEN[92951] = { title = "Digging Deeper", description = "De mask says we are lookin' for de scrolls of Malacrass. While we are in Maisara, try to find any scrolls de Vilebranch have left around.\n\nMaisara is a dangerous place, so don't bother sortin' through dem--just grab 'em and we can check later.\n\nEven if dey don't mention Ula'tek, we might find information about their plans or intentions against de Amani.", objectives = "" }
WordHunterWoW_QuestEN[92952] = { title = "Mission to Maisara", description = "De magic helped, but... not enough. I still don't remember my name or past life. Dat knowledge may be lost forever...\n\nI do remember more about Ula'tek--or rather, where we might find more information!\n\nI was forced into dis form by de Vilebranch trolls. Dey kept dark knowledge secret from de other tribes, includin' knowledge of Ula'tek.\n\nIf we are to know more, we must go to de Maisara Deeps.", objectives = "" }
WordHunterWoW_QuestEN[92953] = { title = "Memories of Malacrass", description = "While I was a servant of de Vilebranch, I remember discussions about Malacrass's research into Ula'tek.\n\nMalacrass recorded his knowledge in scrolls that he kept with him. Now that he's dead, we need to find out what happened to dem.\n\nDe Vilebranch hex masters won't talk willingly... but if you slay dem, I can use their own necromantic magic against dem to compel dem to speak.", objectives = "" }
WordHunterWoW_QuestEN[92954] = { title = "Maisara Caverns: Master of Souls", description = "Malacrass's notes are with Vordaza, and she's using them to further her necromantic experiments.\n\nI need you to go into de Maisara Caverns to recover them. It will be dangerous, and you will need to gather allies before venturing in.\n\nI will stay here and protect my uncle. We need to sort through all de scrolls we gathered and see what else we can find out.", objectives = "" }
WordHunterWoW_QuestEN[92955] = { title = "The Tablets of Numazon", description = "De ancestors did not bow to a loa--dey claimed a weapon! A weapon dat led to our victory.\n\nI must know more.\n\nYou said de tablets at Numazon are de oldest in Zul'Aman. We can continue de search there. Perhaps de ancient Amani left behind clues for us.\n\nUncle says we should bring de mask. A stray memory might be de key to unlocking dis mystery.", objectives = "" }
WordHunterWoW_QuestEN[92957] = { title = "There's the Rub", description = "If de tablets were made when de Amani first arrived in Zul'Aman, den there must be some clue about Ula'tek here.\n\nDe tablets are too heavy to carry, so Uncle suggested dat we take rubbings of de inscriptions.\n\nI scouted ahead and gathered a few, but I ran into de Vilebranch. I came back here to make sure Uncle was safe.\n\nEnter Numazon and collect more of de rubbings while I watch over Uncle. Watch out for de Vilebranch.", objectives = "" }
WordHunterWoW_QuestEN[92958] = { title = "Brain Drain", description = "I wish I could be more help but... de gaps in my memory. Due to de damage de mask has sustained, dat magic has leaked out for who knows how long.\n\nYou repaired de physical parts of de mask, but de magic within is still weak.\n\nZul'jan says Vilebranch trolls occupy this crypt. De magic dat binds me together is like de magic they use.\n\nYou might be able to help. Retrieve their hex fetishes--I should be able to drain the magic from them.", objectives = "" }
WordHunterWoW_QuestEN[92961] = { title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nSentinel of stone.\nFirst to greet each new neighbor.\nSeek out the deep shade.\n\nGood luck!", objectives = "" }
